@section('scripts')
    <!-- jQuery (required for date range picker and AJAX) -->
    <script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>
    <!-- Moment.js (required for date range picker) -->
    <script src="https://cdn.jsdelivr.net/npm/moment@2.29.4/moment.min.js"></script>
    <!-- Date Range Picker CSS and JS -->
    <link rel="stylesheet" type="text/css" href="https://cdn.jsdelivr.net/npm/daterangepicker/daterangepicker.css" />
    <script type="text/javascript" src="https://cdn.jsdelivr.net/npm/daterangepicker/daterangepicker.min.js"></script>
    <!-- Select2 JS -->
    <script src="https://cdnjs.cloudflare.com/ajax/libs/select2/4.0.13/js/select2.min.js"></script>
    <!-- Select2 Initialization Script -->
    <script>
        // Global function to reinitialize Select2 on a specific element
        window.reinitializeSelect2 = function(elementId, placeholder) {
            const $element = $('#' + elementId);
            if ($element.length) {
                // Destroy existing Select2 if it exists
                if ($element.hasClass("select2-hidden-accessible")) {
                    $element.select2('destroy');
                }
                // Reinitialize Select2
                $element.select2({
                    placeholder: placeholder || "Select an option",
                    allowClear: true,
                    width: '100%'
                });
            }
        };

        /**
         * One in-flight GET + JSON parse per URL. Bulk single-city sync triggers many identical
         * loads; without this Chrome may hit net::ERR_INSUFFICIENT_RESOURCES and services look empty.
         */
        window.fetchJsonDeduped = function (url) {
            if (!window.__fetchJsonInflight) {
                window.__fetchJsonInflight = Object.create(null);
            }
            var inflight = window.__fetchJsonInflight;
            if (inflight[url]) {
                return inflight[url];
            }
            var p = fetch(url).then(function (response) {
                if (!response.ok) {
                    throw new Error('HTTP ' + response.status);
                }
                return response.json();
            });
            inflight[url] = p;
            p.finally(function () {
                delete inflight[url];
            });
            return p;
        };

        // Service city dropdowns (single-city mode: default from main tour city; stays editable)
        window.SERVICE_CITY_SELECTORS = [
            '#hotelCitySelect',
            '#modal_local_transfer_city',
            '#modal_exit_city',
            '.attraction-city-select',
            '.guide-city-select',
            '.restaurant-city-select',
            '.transport-city-select'
        ];

        window.isSingleCityMode = function () {
            return $('input[name="city_mode"]:checked').val() === 'single';
        };

        window.setServiceCityReadonly = function (readonly) {
            const ro = !!readonly;
            window.SERVICE_CITY_SELECTORS.forEach(function (sel) {
                $(sel).each(function () {
                    const $dd = $(this);
                    if (!$dd.length) return;
                    $dd.prop('disabled', ro);
                    // If Select2 is attached, it will reflect disabled state automatically.
                });
            });
        };

        window.getSingleCityName = function () {
            const $sc = $('#single_city');
            if (!$sc.length) return '';

            let txt = '';
            try {
                const data = $sc.select2('data');
                if (data && data.length && data[0].text) {
                    txt = String(data[0].text);
                }
            } catch (e) { /* select2 not ready */ }

            if (!txt) {
                const $opt = $sc.find('option:selected');
                txt = ($opt.text() || '').trim() || String($sc.val() || '');
            }

            return txt.split('(')[0].trim();
        };

        window.getSingleCityMeta = function () {
            const $sc = $('#single_city');
            const selectedVal = String($sc.val() || '').trim();
            let selectedText = window.getSingleCityName() || selectedVal;
            let selectedDataId = '';

            try {
                const data = $sc.select2('data');
                if (data && data.length && data[0]) {
                    if (data[0].text) selectedText = String(data[0].text).split('(')[0].trim();
                    if (data[0].id !== undefined && data[0].id !== null) {
                        selectedDataId = String(data[0].id).trim();
                    }
                }
            } catch (e) { /* select2 not ready */ }

            return {
                value: selectedVal,
                text: selectedText,
                id: selectedDataId
            };
        };

        window.syncAllServiceCities = function (cityName) {
            if (!cityName || !String(cityName).trim()) return;

            const needle = String(cityName).trim();
            // Multi-city: #single_city is cleared — do not use getSingleCityMeta() or matching fails (hotel city stays empty).
            const meta = (typeof window.isSingleCityMode === 'function' && window.isSingleCityMode() && typeof window.getSingleCityMeta === 'function')
                ? window.getSingleCityMeta()
                : { value: needle, text: needle, id: '' };
            const norm = function (s) {
                return String(s || '').trim().toLowerCase();
            };
            const nNeedle = norm(needle);
            const nVal = norm(meta.value);
            const nText = norm(meta.text);
            const nId = norm(meta.id);

            window.SERVICE_CITY_SELECTORS.forEach(function (sel) {
                $(sel).each(function () {
                    const $dd = $(this);
                    if (!$dd.length) return;

                    let matchedVal = null;
                    $dd.find('option').each(function () {
                        const $o = $(this);
                        const v = $o.attr('value');
                        const did = $o.data('id') !== undefined && $o.data('id') !== null ? String($o.data('id')) : '';
                        const t = ($o.text() || '').trim();
                        const tBase = t ? t.split('(')[0].trim() : '';

                        if (v !== undefined && v !== '' && nVal && norm(v) === nVal) {
                            matchedVal = v;
                            return false;
                        }
                        if (did && nId && norm(did) === nId) {
                            matchedVal = (v !== undefined && v !== '') ? v : tBase;
                            return false;
                        }
                        if (tBase && nText && norm(tBase) === nText) {
                            matchedVal = (v !== undefined && v !== '') ? v : tBase;
                            return false;
                        }
                        if (v !== undefined && v !== '' && norm(v) === nNeedle) {
                            matchedVal = v;
                            return false;
                        }
                        if (tBase && norm(tBase) === nNeedle) {
                            matchedVal = (v !== undefined && v !== '') ? v : t;
                            return false;
                        }
                    });

                    if (matchedVal === null) {
                        $dd.append($('<option></option>').attr('value', needle).text(needle));
                        matchedVal = needle;
                    }

                    var prevVal = String($dd.val() || '');
                    var nextVal = String(matchedVal || '');
                    $dd.val(matchedVal);
                    // Only fire change when value actually changes — avoids reload loops (XHR → DOM → sync again).
                    if (prevVal !== nextVal) {
                        $dd.trigger('change');
                    }
                });
            });
        };

        // Multi-city helper: services bundle lives inside the active ".segment".
        // When user clicks "Add more" inside services, newly added city dropdowns must inherit the active segment city.
        window.getActiveSegmentCityLabelForServices = function () {
            try {
                if ($('input[name="city_mode"]:checked').val() !== 'multi') return '';
                const $bundle = $('#segmentServicesBundle');
                if (!$bundle.length) return '';
                const $seg = $bundle.closest('.segment');
                if (!$seg.length) return '';
                const $opt = $seg.find('.city-select option:selected');
                const cityName = ($opt.data('city-name') || '').toString().trim();
                const cityText = ($opt.text() || '').toString().trim();
                return (cityName || cityText.split('(')[0].trim() || '').trim();
            } catch (e) {
                return '';
            }
        };

        // Single-city mode: default tour city onto service city fields only (editable; never lock/disabled).
        window.syncSingleCityToAllServices = function () {
            if (!window.isSingleCityMode()) {
                return;
            }
            const city = window.getSingleCityName();
            if (city) {
                window.syncAllServiceCities(city);
            } else {
                window.SERVICE_CITY_SELECTORS.forEach(function (sel) {
                    $(sel).each(function () {
                        $(this).val('').trigger('change');
                    });
                });
            }
        };

        let _syncSingleCityDebounce = null;
        window.scheduleSyncSingleCityToAllServices = function () {
            clearTimeout(_syncSingleCityDebounce);
            _syncSingleCityDebounce = setTimeout(function () {
                if (typeof window.syncSingleCityToAllServices === 'function') {
                    window.syncSingleCityToAllServices();
                }
            }, 100);
        };

        $(document).ready(function() {
            // Initialize Select2 for all static select fields
            
            // Country Select
            $('#user_country').select2({
                placeholder: "Choose a country...",
                allowClear: true,
                width: '100%'
            });

            // City dropdown (Single City mode)
            $('#single_city').select2({
                placeholder: "Select city...",
                allowClear: true,
                width: '100%',
                ajax: {
                    url: "{{ route('ajax.cities') }}",
                    dataType: 'json',
                    delay: 200,
                    data: function (params) {
                        return { q: params.term || '' };
                    },
                    processResults: function (data) {
                        return data;
                    },
                    cache: true
                }
            });

            $('#single_city').on('change select2:select select2:clear', function () {
                window.syncSingleCityToAllServices();
            });

            // Master cities (Multi City mode)
            $('#multi_cities').select2({
                placeholder: "Select cities...",
                allowClear: true,
                width: '100%',
                ajax: {
                    url: "{{ route('ajax.cities') }}",
                    dataType: 'json',
                    delay: 200,
                    data: function (params) {
                        return { q: params.term || '' };
                    },
                    processResults: function (data) {
                        return data;
                    },
                    cache: true
                }
            });

            function toISODate(s) {
                // expects YYYY-MM-DD
                return s ? new Date(s + 'T00:00:00') : null;
            }

            function isWithinMainRange(start, end) {
                const mainStart = toISODate($('#start_date').val());
                const mainEnd = toISODate($('#end_date').val());
                const segStart = toISODate(start);
                const segEnd = toISODate(end);

                if (!mainStart || !mainEnd || !segStart || !segEnd) return false;
                return segStart >= mainStart && segEnd <= mainEnd && segStart <= segEnd;
            }

            function applySegmentDateLimits() {
                const min = $('#start_date').val() || '';
                const max = $('#end_date').val() || '';
                if (!min || !max) return;

                $('#segmentsWrapper .start-date').attr({ min: min, max: max });
                $('#segmentsWrapper .end-date').attr({ min: min, max: max });
            }

            function getMasterCities() {
                return ($('#multi_cities').val() || []).map(String);
            }

            function rebuildSegmentCityOptions($select) {
                const selected = $select.val() || '';
                const master = getMasterCities();
                let html = '<option value="">Select city...</option>';

                // Use Select2 selected data for nicer labels when available
                const data = $('#multi_cities').select2('data') || [];
                const labelById = {};
                const countryById = {};
                data.forEach(function (item) {
                    labelById[String(item.id)] = item.text;
                    if (item.country) {
                        countryById[String(item.id)] = item.country;
                    }
                });

                const escAttr = function (s) {
                    return String(s || '').replace(/&/g, '&amp;').replace(/"/g, '&quot;');
                };

                master.forEach(function (id) {
                    const label = labelById[id] || id;
                    const cityName = String(label).split('(')[0].trim();
                    const ctry = countryById[id] || '';
                    html += `<option value="${id}" data-city-name="${escAttr(cityName)}" data-country="${escAttr(ctry)}">${label}</option>`;
                });

                $select.html(html);
                if (selected && master.includes(String(selected))) {
                    $select.val(selected);
                } else {
                    $select.val('');
                }
            }

            function isServicesAccordionInSegment() {
                return $('#segmentServicesBundle').closest('.segment-services').length > 0;
            }

            window.multiSegmentStayRange = null;

            function clearMultiSegmentStayContext() {
                window.multiSegmentStayRange = null;
            }

            function freezeServicesBundleInSegment($segment) {
                const $bundle = $('#segmentServicesBundle');
                if (!$segment || !$segment.length || !$bundle.length) return;
                if (!$segment.find('#segmentServicesBundle').length) return; // bundle not currently inside this segment
                if ($segment.find('.segment-services-frozen').length) return; // already frozen snapshot exists

                const $clone = $bundle.clone(false, false);

                // Avoid duplicate IDs / aria references in the snapshot copy.
                // Root must lose id — otherwise #segmentServicesBundle exists twice and
                // getElementById / document.querySelector hit the frozen row (first city) instead of the live bundle.
                $clone.removeAttr('id');
                $clone.find('[id]').removeAttr('id');
                $clone.find('label[for]').removeAttr('for');

                // Make it read-only (visual snapshot).
                $clone.find('input, select, textarea, button').prop('disabled', true);
                $clone.addClass('segment-services-frozen');
                $clone.css({ pointerEvents: 'none', opacity: 0.92 });

                // Add a small header note (kept minimal to avoid layout shift).
                $clone.prepend(
                    $('<div class="mb-2 text-muted"></div>').css({ fontSize: '0.72rem' }).html(
                        '<i class="ri-lock-line me-1"></i>Saved services for this city plan (read-only). Select this plan again to edit.'
                    )
                );

                $segment.find('.segment-services').append($clone);
            }

            /** Badges next to Hotel Accommodations: segment stay (e.g. 01 Mar – 05 Mar, 2026), not full tour. */
            function applySegmentStayDateBadges(startStr, endStr) {
                const s = moment(startStr, 'YYYY-MM-DD');
                const e = moment(endStr, 'YYYY-MM-DD');
                if (!s.isValid() || !e.isValid()) return;
                const y = e.format('YYYY');
                $('#tourDates').text(s.format('DD MMM') + ' – ' + e.format('DD MMM') + ', ' + y);
                $('#hotelNights').text(e.diff(s, 'days') + ' nights · this stay');
            }

            /** After city plan is set: fill hotel/port/attraction/guide/restaurant/transport city selects; retry for async DOM. */
            function resyncSegmentCityToAllServiceSelects(cityLabel) {
                if (!cityLabel || typeof window.syncAllServiceCities !== 'function') return;
                window.syncAllServiceCities(cityLabel);
                [120, 400, 800].forEach(function (ms) {
                    setTimeout(function () { window.syncAllServiceCities(cityLabel); }, ms);
                });
            }

            /** Multi-city: hide global services until a segment has city + dates; single-city always shows global block. */
            function refreshGlobalServicesVisibility() {
                const multi = $('input[name="city_mode"]:checked').val() === 'multi';
                const $bundle = $('#segmentServicesBundle');
                const $hint = $('#multiCityServicesHint');
                if (!$hint.length || !$bundle.length) return;

                if (!multi) {
                    if (typeof window.setServiceCityReadonly === 'function') {
                        window.setServiceCityReadonly(false);
                    }
                    clearMultiSegmentStayContext();
                    $bundle.removeClass('d-none');
                    $hint.addClass('d-none');
                    if (typeof window.generateNightSelection === 'function') {
                        window.generateNightSelection();
                    }
                    if (typeof window.updateNightDisplay === 'function') {
                        window.updateNightDisplay();
                    }
                    return;
                }

                if (isServicesAccordionInSegment()) {
                    if (typeof window.setServiceCityReadonly === 'function') {
                        window.setServiceCityReadonly(true);
                    }
                    $bundle.removeClass('d-none');
                    $hint.addClass('d-none');
                } else {
                    if (typeof window.setServiceCityReadonly === 'function') {
                        window.setServiceCityReadonly(false);
                    }
                    clearMultiSegmentStayContext();
                    $bundle.addClass('d-none');
                    $hint.removeClass('d-none');
                    const s = $('#start_date').val();
                    const e = $('#end_date').val();
                    if (s && e && typeof moment !== 'undefined') {
                        const ms = moment(s, 'YYYY-MM-DD');
                        const me = moment(e, 'YYYY-MM-DD');
                        if (ms.isValid() && me.isValid()) {
                            $('#tourDates').text(ms.format('DD MMM') + ' – ' + me.format('DD MMM') + ', ' + me.format('YYYY'));
                            $('#hotelNights').text(me.diff(ms, 'days') + ' nights · full tour');
                        }
                    }
                    const tdc = document.getElementById('transportDayCount');
                    if (tdc && s && e && typeof moment !== 'undefined') {
                        const ms = moment(s, 'YYYY-MM-DD');
                        const me = moment(e, 'YYYY-MM-DD');
                        if (ms.isValid() && me.isValid()) {
                            tdc.textContent = (me.diff(ms, 'days') + 1) + ' days · full tour';
                        }
                    }
                    if (typeof window.generateNightSelection === 'function') {
                        window.generateNightSelection();
                    }
                    if (typeof window.updateNightDisplay === 'function') {
                        window.updateNightDisplay();
                    }
                }
            }

            function setCityMode(mode) {
                const isMulti = mode === 'multi';
                $('#multiCityControls').toggleClass('d-none', !isMulti);

                // Single-city inputs shown/hidden
                $('#single_city').closest('.col-md-6, .col-md-2, .col-12').toggleClass('d-none', isMulti);

                // main travel_dates MUST stay visible in both modes (main range constraint)
                // so do nothing here; segments validate against #start_date/#end_date.
                refreshGlobalServicesVisibility();
            }

            function clearTourPackageHeaderFields() {
                // Reference number
                $('#reference_number').val('');

                // Travel dates
                $('#travel_dates').val('');
                $('#start_date').val('');
                $('#end_date').val('');

                // Reset daterangepicker internal state (otherwise UI can look "stuck" after mode switch)
                try {
                    const $td = $('#travel_dates');
                    const drp = $td.data('daterangepicker');
                    if (drp && typeof moment !== 'undefined') {
                        drp.setStartDate(moment());
                        drp.setEndDate(moment());
                        $td.val('');
                    }
                } catch (e) { /* ignore */ }

                // Reset global travel date vars used across services
                try {
                    if (typeof tourStartDate !== 'undefined') tourStartDate = null;
                    if (typeof tourEndDate !== 'undefined') tourEndDate = null;
                    if (typeof tourNights !== 'undefined') tourNights = 0;
                } catch (e) { /* ignore */ }

                // Reset header badges that depend on tour range
                try {
                    const tdEl = document.getElementById('tourDates');
                    const hnEl = document.getElementById('hotelNights');
                    if (tdEl) tdEl.textContent = '';
                    if (hnEl) hnEl.textContent = '0 Nights Selected';
                    const ns = document.getElementById('nightSelection');
                    if (ns) ns.innerHTML = '';
                } catch (e) { /* ignore */ }

                // City selects
                if ($('#single_city').length) {
                    $('#single_city').val(null).trigger('change');
                }
                if ($('#multi_cities').length) {
                    $('#multi_cities').val(null).trigger('change');
                }

                // Agency + Agent
                if ($('#agency_id').length) {
                    $('#agency_id').val(null).trigger('change');
                }
                if ($('#agent_id').length) {
                    $('#agent_id').val(null).trigger('change');
                }

                // Guests: reset to defaults
                $('#adults').val('1');
                $('#male').val('0');
                $('#female').val('0');
                $('#children').val('0');
                $('#infants').val('0');
                $('#child_ages').val('[]');

                // Clear additional guest cards (they depend on pax)
                try {
                    const agc = document.getElementById('additionalGuestsContainer');
                    if (agc) agc.innerHTML = '';
                    if (typeof additionalGuestCount !== 'undefined') additionalGuestCount = 0;
                    if (typeof window.updateGuestLimitInfo === 'function') {
                        window.updateGuestLimitInfo();
                    } else if (typeof updateGuestLimitInfo === 'function') {
                        updateGuestLimitInfo();
                    }
                } catch (e) { /* ignore */ }

                // Refresh guest summary UI if helper exists
                try {
                    if (typeof window.updateGuestSummary === 'function') {
                        window.updateGuestSummary();
                    } else if (typeof updateGuestSummary === 'function') {
                        updateGuestSummary();
                    } else if (typeof window.updateMainGuestSummary === 'function') {
                        window.updateMainGuestSummary();
                    } else if (typeof updateMainGuestSummary === 'function') {
                        updateMainGuestSummary();
                    }
                } catch (e) { /* ignore */ }
            }

            function clearCityModeUIState() {
                if ($('#multi_cities').length) {
                    $('#multi_cities').val(null).trigger('change');
                }
                $('#segmentsWrapper').empty();
                segmentIndex = 0;

                if (window.__segmentBundleDomByIdx) window.__segmentBundleDomByIdx = {};
                if (window.__segmentServiceState) window.__segmentServiceState = {};
                if (window.__segmentServiceMeta) window.__segmentServiceMeta = {};

                clearMultiSegmentStayContext();

                const $bundle = $('#segmentServicesBundle');
                const $home = $('#servicesAccordionHome');
                if ($bundle.length && $home.length) {
                    $home.after($bundle);
                }

                $('.service-grid').empty();
            }

            function resetTourPackageCityMode(mode) {
                // Full reset of Tour Package Configuration when switching city mode
                clearTourPackageHeaderFields();
                clearCityModeUIState();

                if (mode === 'multi') {
                    // Switching to multi: clear single-city selection
                    if ($('#single_city').length) {
                        $('#single_city').val(null).trigger('change');
                    }
                } else {
                    refreshGlobalServicesVisibility();
                }
            }

            $(document).on('change', 'input[name="city_mode"]', function () {
                const mode = $(this).val();
                resetTourPackageCityMode(mode);
                setCityMode(mode);
                window.syncSingleCityToAllServices();
            });

            // default mode
            setCityMode('single');
            window.syncSingleCityToAllServices();

            // Multi-city segments
            let segmentIndex = 0;

            function updateAddCityPlanButtonState() {
                const $btn = $('#addCityPlan');
                if (!$btn.length) return;

                const isNonEmpty = (v) => String(v ?? '').trim() !== '';

                const startOk = isNonEmpty($('#start_date').val());
                const endOk = isNonEmpty($('#end_date').val());
                const datesOk = startOk && endOk;

                const adults = parseInt(String($('#adults').val() ?? '0'), 10) || 0;
                const children = parseInt(String($('#children').val() ?? '0'), 10) || 0;
                const guestsOk = (adults + children) > 0;

                const agencyOk = isNonEmpty($('#agency_id').val());
                const agentOk = isNonEmpty($('#agent_id').val());

                const mode = String($('input[name="city_mode"]:checked').val() || 'single');
                const cityOk = (mode === 'multi')
                    ? ((Array.isArray($('#multi_cities').val()) ? $('#multi_cities').val() : []) || []).length > 0
                    : isNonEmpty($('#single_city').val());

                const ok = datesOk && guestsOk && agencyOk && agentOk && cityOk;

                $btn.prop('disabled', !ok);
                $btn.attr('title', ok ? '' : 'Fill travel dates, guests, agency, agent, and city first.');
            }
            // Expose so other script blocks (date picker, etc.) can refresh state
            window.updateAddCityPlanButtonState = updateAddCityPlanButtonState;

            // Keep Add City Plan disabled until required fields filled
            updateAddCityPlanButtonState();
            $(document).on('change input', [
                '#start_date',
                '#end_date',
                '#adults',
                '#children',
                '#agency_id',
                '#agent_id',
                '#single_city',
                '#multi_cities',
                'input[name="city_mode"]'
            ].join(','), function () {
                updateAddCityPlanButtonState();
            });

            $('#addCityPlan').on('click', function () {
                const master = getMasterCities();
                if (!master.length) {
                    alert('Please select cities in the master list first.');
                    return;
                }

                segmentIndex++;

                const segmentHTML = `
                <div class="card mt-2 segment border-0 shadow-sm" data-index="${segmentIndex}" style="border-radius: 10px;">
                    <div class="card-body py-2 px-2 position-relative segment-topbar">
                        <div class="row g-2">
                            <div class="col-md-5">
                                <label class="form-label fw-semibold mb-1" style="color:#495057; font-size:0.72rem;">City (this stay)</label>
                                <select class="form-select form-select-sm city-select" name="segments[${segmentIndex}][city]" style="height: 40px;">
                                    <option value="">Select city...</option>
                                </select>
                            </div>

                            <div class="col-md-3">
                                <label class="form-label fw-semibold mb-1" style="color:#495057; font-size:0.72rem;">Stay from</label>
                                <input type="date" class="form-control form-control-sm start-date" name="segments[${segmentIndex}][start_date]" style="height: 40px;" title="Must be on or after main tour start">
                            </div>

                            <div class="col-md-3">
                                <label class="form-label fw-semibold mb-1" style="color:#495057; font-size:0.72rem;">Stay until</label>
                                <input type="date" class="form-control form-control-sm end-date" name="segments[${segmentIndex}][end_date]" style="height: 40px;" title="Must be on or before main tour end">
                            </div>

                            <div class="col-md-1 d-flex align-items-end justify-content-end">
                                <button type="button"
                                    class="btn btn-outline-danger btn-sm removeSegment d-flex align-items-center justify-content-center gap-1"
                                    title="Remove plan"
                                    style="height: 40px; width: 100%; border-radius: 10px; padding: 0 10px;">
                                    <i class="ri-close-line"></i>
                                    <span style="font-size:0.72rem;">Remove</span>
                                </button>
                            </div>
                        </div>

                        <div class="segment-header mt-2 d-none">
                            <div class="d-flex align-items-center justify-content-between px-2 py-1 rounded"
                                style="background:#f8f9fa;border:1px solid #e9ecef;pointer-events:none;">
                                <div class="d-flex flex-column">
                                    <div class="fw-semibold segment-title" style="font-size:0.78rem;color:#495057;"></div>
                                    <div class="text-muted segment-range" style="font-size:0.75rem;"></div>
                                </div>
                                <button class="btn btn-sm btn-outline-secondary segment-body-toggle"
                                    type="button"
                                    data-bs-toggle="collapse"
                                    data-bs-target="#segmentBodyCollapse_${segmentIndex}"
                                    aria-expanded="false"
                                    aria-controls="segmentBodyCollapse_${segmentIndex}"
                                    style="height:26px;line-height:1;padding:0 8px;border-radius:8px;pointer-events:auto;">
                                    <i class="ri-arrow-down-s-line"></i>
                                </button>
                            </div>
                        </div>

                        <div id="segmentBodyCollapse_${segmentIndex}" class="collapse segment-body-collapse mt-2">
                            <div class="segment-services">
                                <div class="segment-services-banner alert alert-light border py-1 px-2 mb-2 d-none" style="font-size:0.74rem;">
                                    <i class="ri-layout-grid-line me-1 text-primary"></i><span class="fw-semibold">All services for this stay</span> (hotels, arrival/departure, attractions, guides, restaurants, transport) — scoped to the city and dates on this row.
                                </div>
                            </div>
                            <div class="service-grid mt-2"></div>
                        </div>
                    </div>
                </div>`;

                $('#segmentsWrapper').append(segmentHTML);

                const $newCitySelect = $('#segmentsWrapper .segment:last .city-select');
                rebuildSegmentCityOptions($newCitySelect);

                // Disable dates outside main tour range
                applySegmentDateLimits();
            });

            $(document).on('click', '.removeSegment', function () {
                const $seg = $(this).closest('.segment');
                const rmKey = $seg.length ? String($seg.data('index')) : '';
                if (rmKey && window.__segmentServiceState && window.__segmentServiceState[rmKey]) {
                    delete window.__segmentServiceState[rmKey];
                }
                const $bundle = $('#segmentServicesBundle');
                if ($bundle.length && $seg.find('#segmentServicesBundle').length) {
                    $('#servicesAccordionHome').after($bundle);
                    clearMultiSegmentStayContext();
                }
                $seg.remove();
                refreshGlobalServicesVisibility();
            });

            // When master list changes, update all segment dropdown options
            $('#multi_cities').on('change', function () {
                $('#segmentsWrapper .city-select').each(function () {
                    rebuildSegmentCityOptions($(this));
                });
            });

            // Load services grid dynamically per segment when city+dates valid and within main range
            $(document).on('change', '.city-select, .start-date, .end-date', function () {
                const $segment = $(this).closest('.segment');
                const city = $segment.find('.city-select').val();
                const start = $segment.find('.start-date').val();
                const end = $segment.find('.end-date').val();
                let segmentCityLabelForAjax = '';

                // Avoid toast spam when we restore a previous valid range
                if ($segment.data('suppressSegmentDateCheck')) {
                    $segment.data('suppressSegmentDateCheck', false);
                    return;
                }

                if (!(city && start && end)) {
                    if ($('input[name="city_mode"]:checked').val() === 'multi') {
                        $segment.find('.segment-services-banner').addClass('d-none');
                        const $bundle = $('#segmentServicesBundle');
                        if ($bundle.length && $segment.find('#segmentServicesBundle').length) {
                            $segment.find('.service-grid').empty();
                            $('#servicesAccordionHome').after($bundle);
                            // Keep any frozen snapshot (do not remove); it's the segment's saved view.
                            clearMultiSegmentStayContext();
                            refreshGlobalServicesVisibility();
                        }
                    }
                    return;
                }

                // Block overlapping city stays (hotel-night logic). Allow only boundary touch:
                // e.g. City A 10→12 and City B 12→14 is OK, but B 11→14 is NOT.
                // We treat stays as [start, end) so checkout day (end) can be shared.
                if (typeof moment !== 'undefined') {
                    const curIdx = String($segment.data('index') || '');
                    if (!window.__segmentLastValidRange) window.__segmentLastValidRange = {};

                    const ms = moment(start, 'YYYY-MM-DD', true);
                    const me = moment(end, 'YYYY-MM-DD', true);
                    if (ms.isValid() && me.isValid()) {
                        let overlaps = false;

                        $('#segmentsWrapper .segment').each(function () {
                            const $o = $(this);
                            const oIdx = String($o.data('index') || '');
                            if (!oIdx || oIdx === curIdx) return;

                            const oStart = $o.find('.start-date').val();
                            const oEnd = $o.find('.end-date').val();
                            if (!(oStart && oEnd)) return;

                            const os = moment(oStart, 'YYYY-MM-DD', true);
                            const oe = moment(oEnd, 'YYYY-MM-DD', true);
                            if (!os.isValid() || !oe.isValid()) return;

                            // overlap if start < otherEnd AND end > otherStart (end exclusive)
                            if (ms.isBefore(oe, 'day') && me.isAfter(os, 'day')) {
                                overlaps = true;
                            }
                        });

                        if (overlaps) {
                            const prev = window.__segmentLastValidRange[curIdx];
                            const msg = 'These dates overlap another city plan.';

                            if (typeof showNotification === 'function') {
                                // Show only once for the same invalid attempt.
                                try {
                                    const toastKey = `${curIdx}|${start}|${end}`;
                                    const now = Date.now();
                                    const last = window.__segmentOverlapToastLast || {};
                                    if (last.key !== toastKey || !last.ts || (now - last.ts) > 2500) {
                                        showNotification(msg, 'error');
                                        window.__segmentOverlapToastLast = { key: toastKey, ts: now };
                                    }
                                } catch (e) {
                                    showNotification(msg, 'error');
                                }
                            }

                            // Restore last valid dates (or clear end date if none)
                            $segment.data('suppressSegmentDateCheck', true);
                            if (prev && prev.start && prev.end) {
                                $segment.find('.start-date').val(prev.start);
                                $segment.find('.end-date').val(prev.end);
                            } else {
                                $segment.find('.end-date').val('');
                            }

                            $segment.find('.service-grid').html(
                                '<div class="alert alert-danger mb-0"><strong>These dates overlap another city plan.</strong> Only checkout/check-in on the same date is allowed.</div>'
                            );
                            $segment.find('.segment-services-banner').addClass('d-none');
                            const $bundleBad = $('#segmentServicesBundle');
                            if ($bundleBad.length && $segment.find('#segmentServicesBundle').length) {
                                $('#servicesAccordionHome').after($bundleBad);
                            }
                            clearMultiSegmentStayContext();
                            refreshGlobalServicesVisibility();
                            return;
                        }
                    }
                }

                if (!isWithinMainRange(start, end)) {
                    $segment.find('.service-grid').html(
                        '<div class="alert alert-warning mb-0">Stay dates must fall inside your main <strong>Travel dates</strong> (tour start → tour end).</div>'
                    );
                    $segment.find('.segment-services-banner').addClass('d-none');
                    const $bundleBad = $('#segmentServicesBundle');
                    if ($bundleBad.length && $segment.find('#segmentServicesBundle').length) {
                        $('#servicesAccordionHome').after($bundleBad);
                    }
                    // Keep any frozen snapshot (do not remove).
                    clearMultiSegmentStayContext();
                    refreshGlobalServicesVisibility();
                    return;
                }

                // Save last valid range for restore on overlap attempt
                try {
                    const idxStore = String($segment.data('index') || '');
                    if (idxStore) {
                        if (!window.__segmentLastValidRange) window.__segmentLastValidRange = {};
                        window.__segmentLastValidRange[idxStore] = { start: start, end: end };
                    }
                } catch (e) { /* ignore */ }

                // Show city/date header and place services UI under this segment (Multi City)
                if ($('input[name="city_mode"]:checked').val() === 'multi') {
                    const $opt = $segment.find('.city-select option:selected');
                    const cityName = ($opt.data('city-name') || '').toString().trim();
                    const cityText = ($opt.text() || '').trim();
                    segmentCityLabelForAjax = cityName || cityText.split('(')[0].trim();

                    $segment.find('.segment-title').text(cityText || 'Selected City');
                    const mStart = moment(start, 'YYYY-MM-DD');
                    const mEnd = moment(end, 'YYYY-MM-DD');
                    if (mStart.isValid() && mEnd.isValid()) {
                        $segment.find('.segment-range').text(
                            mStart.format('DD MMM') + ' – ' + mEnd.format('DD MMM YYYY')
                        );
                    } else {
                        $segment.find('.segment-range').text(start + ' → ' + end);
                    }
                    $segment.find('.segment-header').removeClass('d-none');
                    $segment.find('.segment-services-banner').removeClass('d-none');

                    // Ensure the segment body (services + grid) is opened when the plan becomes valid.
                    const $collapse = $segment.find('.segment-body-collapse');
                    if ($collapse.length) {
                        $collapse.addClass('show');
                        $segment.find('.segment-body-toggle').attr('aria-expanded', 'true');
                    }

                    window.multiSegmentStayRange = { start: start, end: end };

                    const $bundle = $('#segmentServicesBundle');
                    const $svcHost = $segment.find('.segment-services');
                    if ($bundle.length && $svcHost.length) {
                        // If the bundle is currently attached to another segment, leave behind a read-only snapshot there.
                        const $prevSegment = $bundle.closest('.segment');
                        if ($prevSegment.length && !$prevSegment.is($segment)) {
                            if (typeof window.saveMultiSegmentServiceState === 'function') {
                                window.saveMultiSegmentServiceState($prevSegment);
                            }
                            freezeServicesBundleInSegment($prevSegment);
                        }

                        // If this segment had a previous snapshot, remove it (we are activating live editing here).
                        $segment.find('.segment-services-frozen').remove();

                        $svcHost.append($bundle);
                        $bundle.removeClass('d-none');

                        if (typeof window.restoreMultiSegmentServiceState === 'function') {
                            window.restoreMultiSegmentServiceState($segment);
                        }

                        applySegmentStayDateBadges(start, end);
                        if (typeof window.setServiceCityReadonly === 'function') {
                            window.setServiceCityReadonly(true);
                        }

                        if (typeof generateDailyServices === 'function') {
                            generateDailyServices();
                        }
                        // After DOM regeneration, restore field selections for this segment again.
                        if (typeof window.restoreMultiSegmentServiceState === 'function') {
                            window.restoreMultiSegmentServiceState($segment);
                        }
                        resyncSegmentCityToAllServiceSelects(segmentCityLabelForAjax);
                        if (typeof window.updateAttractionSectionSummary === 'function') {
                            window.updateAttractionSectionSummary(1);
                            const r = window.multiSegmentStayRange;
                            if (r && r.start && r.end && typeof moment !== 'undefined') {
                                const td = moment(r.end).diff(moment(r.start), 'days') + 1;
                                if (td > 1) {
                                    window.updateAttractionSectionSummary(td);
                                }
                            }
                        }
                        if (typeof window.updateGuideSectionSummary === 'function') {
                            window.updateGuideSectionSummary(1);
                            const r = window.multiSegmentStayRange;
                            if (r && r.start && r.end && typeof moment !== 'undefined') {
                                const td = moment(r.end).diff(moment(r.start), 'days') + 1;
                                if (td > 1) {
                                    window.updateGuideSectionSummary(td);
                                }
                            }
                        }
                        if (typeof window.updateRestaurantSectionSummary === 'function') {
                            window.updateRestaurantSectionSummary(1);
                            const r = window.multiSegmentStayRange;
                            if (r && r.start && r.end && typeof moment !== 'undefined') {
                                const td = moment(r.end).diff(moment(r.start), 'days') + 1;
                                if (td > 1) {
                                    window.updateRestaurantSectionSummary(td);
                                }
                            }
                        }
                        if (typeof window.generateNightSelection === 'function') {
                            window.generateNightSelection();
                        }
                        if (typeof window.updateNightDisplay === 'function') {
                            window.updateNightDisplay();
                        }
                    }
                    refreshGlobalServicesVisibility();
                }

                $.ajax({
                    url: "{{ url('/get-services') }}",
                    type: 'GET',
                    data: { city: city, start_date: start, end_date: end },
                    success: function (res) {
                        $segment.find('.service-grid').html(res);
                        if ($('input[name="city_mode"]:checked').val() === 'multi' && segmentCityLabelForAjax) {
                            if (typeof generateDailyServices === 'function') {
                                generateDailyServices();
                            }
                            if (typeof window.restoreMultiSegmentServiceState === 'function') {
                                window.restoreMultiSegmentServiceState($segment);
                            }
                            resyncSegmentCityToAllServiceSelects(segmentCityLabelForAjax);
                            if (typeof window.updateAttractionSectionSummary === 'function') {
                                window.updateAttractionSectionSummary(1);
                                const r = window.multiSegmentStayRange;
                                if (r && r.start && r.end && typeof moment !== 'undefined') {
                                    const td = moment(r.end).diff(moment(r.start), 'days') + 1;
                                    if (td > 1) {
                                        window.updateAttractionSectionSummary(td);
                                    }
                                }
                            }
                            if (typeof window.updateGuideSectionSummary === 'function') {
                                window.updateGuideSectionSummary(1);
                                const r = window.multiSegmentStayRange;
                                if (r && r.start && r.end && typeof moment !== 'undefined') {
                                    const td = moment(r.end).diff(moment(r.start), 'days') + 1;
                                    if (td > 1) {
                                        window.updateGuideSectionSummary(td);
                                    }
                                }
                            }
                            if (typeof window.updateRestaurantSectionSummary === 'function') {
                                window.updateRestaurantSectionSummary(1);
                                const r = window.multiSegmentStayRange;
                                if (r && r.start && r.end && typeof moment !== 'undefined') {
                                    const td = moment(r.end).diff(moment(r.start), 'days') + 1;
                                    if (td > 1) {
                                        window.updateRestaurantSectionSummary(td);
                                    }
                                }
                            }
                            if (typeof generateNightSelection === 'function') {
                                generateNightSelection();
                            }
                            if (typeof updateNightDisplay === 'function') {
                                updateNightDisplay();
                            }
                        }
                    },
                    error: function () {
                        $segment.find('.service-grid').html(
                            '<div class="alert alert-danger mb-0">Failed to load services.</div>'
                        );
                    }
                });
            });

            // Re-apply date limits whenever main tour dates change
            $('#travel_dates').on('apply.daterangepicker', function () {
                applySegmentDateLimits();
                refreshGlobalServicesVisibility();
            });
            
            // Store previous country value for Select2
            let previousCountrySelect2 = $('#user_country').val() || '';
            
            // Handle country change with Select2
            $('#user_country').on('change', function() {
                const selectedCountry = $(this).val() || '';
                const oldCountry = previousCountrySelect2;
                previousCountrySelect2 = selectedCountry;
                
                console.log('Country changed (Select2) from:', oldCountry, 'to:', selectedCountry);
                
                // If country actually changed (not just initial load), clear all services
                if (oldCountry && oldCountry !== selectedCountry && selectedCountry) {
                    if (typeof clearAllSelectedServices === 'function') {
                        clearAllSelectedServices();
                    }
                }
                
                // Get country ID from selected option and fetch cities/ports
                if (selectedCountry) {
                    const selectedOption = $(this).find('option:selected');
                    const countryId = selectedOption.data('country-id') || selectedOption.attr('data-country-id');
                    
                    console.log('Selected country (Select2):', selectedCountry, 'Country ID:', countryId);
                    
                    // Populate cities for the selected country
                    if (typeof populateAllCityDropdowns === 'function') {
                        populateAllCityDropdowns(selectedCountry);
                    }
                    
                    // Fetch ports for the selected country using country ID
                    if (countryId && typeof fetchPortsByCountry === 'function') {
                        fetchPortsByCountry(countryId);
                    } else if (!countryId) {
                        console.warn('Country ID not found for country:', selectedCountry);
                    }
                } else {
                    // Clear ports when country is cleared
                    if (typeof clearAllPortDropdowns === 'function') {
                        clearAllPortDropdowns();
                    }
                }
            });
            
            // Trigger change event if country is pre-selected (for Select2)
            const initialCountry = $('#user_country').val();
            if (initialCountry) {
                // Small delay to ensure Select2 is fully initialized
                setTimeout(function() {
                    $('#user_country').trigger('change');
                }, 100);
            }
            
            // Agency Select
            $('#agency_id').select2({
                placeholder: "Choose agency...",
                allowClear: true,
                width: '100%'
            });
            
            // Agent Select
            $('#agent_id').select2({
                placeholder: "Choose agent...",
                allowClear: true,
                width: '100%'
            });
            
            // Accordion arrow icon rotation
            $('#servicesAccordion').on('show.bs.collapse', function (e) {
                const target = $(e.target);
                const header = target.prev('.card-header');
                const arrow = header.find('i[class*="ri-arrow"]');
                arrow.removeClass('ri-arrow-down-s-line').addClass('ri-arrow-up-s-line');
            });
            
            $('#servicesAccordion').on('hide.bs.collapse', function (e) {
                const target = $(e.target);
                const header = target.prev('.card-header');
                const arrow = header.find('i[class*="ri-arrow"]');
                arrow.removeClass('ri-arrow-up-s-line').addClass('ri-arrow-down-s-line');
            });
            
            // Inner accordion arrow icon rotation (for services inside transport section)
            $(document).on('show.bs.collapse', '#servicesAccordionInner .collapse', function (e) {
                const target = $(e.target);
                const header = target.prev('.card-header');
                const arrow = header.find('i[class*="ri-arrow"]');
                arrow.removeClass('ri-arrow-down-s-line').addClass('ri-arrow-up-s-line');
            });
            
            $(document).on('hide.bs.collapse', '#servicesAccordionInner .collapse', function (e) {
                const target = $(e.target);
                const header = target.prev('.card-header');
                const arrow = header.find('i[class*="ri-arrow"]');
                arrow.removeClass('ri-arrow-up-s-line').addClass('ri-arrow-down-s-line');
            });

            // One accordion open at a time (scoped): only within the main services accordions.
            // Do NOT affect per-city-plan wrapper accordion (segmentFullCollapse_*).
            $(document).on('show.bs.collapse', '#servicesAccordion .collapse, #servicesAccordionInner .collapse', function (e) {
                var $opening = $(e.target);
                $('#servicesAccordion .collapse, #servicesAccordionInner .collapse')
                    .not($opening)
                    .filter('.show')
                    .collapse('hide');
            });
            $(document).on('show.bs.collapse', '#servicesAccordion .collapse, #servicesAccordionInner .collapse', function (e) {
                $(e.target).prev('.card-header').find('i[class*="ri-arrow"]').removeClass('ri-arrow-down-s-line').addClass('ri-arrow-up-s-line');
            });
            $(document).on('hide.bs.collapse', '#servicesAccordion .collapse, #servicesAccordionInner .collapse', function (e) {
                $(e.target).prev('.card-header').find('i[class*="ri-arrow"]').removeClass('ri-arrow-up-s-line').addClass('ri-arrow-down-s-line');
            });

            // Hotel City Select
            $('#hotelCitySelect').select2({
                placeholder: "Select country first",
                allowClear: true,
                width: '100%'
            });
            
            // Handle hotel city change event with Select2
            $('#hotelCitySelect').on('change', function() {
                const selectedCity = $(this).val();
                const hotelSelect = document.getElementById('hotelSelect');
                const hotelLoadingStatus = document.getElementById('hotelLoadingStatus');
                const cityMessage = document.getElementById('hotelCityMessage');
                
                if (selectedCity) {
                    // Enable hotel selection and load hotels
                    hotelSelect.disabled = false;
                    $('#hotelSelect').prop('disabled', false); // Enable Select2
                    cityMessage.style.display = 'none';
                    
                    // Call loadHotelsForCity function (check if it exists)
                    if (typeof window.loadHotelsForCity === 'function') {
                        window.loadHotelsForCity(selectedCity);
                    } else if (typeof loadHotelsForCity === 'function') {
                        loadHotelsForCity(selectedCity);
                    } else {
                        console.error('loadHotelsForCity function is not defined');
                    }
                    
                    // Load vehicles and locations for transfer if transfer is enabled
                    const transferRequired = document.getElementById('hotel_transfer_required');
                    if (transferRequired && transferRequired.value === 'Yes') {
                        if (typeof window.loadHotelTransferVehicles === 'function') {
                            window.loadHotelTransferVehicles(selectedCity);
                        }
                        if (typeof window.loadHotelTransferLocations === 'function') {
                            window.loadHotelTransferLocations(selectedCity);
                        }
                    }
                } else {
                    // Disable hotel selection
                    hotelSelect.disabled = true;
                    $('#hotelSelect').prop('disabled', true); // Disable Select2
                    hotelSelect.innerHTML = '<option value="">Select a city first to load hotels</option>';
                    hotelLoadingStatus.innerHTML = '';
                    cityMessage.style.display = 'block';
                    
                    // Reinitialize Select2 when disabling
                    if (typeof window.reinitializeSelect2 === 'function') {
                        window.reinitializeSelect2('hotelSelect', 'Select a city first to load hotels');
                    }
                }
            });
            
            // Hotel Select
            $('#hotelSelect').select2({
                placeholder: "Select a city first to load hotels",
                allowClear: true,
                width: '100%'
            });
            
            // Room Type Select
            $('#roomTypeSelect').select2({
                placeholder: "Room Type",
                allowClear: true,
                width: '100%'
            });
            
            // Bed Type Select
            $('#bedTypeSelect').select2({
                placeholder: "Bed Type",
                allowClear: true,
                width: '100%'
            });
            
            // Meal Plan Select
            $('#mealPlanSelect').select2({
                placeholder: "Select Meal Plans",
                allowClear: true,
                width: '100%'
            });
            
            // Modal Local Transfer City
            $('#modal_local_transfer_city').select2({
                placeholder: "Select city",
                allowClear: true,
                width: '100%',
                dropdownParent: $('#modal_local_transfer_city').closest('.modal-content')
            }).on('select2:open select2:close', function() {
                setTimeout(fixSelect2IconPadding, 10);
            });
            setTimeout(() => fixSelect2IconPadding(), 100);
            
            // Modal Exit City
            $('#modal_exit_city').select2({
                placeholder: "Select city",
                allowClear: true,
                width: '100%',
                dropdownParent: $('#modal_exit_city').closest('.modal-content')
            }).on('select2:open select2:close', function() {
                setTimeout(fixSelect2IconPadding, 10);
            });
            setTimeout(() => fixSelect2IconPadding(), 100);
            
            // Entry Pickup Port Select
            $('#entry_pickup_port_select').select2({
                placeholder: "Select pickup port",
                allowClear: true,
                width: '100%'
            }).on('select2:open select2:close', function() {
                setTimeout(fixSelect2IconPadding, 10);
            });
            setTimeout(() => fixSelect2IconPadding(), 100);
            
            // Entry Dropoff Location Select
            $('#entry_dropoff_location_select').select2({
                placeholder: "Select city first",
                allowClear: true,
                width: '100%'
            }).on('select2:open select2:close', function() {
                setTimeout(fixSelect2IconPadding, 10);
            });
            setTimeout(() => fixSelect2IconPadding(), 100);
            
            // Exit Pickup Location Select
            $('#exit_pickup_location_select').select2({
                placeholder: "Select city first",
                allowClear: true,
                width: '100%'
            });
            
            // Exit Dropoff Port Select
            $('#exit_dropoff_port_select').select2({
                placeholder: "Select dropoff port",
                allowClear: true,
                width: '100%'
            });
            
            // Function to initialize Select2 on dynamically added elements
            // Function to fix icon padding for Select2 elements
            window.fixSelect2IconPadding = function() {
                $('.position-relative').each(function() {
                    const $container = $(this);
                    const hasIcon = $container.find('> i[class*="ri-map-pin"], > i[class*="ri-time"]').length > 0;
                    if (hasIcon) {
                        const $select2 = $container.find('.select2-container');
                        if ($select2.length) {
                            $select2.find('.select2-selection__rendered').css('padding-left', '45px');
                        }
                    }
                });
            };
            
            function initializeDynamicSelect2() {
                // Attraction city selects
                $('.attraction-city-select:not(.select2-hidden-accessible)').each(function() {
                    $(this).select2({
                        placeholder: "Select City",
                        allowClear: true,
                        width: '100%'
                    });
                });
                
                // Attraction selects
                $('.attraction-select:not(.select2-hidden-accessible)').each(function() {
                    $(this).select2({
                        placeholder: "Select city first",
                        allowClear: true,
                        width: '100%'
                    });
                });
                
                // Guide city selects
                $('.guide-city-select:not(.select2-hidden-accessible)').each(function() {
                    $(this).select2({
                        placeholder: "Select City",
                        allowClear: true,
                        width: '100%'
                    });
                });
                
                // Guide selects
                $('.guide-select:not(.select2-hidden-accessible)').each(function() {
                    $(this).select2({
                        placeholder: "Select city first",
                        allowClear: true,
                        width: '100%'
                    });
                });
                
                // Restaurant city selects
                $('.restaurant-city-select:not(.select2-hidden-accessible)').each(function() {
                    $(this).select2({
                        placeholder: "Select City",
                        allowClear: true,
                        width: '100%'
                    });
                });
                
                // Restaurant selects
                $('.restaurant-select:not(.select2-hidden-accessible)').each(function() {
                    $(this).select2({
                        placeholder: "Select city first",
                        allowClear: true,
                        width: '100%'
                    });
                });
                
                // Transport city selects
                $('.transport-city-select:not(.select2-hidden-accessible)').each(function() {
                    const $select = $(this);
                    $select.select2({
                        placeholder: "Select City",
                        allowClear: true,
                        width: '100%'
                    });
                    
                    // Attach validation for point-to-point fields
                    // Extract day and index from the select ID
                    const selectId = this.id;
                    if (selectId && selectId.includes('transport_city')) {
                        const dayMatch = selectId.match(/day(\d+)_transport_city/);
                        if (dayMatch) {
                            const day = parseInt(dayMatch[1]);
                            // Check if it's initial transport (index 0) or dynamic
                            let index;
                            if (selectId.match(/day\d+_transport_city_0$/)) {
                                index = 0;
                            } else {
                                const indexMatch = selectId.match(/day\d+_transport_city_(\d+)$/);
                                if (indexMatch) {
                                    index = parseInt(indexMatch[1]);
                                }
                            }
                            
                            if (typeof index !== 'undefined') {
                                // Attach Select2 events for validation
                                $select.on('select2:select.pointToPoint', function() {
                                    if (typeof enableSearchButton === 'function') {
                                        const section = index === 0 ? 'transport_additional' : `transport_${index}_additional`;
                                        setTimeout(() => enableSearchButton(day, section, index === 0 ? 0 : index), 50);
                                    }
                                });
                                $select.on('select2:unselect.pointToPoint', function() {
                                    if (typeof enableSearchButton === 'function') {
                                        const section = index === 0 ? 'transport_additional' : `transport_${index}_additional`;
                                        setTimeout(() => enableSearchButton(day, section, index === 0 ? 0 : index), 50);
                                    }
                                });
                                $select.on('change.pointToPoint', function() {
                                    if (typeof enableSearchButton === 'function') {
                                        const section = index === 0 ? 'transport_additional' : `transport_${index}_additional`;
                                        setTimeout(() => enableSearchButton(day, section, index === 0 ? 0 : index), 50);
                                    }
                                });
                            }
                        }
                    }
                });
                
                // Pickup zone selects
                $('.pickup-zone-select:not(.select2-hidden-accessible)').each(function() {
                    $(this).select2({
                        placeholder: "Select pickup location",
                        allowClear: true,
                        width: '100%'
                    });
                });
                
                // Dropoff zone selects
                $('.dropoff-zone-select:not(.select2-hidden-accessible)').each(function() {
                    $(this).select2({
                        placeholder: "Select dropoff location",
                        allowClear: true,
                        width: '100%'
                    });
                });
                
                // Vehicle selects
                $('.vehicle-select:not(.select2-hidden-accessible)').each(function() {
                    $(this).select2({
                        placeholder: "Choose vehicle",
                        allowClear: true,
                        width: '100%'
                    });
                });
                
                // Fix icon padding for all Select2 elements with icons
                setTimeout(fixSelect2IconPadding, 50);
                // Do NOT call scheduleSyncSingleCityToAllServices here: it runs on every observer tick,
                // triggers change → AJAX → DOM updates → observer again (infinite refresh / fetch storm).
                // City sync runs only from #single_city / country city loads / city_mode (see those call sites).
            }

            let _dynamicSelect2Debounce = null;
            function scheduleInitializeDynamicSelect2() {
                clearTimeout(_dynamicSelect2Debounce);
                _dynamicSelect2Debounce = setTimeout(function () {
                    initializeDynamicSelect2();
                    // Prefill new service city selects only when main city is set; syncAllServiceCities skips
                    // change if value unchanged so this does not refetch all rows on every DOM tweak.
                    if (typeof window.getSingleCityName === 'function' && window.getSingleCityName() &&
                        typeof window.scheduleSyncSingleCityToAllServices === 'function') {
                        window.scheduleSyncSingleCityToAllServices();
                    }
                }, 150);
            }
            
            // Initialize existing dynamic selects
            initializeDynamicSelect2();
            
            // Watch for new form markup only (not document.body — Select2 dropdowns append to body and would retrigger forever)
            const observer = new MutationObserver(function (mutations) {
                for (var i = 0; i < mutations.length; i++) {
                    if (mutations[i].addedNodes && mutations[i].addedNodes.length > 0) {
                        scheduleInitializeDynamicSelect2();
                        return;
                    }
                }
            });

            var _tourFormRoot = document.getElementById('singleTourPackageForm');
            if (_tourFormRoot) {
                observer.observe(_tourFormRoot, { childList: true, subtree: true });
            }
            
            // Custom styling for Select2 to match the form design with proper height
            $('<style>')
                .prop('type', 'text/css')
                .html(`
                    .select2-container .select2-selection--single {
                        height: 38px !important;
                        border: 1px solid #d9dee3;
                        border-radius: 0.375rem;
                    }
                    .select2-container--default .select2-selection--single .select2-selection__rendered {
                        line-height: 38px;
                        padding-left: 12px;
                        color: #697a8d;
                    }
                    .select2-container--default .select2-selection--single .select2-selection__arrow {
                        height: 38px;
                        right: 8px;
                    }
                    .select2-container--default .select2-selection--single .select2-selection__placeholder {
                        color: #a1acb8;
                    }
                    .select2-container .select2-results__option {
                        padding: 8px 12px;
                    }
                    .select2-container--default .select2-results__option--highlighted[aria-selected] {
                        background-color: #696cff;
                        color: white;
                    }
                    .select2-dropdown {
                        border: 1px solid #d9dee3;
                        border-radius: 0.375rem;
                    }
                    .select2-container--default .select2-search--dropdown .select2-search__field {
                        border: 1px solid #d9dee3;
                        padding: 8px;
                        border-radius: 0.375rem;
                    }
                    .select2-container--default.select2-container--focus .select2-selection--single {
                        border-color: #696cff;
                        outline: 0;
                    }
                    .select2-container--default .select2-selection--single:focus {
                        outline: none;
                    }
                    /* Fix for Select2 with icons - add padding when icon is present */
                    .position-relative:has(> i[class*="ri-map-pin"]) .select2-container--default .select2-selection--single .select2-selection__rendered,
                    .position-relative:has(> i[class*="ri-time"]) .select2-container--default .select2-selection--single .select2-selection__rendered {
                        padding-left: 45px !important;
                    }
                    /* Fallback for browsers that don't support :has() - apply when select has padding-left style */
                    .position-relative select[style*="padding-left: 45px"] ~ .select2-container .select2-selection__rendered,
                    .position-relative select[style*="padding-left:45px"] ~ .select2-container .select2-selection__rendered {
                        padding-left: 45px !important;
                    }
                    /* Ensure icon appears above Select2 */
                    .position-relative > i[class*="ri-map-pin"],
                    .position-relative > i[class*="ri-time"] {
                        z-index: 10 !important;
                        pointer-events: none;
                    }
                    /* Adjust Select2 container to not overlap with icon */
                    .position-relative .select2-container {
                        padding-left: 0;
                    }
                `)
                .appendTo('head');
        });
    </script>

    <!-- Bootstrap 5 JS (for dropdown functionality) -->
    <!-- <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script> -->
    <script>
        // Guest Dropdown Functions - Define them globally first

        (function groupFOCBehavior() {
            function safeInt(v) {
                const n = parseInt(String(v ?? '').trim(), 10);
                return Number.isFinite(n) ? n : 0;
            }

            function getSelectedTourType() {
                const checked = document.querySelector('input[name="tour_type"]:checked');
                return checked ? String(checked.value || '') : String(window.selectedTourType || 'FIT');
            }

            function getElVal(id) {
                const el = document.getElementById(id);
                return el ? el.value : '';
            }

            function setElVal(id, v) {
                const el = document.getElementById(id);
                if (el) el.value = String(v);
            }

            function updateFOCUI() {
                const groupSize = Math.max(0, safeInt(getElVal('group_size')));
                const focSize = Math.max(0, safeInt(getElVal('foc_size')));
                const includeFOCPriceEl = document.getElementById('include_foc_in_group_price');
                const includeFOCInPrice = !!(includeFOCPriceEl && includeFOCPriceEl.checked);
                const includeFOCRow = document.getElementById('includeFOCInPriceRow');

                // Store foc size in legacy field if backend expects it
                setElVal('auto_foc', focSize);

                // Total pax includes FOC pax on top of group size.
                const totalPax = Math.max(0, groupSize + focSize);
                setElVal('total_pax_display', totalPax);

                // Checkbox only makes sense when FOC > 0
                if (includeFOCRow) includeFOCRow.classList.toggle('d-none', focSize <= 0);
                if (includeFOCPriceEl) {
                    includeFOCPriceEl.disabled = focSize <= 0;
                    if (focSize <= 0) includeFOCPriceEl.checked = false;
                }

                // Paying pax must never include FOC.
                setElVal('paying_pax', groupSize);

                // Discount flag to store:
                // - If checkbox checked => discount = 1
                // - If checkbox NOT checked => discount = 0
                setElVal('discount', includeFOCInPrice ? 1 : 0);
            }

            function renderMainGuestSummary(male, female, children, infants) {
                const adults = Math.max(0, safeInt(male) + safeInt(female));
                const guestSummary = document.getElementById('mainGuestSummary');
                if (!guestSummary) return;

                let summaryHTML = `<span class="d-flex align-items-center gap-1">`;
                summaryHTML += `<span class="badge d-flex align-items-center gap-1" style="background: #667eea; border-radius: 4px; font-size: 0.7rem; padding: 0.2rem 0.4rem;" title="Adults"><i class="ri-group-line" style="font-size: 0.75rem;"></i><span>${adults} Adults</span></span>`;
                summaryHTML += ` <span class="badge d-flex align-items-center gap-1" style="background: #667eea; border-radius: 4px; font-size: 0.7rem; padding: 0.2rem 0.4rem; opacity: 0.8;" title="Male"><i class="ri-men-line" style="font-size: 0.75rem;"></i><span>${safeInt(male)}</span></span>`;
                summaryHTML += ` <span class="badge d-flex align-items-center gap-1" style="background: #667eea; border-radius: 4px; font-size: 0.7rem; padding: 0.2rem 0.4rem; opacity: 0.8;" title="Female"><i class="ri-women-line" style="font-size: 0.75rem;"></i><span>${safeInt(female)}</span></span>`;
                summaryHTML += `</span>`;
                summaryHTML += `<span class="d-flex align-items-center gap-1">`;
                summaryHTML += ` <span class="badge d-flex align-items-center gap-1" style="background: #28a745; border-radius: 4px; font-size: 0.7rem; padding: 0.2rem 0.4rem;" title="Children"><i class="ri-user-smile-line" style="font-size: 0.75rem;"></i><span>${safeInt(children)}</span></span>`;
                summaryHTML += ` <span class="badge d-flex align-items-center gap-1" style="background: #ffc107; color: #000; border-radius: 4px; font-size: 0.7rem; padding: 0.2rem 0.4rem;" title="Infants"><i class="ri-user-heart-line" style="font-size: 0.75rem;"></i><span>${safeInt(infants)}</span></span>`;
                summaryHTML += `</span>`;
                guestSummary.innerHTML = summaryHTML;
            }

            function syncGuestsFromTotalPax() {
                const type = getSelectedTourType();
                if (String(type).toUpperCase() !== 'GROUP') return;

                const groupSize = Math.max(0, safeInt(getElVal('group_size')));
                const focSize = Math.max(0, safeInt(getElVal('foc_size')));
                const totalPax = Math.max(0, groupSize + focSize);

                // Auto-populate Adults from Total Pax (Male gets all by default)
                const adultsInput = document.getElementById('adults');
                const maleInput = document.getElementById('male');
                const femaleInput = document.getElementById('female');
                const childrenInput = document.getElementById('children');
                const infantsInput = document.getElementById('infants');

                if (adultsInput) adultsInput.value = String(totalPax);
                if (maleInput) maleInput.value = String(totalPax);
                if (femaleInput) femaleInput.value = '0';
                if (childrenInput) childrenInput.value = '0';
                // keep infants as-is (do not auto-change)

                renderMainGuestSummary(totalPax, 0, 0, safeInt(infantsInput?.value || 0));

                // If modal is open, reflect values there too
                const maleEl = document.getElementById('mainModalMale');
                const femaleEl = document.getElementById('mainModalFemale');
                const adultsEl = document.getElementById('mainModalAdults');
                const childrenEl = document.getElementById('mainModalChildren');
                if (maleEl) maleEl.textContent = String(totalPax);
                if (femaleEl) femaleEl.textContent = '0';
                if (adultsEl) adultsEl.textContent = String(totalPax);
                if (childrenEl) childrenEl.textContent = '0';

                try { window.updateAllServiceGuestFields && window.updateAllServiceGuestFields(totalPax, 0, 0, safeInt(infantsInput?.value || 0)); } catch (e) {}
            }

            function setGroupDetailsVisible(isVisible) {
                const wrap = document.getElementById('groupDetailsWrapper');
                if (!wrap) return;
                wrap.classList.toggle('d-none', !isVisible);
            }

            function updateGroupDetailsVisibility() {
                // Requested: do NOT show this section on the main page.
                // We only mount + show it inside the guest modal when GROUP is selected.
                setGroupDetailsVisible(false);
            }

            // Move existing Group Details section into/out of modal (no duplicate IDs).
            window.mountGroupDetailsFOCIntoGuestModal = function (toModal) {
                const wrapper = document.getElementById('groupDetailsWrapper');
                if (!wrapper) return;

                const placeholder = document.getElementById('groupDetailsPlaceholder');
                const mount = document.getElementById('mainGuestGroupDetailsMount');
                const isGroup = String(getSelectedTourType()).toUpperCase() === 'GROUP';

                if (toModal) {
                    if (!isGroup || !mount) return;
                    wrapper.classList.remove('d-none');
                    mount.appendChild(wrapper);
                    return;
                }

                if (placeholder) placeholder.appendChild(wrapper);
                // Always hide when it's back on the page
                setGroupDetailsVisible(false);
            };

            document.addEventListener('input', function (e) {
                const id = e && e.target ? e.target.id : '';
                if (id === 'foc_size' || id === 'group_size_display') {
                    // keep hidden group_size in sync with editable display field
                    if (id === 'group_size_display') setElVal('group_size', safeInt(getElVal('group_size_display')));
                    updateFOCUI();
                    syncGuestsFromTotalPax();
                }
            }, true);

            document.addEventListener('change', function (e) {
                const t = e && e.target ? e.target : null;
                const id = t && t.id ? t.id : '';

                if (t && t.name === 'tour_type') {
                    window.selectedTourType = t.value;
                    updateGroupDetailsVisibility();
                }
                if (id === 'include_foc_in_group_price') {
                    updateFOCUI();
                }
            }, true);

            document.addEventListener('DOMContentLoaded', function () {
                updateGroupDetailsVisibility();
                // Initialize editable group size from existing hidden value (fallback to current Adults+Children once)
                const existingGroup = safeInt(getElVal('group_size'));
                const fallbackGroup = Math.max(0, safeInt(getElVal('adults')) + safeInt(getElVal('children')));
                const initGroup = existingGroup > 0 ? existingGroup : fallbackGroup;
                setElVal('group_size', initGroup);
                setElVal('group_size_display', initGroup);
                updateFOCUI();
                syncGuestsFromTotalPax();

                // Enable tooltips for info icons (Bootstrap 5)
                try {
                    if (typeof bootstrap !== 'undefined' && bootstrap.Tooltip) {
                        document.querySelectorAll('[data-bs-toggle="tooltip"]').forEach((el) => {
                            bootstrap.Tooltip.getOrCreateInstance(el);
                        });
                    }
                } catch (e) { /* ignore */ }
            });
        })();

        
        // Main Guest Selector - Uses the same modal pattern as attraction booking
        window.openMainGuestSelector = function() {
            console.log('openMainGuestSelector called');
            
            // Get current values from hidden inputs
            const male = parseInt(document.getElementById('male').value) || 0;
            const female = parseInt(document.getElementById('female').value) || 0;
            const children = parseInt(document.getElementById('children').value) || 0;
            const infants = parseInt(document.getElementById('infants').value) || 0;
            const adults = male + female;
            
            console.log('Current guest values:', {adults, male, female, children, infants});
            
            // Create modal if it doesn't exist
            if (!document.getElementById('mainGuestSelectorModal')) {
                createMainGuestSelectorModal();
            }
            
            // Set modal values
            document.getElementById('mainModalMale').textContent = male;
        document.getElementById('mainModalFemale').textContent = female;
        document.getElementById('mainModalChildren').textContent = children;
        document.getElementById('mainModalInfants').textContent = infants;
        
        // Set total adults (male + female) if the element exists
        const adultsEl = document.getElementById('mainModalAdults');
        if (adultsEl) {
            adultsEl.textContent = (male + female);
        }
            
            // Update child age dropdowns (will auto-populate existing ages)
            updateChildAgeDropdowns(children);
            
            // Show modal
            const modal = document.getElementById('mainGuestSelectorModal');
            const modalInstance = new bootstrap.Modal(modal);

            // For GROUP: show the same Group Details (FOC) section inside this modal (move it, don't duplicate).
            try {
                if (typeof window.mountGroupDetailsFOCIntoGuestModal === 'function') {
                    window.mountGroupDetailsFOCIntoGuestModal(true);
                }
            } catch (e) { /* ignore */ }
            
            // Add event listeners to handle focus properly
            modal.addEventListener('hidden.bs.modal', function () {
                // Remove focus from any focused elements when modal is hidden
                const focusedElement = document.activeElement;
                if (focusedElement && modal.contains(focusedElement)) {
                    focusedElement.blur();
                }

                // Always restore Group Details section back to form area
                try {
                    if (typeof window.mountGroupDetailsFOCIntoGuestModal === 'function') {
                        window.mountGroupDetailsFOCIntoGuestModal(false);
                    }
                } catch (e) { /* ignore */ }
            });
            
            modalInstance.show();
        };
        
