        // Function to update restaurant transport pricing column
        window.updateRestaurantTransportPricing = function(day, index) {
            const transportCostField = document.getElementById(`day${day}_restaurant_${index}_transfer_cost`);
            const transportPricingContent = document.getElementById(`day${day}_restaurant_${index}_transport_pricing_content`);
            const transferRequired = document.getElementById(`day${day}_restaurant_${index}_transfer_required`);
            const transferType = document.getElementById(`day${day}_restaurant_${index}_transfer_type`);
            const transferWay = document.getElementById(`day${day}_restaurant_${index}_transfer_way`);
            const transferVehicle = document.getElementById(`day${day}_restaurant_${index}_transfer_vehicle`);
            const pickupLocationSelect = document.getElementById(`day${day}_restaurant_${index}_transfer_pickup_location`);
            
            if (!transportPricingContent) return;
            
            // Check if transfer is required
            if (!transferRequired || transferRequired.value !== 'Yes') {
                transportPricingContent.innerHTML = '<div class="text-muted small">No transport selected</div>';
                // Update total display (transport is 0)
                updateRestaurantTotalDisplay(day, index);
                return;
            }
            
            let cost = transportCostField ? (parseFloat(transportCostField.value) || 0) : 0;
            const type = transferType ? transferType.value : '';
            const way = transferWay ? transferWay.value : '';
            const vehicleSelect = transferVehicle;
            let vehicleName = 'N/A';
            let baseCost = cost;
            let guestCount = 1;
            
            if (vehicleSelect && vehicleSelect.value) {
                const selectedOption = vehicleSelect.options[vehicleSelect.selectedIndex];
                if (selectedOption) {
                    vehicleName = selectedOption.textContent || 'N/A';
                }
            }
            
            // For Shared transfer: multiply base cost by restaurant pax (guest count)
            if (type === 'Shared' && cost > 0) {
                const guestSummaryElement = document.getElementById(`day${day}_restaurant_${index}_guest_summary`);
                if (guestSummaryElement && typeof parseGuestSummary === 'function') {
                    const guestInfo = parseGuestSummary(guestSummaryElement.innerHTML || guestSummaryElement.textContent || '');
                    guestCount = (guestInfo.adults || 0) + (guestInfo.children || 0) + (guestInfo.infants || 0);
                    if (guestCount === 0) guestCount = 1;
                    cost = baseCost * guestCount;
                }
            }
            
            // Check if this price came from AJAX (zone-based pricing)
            const isAjaxPrice = transportCostField && transportCostField.getAttribute('data-ajax-base-price');
            const priceSource = isAjaxPrice ? ' (Zone-based)' : '';
            
            if (cost > 0) {
                let transportHtml = `
                    <div class="small">
                        <div><strong>Type:</strong> ${type || 'N/A'}</div>
                        <div><strong>Way:</strong> ${way || 'N/A'}</div>
                        <div><strong>Vehicle:</strong> ${vehicleName}</div>
                        ${isAjaxPrice ? '<div class="text-info"><small><i class="ri-checkbox-circle-line me-1"></i>Zone-based pricing</small></div>' : ''}
                        ${type === 'Shared' && guestCount > 1 ? `<div class="mt-1"><small>Base Cost: $${baseCost.toFixed(2)} × ${guestCount} pax</small></div>` : ''}
                        <div class="mt-2"><strong class="text-success">$${cost.toFixed(2)}${priceSource}</strong></div>
                    </div>
                `;
                transportPricingContent.innerHTML = transportHtml;
                // Update total display (restaurant + transport)
                updateRestaurantTotalDisplay(day, index);
            } else {
                // If pickup location is selected but cost is 0, try to fetch pricing
                if (pickupLocationSelect && pickupLocationSelect.value &&
                    vehicleSelect && vehicleSelect.value &&
                    transferType && transferType.value &&
                    transferWay && transferWay.value) {
                    
                    // Check if pricing fetch has already failed to prevent infinite loop
                    const pricingFetchFailed = transportCostField && transportCostField.getAttribute('data-pricing-fetch-failed') === 'true';
                    const errorMessage = transportCostField ? transportCostField.getAttribute('data-pricing-error-message') : null;
                    
                    if (pricingFetchFailed) {
                        // Pricing fetch already failed, show error message instead of retrying
                        transportPricingContent.innerHTML = `<div class="text-danger small"><i class="ri-error-warning-line me-1"></i>${errorMessage || 'No pricing found'}</div>`;
                    } else {
                        transportPricingContent.innerHTML = '<div class="text-muted small">Fetching pricing...</div>';
                        // Trigger AJAX call to get pricing
                        fetchRestaurantTransferPricing(day, index);
                    }
                } else {
                    transportPricingContent.innerHTML = '<div class="text-muted small">Transport selected but cost not set</div>';
                }
                // Update total display even when cost is 0
                updateRestaurantTotalDisplay(day, index);
            }
        }
        
        // Function to update restaurant total display (restaurant pricing + transport pricing)
        window.updateRestaurantTotalDisplay = function(day, index) {
            const totalDisplay = document.getElementById(`day${day}_restaurant_${index}_total_display`);
            if (!totalDisplay) return;
            
            // Get restaurant pricing from hidden field
            const restaurantTotalField = document.getElementById(`day${day}_restaurant_${index}_total_price`);
            const restaurantTotal = restaurantTotalField ? (parseFloat(restaurantTotalField.value) || 0) : 0;
            
            // Get transport pricing: for Shared, multiply base cost by restaurant pax
            let transportTotal = 0;
            const transportCostField = document.getElementById(`day${day}_restaurant_${index}_transfer_cost`);
            const transferType = document.getElementById(`day${day}_restaurant_${index}_transfer_type`);
            if (transportCostField && transportCostField.value) {
                const baseTransport = parseFloat(transportCostField.value) || 0;
                if (transferType && transferType.value === 'Shared' && baseTransport > 0) {
                    const guestSummaryElement = document.getElementById(`day${day}_restaurant_${index}_guest_summary`);
                    if (guestSummaryElement && typeof parseGuestSummary === 'function') {
                        const guestInfo = parseGuestSummary(guestSummaryElement.innerHTML || guestSummaryElement.textContent || '');
                        const pax = (guestInfo.adults || 0) + (guestInfo.children || 0) + (guestInfo.infants || 0);
                        transportTotal = pax > 0 ? baseTransport * pax : baseTransport;
                    } else {
                        transportTotal = baseTransport;
                    }
                } else {
                    transportTotal = baseTransport;
                }
            }
            
            // Calculate and display total
            const grandTotal = restaurantTotal + transportTotal;
            totalDisplay.textContent = grandTotal.toFixed(2);

            // Also refresh restaurant header summary (all restaurants)
            if (typeof window.updateRestaurantSectionSummary === 'function') {
                window.updateRestaurantSectionSummary(day);
            }
        }

        // Overall restaurant section summary (names + total incl. transport)
        window.updateRestaurantSectionSummary = function(day = 1) {
            try {
                const headerSpan = document.getElementById(`day${day}_restaurantHeaderSummary`);
                const container = document.getElementById(`day${day}_restaurants_container`);
                const restaurantTotalPriceEl = document.getElementById(`day${day}_restaurantTotalPrice`);
                if (!headerSpan || !container) return;

                const items = container.querySelectorAll('.restaurant-item');
                if (!items.length) {
                    headerSpan.textContent = '';
                    if (restaurantTotalPriceEl) restaurantTotalPriceEl.textContent = 'SGD 0.00';
                    return;
                }

                const names = [];
                let grandTotal = 0;

                items.forEach(item => {
                    const idx = item.getAttribute('data-restaurant-index');
                    if (!idx) return;

                    const restaurantSelect = document.getElementById(`day${day}_restaurant_${idx}`);
                    const totalDisplay = document.getElementById(`day${day}_restaurant_${idx}_total_display`);

                    if (restaurantSelect && restaurantSelect.value) {
                        const txt = restaurantSelect.options[restaurantSelect.selectedIndex].text;
                        if (txt) names.push(txt);
                        // Only count money for rows where a restaurant is actually selected (avoids stale totals after segment switch).
                        if (totalDisplay && totalDisplay.textContent) {
                            const match = totalDisplay.textContent.match(/([\d,.]+)/);
                            if (match) {
                                grandTotal += parseFloat(match[1].replace(/,/g, '')) || 0;
                            }
                        }
                    }
                });

                if (!names.length) {
                    headerSpan.textContent = '';
                    if (restaurantTotalPriceEl) restaurantTotalPriceEl.textContent = 'SGD 0.00';
                    return;
                }

                const uniqueNames = [...new Set(names)];
                let nameSummary = '';
                if (uniqueNames.length === 1) {
                    nameSummary = uniqueNames[0];
                } else if (uniqueNames.length === 2) {
                    nameSummary = `${uniqueNames[0]} & ${uniqueNames[1]}`;
                } else if (uniqueNames.length === 3) {
                    nameSummary = `${uniqueNames[0]}, ${uniqueNames[1]} & ${uniqueNames[2]}`;
                } else {
                    const remaining = uniqueNames.length - 2;
                    nameSummary = `${uniqueNames[0]}, ${uniqueNames[1]} + ${remaining} more`;
                }

                const formattedTotal = grandTotal.toLocaleString('en-US', {
                    minimumFractionDigits: 2,
                    maximumFractionDigits: 2
                });

                // Only show names in header, price is shown on right side
                headerSpan.textContent = `– ${nameSummary}`;
                
                // Update right side price display
                if (restaurantTotalPriceEl) {
                    restaurantTotalPriceEl.textContent = `SGD ${formattedTotal}`;
                }
            } catch (e) {
                console.error('Error updating restaurant section summary:', e);
            }
        }
        
        // ==================== END RESTAURANT TRANSFER PRICING FUNCTIONS ====================
        
        window.loadGuidesForCity = function(day, cityName, index) {
            const guideSelect = document.getElementById(`day${day}_guide_${index}`);
            const cityMessage = document.getElementById(`day${day}_guide_city_message_${index}`);
            
            if (!guideSelect) {
                console.error(`Guide select not found: day${day}_guide_${index}`);
                return;
            }
            
            // Check if Select2 is initialized
            const isSelect2Initialized = $(guideSelect).hasClass('select2-hidden-accessible');
            
            if (cityName) {
                guideSelect.disabled = false;
                
                // Destroy Select2 if initialized before updating options
                if (isSelect2Initialized) {
                    $(guideSelect).select2('destroy');
                }
                
                guideSelect.innerHTML = '<option value="">Loading guides...</option>';
                cityMessage.style.display = 'none';
                
                // Reinitialize Select2 with loading state
                if (isSelect2Initialized) {
                    $(guideSelect).select2({
                        placeholder: "Loading guides...",
                        allowClear: true,
                        width: '100%'
                    });
                }
                
                // Load guides for the specific city
                const currentDmcId = '{{ $finalDmcId }}';
                
                window.fetchJsonDeduped(`{{ route('fetch-guides-by-dmc') }}?city=${encodeURIComponent(cityName)}&dmc_id=${currentDmcId}`)
                    .then(data => {
                        // Destroy Select2 before updating options
                        if (isSelect2Initialized) {
                            $(guideSelect).select2('destroy');
                        }
                        
                        guideSelect.innerHTML = '<option value="">Search Guide</option>';
                        
                        if (data.success && data.guides) {
                            data.guides.forEach(guide => {
                                const option = document.createElement('option');
                                option.value = guide.guide_id;
                                // Extract language names from the languages relationship
                                const languageNames = guide.languages ? guide.languages.map(lang => lang.language).join(', ') : 'Languages not specified';
                                option.textContent = `${guide.name} - ${languageNames}`;
                                option.dataset.city = guide.city;
                                option.dataset.image = guide.image || '';
                                option.dataset.languages = guide.languages ? JSON.stringify(guide.languages.map(lang => lang.language)) : JSON.stringify([]);
                                option.dataset.experience = guide.experience || 0;
                                
                                // Add pricing data attributes
                                option.dataset.nightStartTime = guide.night_start_time;
                                option.dataset.nightEndTime = guide.night_end_time;
                                option.dataset.dayRate = 0;
                                option.dataset.nightSurcharge = guide.night_surcharge;
                                option.dataset.hourlyPrice = guide.hourly_price;
                                option.dataset.twoHourPrice = guide.two_hour_price;
                                option.dataset.fourHourPrice = guide.four_hour_price;
                                option.dataset.sixHourPrice = guide.six_hour_price;
                                option.dataset.eightHourPrice = guide.eight_hour_price;
                                option.dataset.tenHourPrice = guide.ten_hour_price;
                                option.dataset.twelveHourPrice = guide.twelve_hour_price;
                                
                                guideSelect.appendChild(option);
                            });
                            console.log(`Loaded ${data.guides.length} guides for ${cityName}`);
                        } else {
                            guideSelect.innerHTML += '<option disabled>No guides found in this city</option>';
                        }
                        
                        guideSelect.disabled = false;
                        
                        // Reinitialize Select2 after populating options
                        if (isSelect2Initialized || $(guideSelect).hasClass('guide-select')) {
                            $(guideSelect).select2({
                                placeholder: "Search Guide",
                                allowClear: true,
                                width: '100%'
                            });
                        }
                    })
                    .catch(error => {
                        console.error('Error loading guides for city:', error);
                        
                        // Destroy Select2 before updating
                        if (isSelect2Initialized) {
                            $(guideSelect).select2('destroy');
                        }
                        
                        guideSelect.innerHTML = '<option disabled>Error loading guides</option>';
                        guideSelect.disabled = false;
                        
                        // Reinitialize Select2
                        if (isSelect2Initialized || $(guideSelect).hasClass('guide-select')) {
                            $(guideSelect).select2({
                                placeholder: "Error loading guides",
                                allowClear: true,
                                width: '100%'
                            });
                        }
                    });
            } else {
                // Destroy Select2 if initialized
                if (isSelect2Initialized) {
                    $(guideSelect).select2('destroy');
                }
                
                guideSelect.disabled = true;
                guideSelect.innerHTML = '<option value="">Select city first</option>';
                cityMessage.style.display = 'block';
                
                // Reinitialize Select2
                if (isSelect2Initialized || $(guideSelect).hasClass('guide-select')) {
                    $(guideSelect).select2({
                        placeholder: "Select city first",
                        allowClear: true,
                        width: '100%'
                    });
                }
            }
        };

        window.loadRestaurantsForCity = function(day, cityName, index) {
            const restaurantSelect = document.getElementById(`day${day}_restaurant_${index}`);
            const cityMessage = document.getElementById(`day${day}_restaurant_city_message_${index}`);
            
            function prependMultiRestaurantOptions(selectEl) {
                const list = window.multiRestaurants || [];
                list.forEach(m => {
                    const price = m.adult_price ?? m.price ?? 0;
                    const name = m.package_name || 'Buffet';
                    const option = document.createElement('option');
                    option.value = 'multi_restaurant_' + m.id;
                    option.textContent = name;
                    option.dataset.adultPrice = String(price);
                    option.dataset.packageName = name;
                    selectEl.appendChild(option);
                });
            }

            if (cityName) {
                restaurantSelect.disabled = false;
                restaurantSelect.innerHTML = '<option value="">Loading restaurants...</option>';
                cityMessage.style.display = 'none';
                
                const currentDmcId = '{{ $finalDmcId }}';
                
                window.fetchJsonDeduped(`{{ route('fetch-restaurants-by-dmc') }}?city=${encodeURIComponent(cityName)}&dmc_id=${currentDmcId}`)
                    .then(data => {
                        restaurantSelect.innerHTML = '<option value="">Search Restaurant</option>';
                        prependMultiRestaurantOptions(restaurantSelect);
                        
                        if (data.success && data.restaurants) {
                            data.restaurants.forEach(restaurant => {
                                const option = document.createElement('option');
                                option.value = restaurant.restaurant_id;
                                option.textContent = restaurant.name;
                                option.dataset.city = restaurant.city;
                                option.dataset.mealTypes = JSON.stringify(restaurant.meal_types || []);
                                restaurantSelect.appendChild(option);
                            });
                        } else {
                            if ((window.multiRestaurants || []).length === 0) {
                                restaurantSelect.innerHTML += '<option disabled>No restaurants found in this city</option>';
                            }
                        }
                        
                        restaurantSelect.disabled = false;
                        
                        const transferRequired = document.getElementById(`day${day}_restaurant_${index}_transfer_required`);
                        if (transferRequired && transferRequired.value === 'Yes') {
                            loadRestaurantTransferVehicles(day, cityName, index);
                            loadRestaurantTransferPickupLocations(day, cityName, index);
                        }
                    })
                    .catch(error => {
                        console.error('Error loading restaurants for city:', error);
                        restaurantSelect.innerHTML = '<option value="">Search Restaurant</option>';
                        prependMultiRestaurantOptions(restaurantSelect);
                        restaurantSelect.innerHTML += '<option disabled>Error loading restaurants</option>';
                        restaurantSelect.disabled = false;
                    });
            } else {
                restaurantSelect.disabled = false;
                restaurantSelect.innerHTML = '<option value="">Search Restaurant</option>';
                prependMultiRestaurantOptions(restaurantSelect);
                cityMessage.style.display = 'block';
            }
        }
        
        // Function to toggle restaurant transfer fields visibility
        window.toggleRestaurantTransferFields = function(day, index) {
            const transferRequired = document.getElementById(`day${day}_restaurant_${index}_transfer_required`);
            const transferCard = document.getElementById(`day${day}_restaurant_${index}_transfer_card`);
            const transferTypeField = document.getElementById(`day${day}_restaurant_${index}_transfer_type_field`);
            const transferWayField = document.getElementById(`day${day}_restaurant_${index}_transfer_way_field`);
            const transferVehicleField = document.getElementById(`day${day}_restaurant_${index}_transfer_vehicle_field`);
            const transferCostField = document.getElementById(`day${day}_restaurant_${index}_transfer_cost_field`);
            const transferPickupField = document.getElementById(`day${day}_restaurant_${index}_transfer_pickup_field`);
            
            if (transferRequired) {
                if (transferRequired.value === 'Yes') {
                    // Show transfer card
                    if (transferCard) transferCard.style.display = 'block';
                    
                    // Show all transfer fields (for backward compatibility)
                    if (transferTypeField) transferTypeField.style.display = 'block';
                    if (transferWayField) transferWayField.style.display = 'block';
                    if (transferVehicleField) transferVehicleField.style.display = 'block';
                    if (transferCostField) transferCostField.style.display = 'block';
                    if (transferPickupField) transferPickupField.style.display = 'block';
                    
                    // Load vehicles if city is already selected
                    const citySelect = document.getElementById(`day${day}_restaurant_city_${index}`);
                    if (citySelect && citySelect.value) {
                        loadRestaurantTransferVehicles(day, citySelect.value, index);
                        loadRestaurantTransferPickupLocations(day, citySelect.value, index);
                    } else {
                        // If vehicles are already loaded, apply filter based on current transfer type
                        window.filterRestaurantTransferVehiclesByType(day, index);
                    }
                } else {
                    // Hide transfer card
                    if (transferCard) transferCard.style.display = 'none';
                    
                    // Hide all transfer fields (for backward compatibility)
                    if (transferTypeField) transferTypeField.style.display = 'none';
                    if (transferWayField) transferWayField.style.display = 'none';
                    if (transferVehicleField) transferVehicleField.style.display = 'none';
                    if (transferCostField) transferCostField.style.display = 'none';
                    if (transferPickupField) transferPickupField.style.display = 'none';
                    
                    // Reset transfer fields
                    const typeSelect = document.getElementById(`day${day}_restaurant_${index}_transfer_type`);
                    const waySelect = document.getElementById(`day${day}_restaurant_${index}_transfer_way`);
                    const vehicleSelect = document.getElementById(`day${day}_restaurant_${index}_transfer_vehicle`);
                    const costInput = document.getElementById(`day${day}_restaurant_${index}_transfer_cost`);
                    const pickupSelect = document.getElementById(`day${day}_restaurant_${index}_transfer_pickup_location`);
                    
                    if (typeSelect) typeSelect.value = '';
                    if (waySelect) waySelect.value = '';
                    if (vehicleSelect) vehicleSelect.innerHTML = '<option value="">Select Vehicle</option>';
                    if (costInput) costInput.value = '';
                    if (pickupSelect) pickupSelect.innerHTML = '<option value="">Select Pickup Location</option>';

                    // After clearing transfer fields, immediately refresh pricing/section totals
                    if (typeof window.updateRestaurantTransportPricing === 'function') {
                        window.updateRestaurantTransportPricing(day, index);
                    }
                }
            }
        }
        
        // Function to load vehicles for restaurant transfer
        window.loadRestaurantTransferVehicles = function(day, cityName, index) {
            const vehicleSelect = document.getElementById(`day${day}_restaurant_${index}_transfer_vehicle`);
            
            if (!vehicleSelect || !cityName) {
                return;
            }
            
            vehicleSelect.innerHTML = '<option value="">Loading vehicles...</option>';
            vehicleSelect.disabled = true;
            
            fetch(`{{ route('fetch-vehicles-by-city-dmc') }}?city=${encodeURIComponent(cityName)}`)
                .then(response => response.json())
                .then(data => {
                    vehicleSelect.innerHTML = '<option value="">Select Vehicle</option>';
                    
                    if (data.success && data.vehicles && data.vehicles.length > 0) {
                        data.vehicles.forEach(vehicle => {
                            const vehicleInfo = `${vehicle.vehicle_name} (${vehicle.vehicle_type}) - ${vehicle.seating_capacity} seats`;
                            const option = document.createElement('option');
                            option.value = vehicle.vehicle_id;
                            option.textContent = vehicleInfo;
                            option.setAttribute('data-vehicle-name', vehicle.vehicle_name || '');
                            option.setAttribute('data-vehicle-type', vehicle.vehicle_type || '');
                            option.setAttribute('data-seating-capacity', vehicle.seating_capacity || '');
                            option.setAttribute('data-private-price', vehicle.private_price || '');
                            option.setAttribute('data-shared-price', vehicle.shared_price || '');
                            option.setAttribute('data-sharable', vehicle.sharable || '0');
                            vehicleSelect.appendChild(option);
                        });
                        console.log(`Loaded ${data.vehicles.length} vehicles for restaurant transfer in ${cityName}`);
                        
                        // Apply filter based on selected transfer type
                        window.filterRestaurantTransferVehiclesByType(day, index);
                    } else {
                        vehicleSelect.innerHTML += '<option disabled>No vehicles available</option>';
                    }
                    
                    vehicleSelect.disabled = false;
                })
                .catch(error => {
                    console.error('Error loading vehicles for restaurant transfer:', error);
                    vehicleSelect.innerHTML = '<option disabled>Error loading vehicles</option>';
                    vehicleSelect.disabled = false;
                });
        }
        
        // Function to load pickup locations for restaurant transfer
        window.loadRestaurantTransferPickupLocations = function(day, cityName, index) {
            const pickupSelect = document.getElementById(`day${day}_restaurant_${index}_transfer_pickup_location`);
            
            if (!pickupSelect || !cityName) {
                return;
            }
            
            pickupSelect.innerHTML = '<option value="">Loading locations...</option>';
            pickupSelect.disabled = true;
            
            // Get DMC ID for the requests
            const dmcId = '{{ $finalDmcId }}';
            
            // Make AJAX calls for attractions, hotels and restaurants (same as entry_dropoff_location_select)
            Promise.all([
                window.fetchJsonDeduped(`{{ route('fetch-hotels-by-dmc') }}?city=${encodeURIComponent(cityName)}&dmc_id=${dmcId}`),
                window.fetchJsonDeduped(`{{ route('fetch-attractions-by-dmc') }}?city=${encodeURIComponent(cityName)}&dmc_id=${dmcId}`),
                window.fetchJsonDeduped(`{{ route('fetch-restaurants-by-dmc') }}?city=${encodeURIComponent(cityName)}&dmc_id=${dmcId}`)
            ])
            .then(([hotelsData, attractionsData, restaurantsData]) => {
                // Clear the dropdown
                pickupSelect.innerHTML = '<option value="">Select Pickup Location</option>';
                
                // Add Hotels
                if (hotelsData.success && hotelsData.hotels && hotelsData.hotels.length > 0) {
                    const hotelGroup = document.createElement('optgroup');
                    hotelGroup.label = 'Hotels';
                    
                    hotelsData.hotels.forEach(hotel => {
                        const option = document.createElement('option');
                        option.value = hotel.hotel_unique_id;
                        option.textContent = hotel.name;
                        option.setAttribute('data-type', 'Hotel');
                        option.setAttribute('data-hotel', JSON.stringify(hotel));
                        if (hotel.zone_id) {
                            option.setAttribute('data-zone-id', hotel.zone_id);
                        }
                        hotelGroup.appendChild(option);
                    });
                    
                    pickupSelect.appendChild(hotelGroup);
                }
                
                // Add Attractions
                if (attractionsData.success && attractionsData.attractions && attractionsData.attractions.length > 0) {
                    const attractionGroup = document.createElement('optgroup');
                    attractionGroup.label = 'Attractions';
                    
                    attractionsData.attractions.forEach(attraction => {
                        const option = document.createElement('option');
                        option.value = attraction.attraction_id;
                        option.textContent = attraction.name;
                        option.setAttribute('data-type', 'Attraction');
                        option.setAttribute('data-attraction', JSON.stringify(attraction));
                        attractionGroup.appendChild(option);
                    });
                    
                    pickupSelect.appendChild(attractionGroup);
                }
                
                // Add Restaurants
                if (restaurantsData.success && restaurantsData.restaurants && restaurantsData.restaurants.length > 0) {
                    const restaurantGroup = document.createElement('optgroup');
                    restaurantGroup.label = 'Restaurants';
                    
                    restaurantsData.restaurants.forEach(restaurant => {
                        const option = document.createElement('option');
                        option.value = restaurant.restaurant_id;
                        option.textContent = restaurant.name;
                        option.setAttribute('data-type', 'Restaurant');
                        option.setAttribute('data-restaurant', JSON.stringify(restaurant));
                        restaurantGroup.appendChild(option);
                    });
                    
                    pickupSelect.appendChild(restaurantGroup);
                }
                
                pickupSelect.disabled = false;

                // If user has selected a hotel previously, default pickup to that hotel (last one)
                if (lastSelectedHotelId) {
                    let defaultValue = null;
                    Array.from(pickupSelect.options).forEach(opt => {
                        if (opt.value === String(lastSelectedHotelId)) {
                            defaultValue = opt.value;
                        }
                    });

                    if (defaultValue) {
                        pickupSelect.value = defaultValue;
                        // Trigger change so pricing updates
                        pickupSelect.dispatchEvent(new Event('change', { bubbles: true }));
                    }
                }

                console.log(`Loaded pickup locations for restaurant transfer in ${cityName}`);
            })
            .catch(error => {
                console.error('Error loading pickup locations for restaurant transfer:', error);
                pickupSelect.innerHTML = '<option disabled>Error loading locations</option>';
                pickupSelect.disabled = false;
            });
        }

        window.loadTransportZonesForCity = function(day, cityName, index) {
            console.log(`=== LOADING TRANSPORT ZONES FOR CITY: ${cityName}, INDEX: ${index} ===`);

            // Scope to live services bundle only. Duplicate name="dayX_transport_*" can exist in frozen
            // segment snapshots; document.querySelector would match the wrong (first) row.
            const bundleRoot = document.getElementById('segmentServicesBundle');
            const qs = function (sel) {
                return bundleRoot ? bundleRoot.querySelector(sel) : document.querySelector(sel);
            };
            
            // For dynamic transport (index > 0), only target specific elements
            // For static transport (index = 0 or undefined), only target static elements
            let pickupSelect, dropoffSelect;
            
            if (index && index > 0) {
                // Dynamic transport - only target specific dynamic elements
                pickupSelect = qs(`[name="day${day}_transport_${index}_pickup_zone_id"]`);
                dropoffSelect = qs(`[name="day${day}_transport_${index}_dropoff_zone_id"]`);
                console.log('Targeting dynamic transport elements for index:', index);
            } else {
                // Static transport - only target static elements
                pickupSelect = qs(`[name="day${day}_transport_pickup_zone_id"]`);
                dropoffSelect = qs(`[name="day${day}_transport_dropoff_zone_id"]`);
                console.log('Targeting static transport elements');
            }
            
            const cityMessage = document.getElementById(`day${day}_transport_city_message_${index}`);
            
            console.log('Transport zone selectors found:', {
                pickup: pickupSelect ? pickupSelect.name : 'NOT FOUND',
                dropoff: dropoffSelect ? dropoffSelect.name : 'NOT FOUND',
                cityMessage: cityMessage ? 'FOUND' : 'NOT FOUND'
            });

            const destroySelect2IfAny = function (el) {
                if (!el || typeof $ === 'undefined') return;
                try {
                    var $e = $(el);
                    if ($e.data('select2')) {
                        $e.select2('destroy');
                    }
                } catch (e) { /* ignore */ }
            };
            
            if (cityName) {
                if (pickupSelect) {
                    pickupSelect.disabled = false;
                    destroySelect2IfAny(pickupSelect);
                    destroySelect2IfAny(dropoffSelect);
                    pickupSelect.innerHTML = '<option value="">Loading pickup locations...</option>';
                    console.log('Pickup select updated for:', pickupSelect.name);
                }
                if (dropoffSelect) {
                    dropoffSelect.innerHTML = '<option value="">Select pickup location first</option>';
                    dropoffSelect.disabled = true;
                    console.log('Dropoff select reset for:', dropoffSelect.name);
                }
                if (cityMessage) {
                    cityMessage.style.display = 'none';
                    console.log('City message hidden for index:', index);
                }
                
                // Check if hourly service type is selected and validate hourly fields
                const fieldIndex = (index === null || index === undefined) ? 0 : index;
                // For static transport (index 0), service type radio name doesn't include index
                // For dynamic transport (index > 0), service type radio name includes index
                let hourlyRadio;
                if (fieldIndex === 0) {
                    hourlyRadio = qs(`input[name="day${day}_transport_service_type"][value="hourly"]`);
                } else {
                    hourlyRadio = qs(`input[name="day${day}_transport_${fieldIndex}_service_type"][value="hourly"]`);
                }
                
                if (hourlyRadio && hourlyRadio.checked) {
                    // Hourly service is selected, check if all hourly fields are filled
                    const sectionName = fieldIndex === 0 ? 'transport_hourly' : `transport_${fieldIndex}_hourly`;
                    setTimeout(() => {
                        enableSearchButton(day, sectionName, fieldIndex);
                    }, 100);
                }
                
                // Load zones for the specific city
                const currentDmcId = '{{ $finalDmcId }}';
                
                fetch(`{{ route('fetch-zones-by-dmc') }}?city=${encodeURIComponent(cityName)}&dmc_id=${currentDmcId}`)
                    .then(response => response.json())
                    .then(data => {
                        if (pickupSelect) {
                            console.log(`Updating pickup select for ${pickupSelect.name} with zones data`);
                            destroySelect2IfAny(pickupSelect);
                            pickupSelect.innerHTML = '<option value="">Select pickup zone</option>';
                            
                            if (data.success && data.zones) {
                                data.zones.forEach(zone => {
                                    const zId = zone.zone_id ?? zone.id;
                                    const zName = zone.zone_name ?? zone.name;
                                    const zType = (zone.zone_type ?? zone.type ?? '').toLowerCase();
                                    const option = document.createElement('option');
                                    option.value = zId;
                                    option.textContent = `${zName} (${zType || 'zone'})`;
                                    if (zType) option.setAttribute('data-type', zType);
                                    pickupSelect.appendChild(option);
                                });
                                console.log(`Loaded ${data.zones.length} zones for ${cityName} into ${pickupSelect.name}`);
                            } else {
                                pickupSelect.innerHTML += '<option disabled>No zones found in this city</option>';
                                console.log(`No zones found for ${cityName} in ${pickupSelect.name}`);
                            }
                            
                            pickupSelect.disabled = false;
                        } else {
                            console.log('No pickup select found to update with zones data');
                        }
                        
                        // After zones are loaded, check hourly fields again if hourly service is selected
                        if (hourlyRadio && hourlyRadio.checked) {
                            const sectionName = fieldIndex === 0 ? 'transport_hourly' : `transport_${fieldIndex}_hourly`;
                            setTimeout(() => {
                                enableSearchButton(day, sectionName, fieldIndex);
                            }, 100);
                        }
                    })
                    .catch(error => {
                        console.error('Error loading zones for city:', error);
                        if (pickupSelect) {
                            destroySelect2IfAny(pickupSelect);
                            pickupSelect.innerHTML = '<option disabled>Error loading zones</option>';
                            pickupSelect.disabled = false;
                        }
                    });
            } else {
                if (pickupSelect) {
                    pickupSelect.disabled = true;
                    destroySelect2IfAny(pickupSelect);
                    destroySelect2IfAny(dropoffSelect);
                    pickupSelect.innerHTML = '<option value="">Select city first</option>';
                }
                if (dropoffSelect) {
                    dropoffSelect.innerHTML = '<option value="">Select city and pickup location first</option>';
                }
                if (cityMessage) {
                    cityMessage.style.display = 'block';
                }
            }
        };

        // Function to validate and clean services when travel dates change
        // Function to recalculate hotel prices based on new nights
        function recalculateHotelPrices(hotel, newNights) {
            if (!hotel || !newNights || newNights.length === 0) {
                console.warn('Cannot recalculate hotel prices: missing hotel or nights data');
                return;
            }
            
            // Get price information from hotel's stored data
            let weekdayPrice = hotel.weekdayPrice || 0;
            let weekendPrice = hotel.weekendPrice || 0;
            
            // If stored prices not available, try to extract from priceBreakdown
            if (weekdayPrice === 0 && weekendPrice === 0 && hotel.priceBreakdown && hotel.priceBreakdown.length > 0) {
                const weekdayNight = hotel.priceBreakdown.find(n => !n.isWeekend);
                const weekendNight = hotel.priceBreakdown.find(n => n.isWeekend);
                weekdayPrice = weekdayNight ? weekdayNight.price : 0;
                weekendPrice = weekendNight ? weekendNight.price : 0;
            }
            
            // If still no prices, we can't recalculate - keep existing values
            if (weekdayPrice === 0 && weekendPrice === 0) {
                console.warn('Cannot recalculate hotel prices: no price data available');
                return;
            }
            
            // Recalculate prices for new nights
            let totalRoomPrice = 0;
            let priceBreakdown = [];
            let weekdayNights = 0;
            let weekendNights = 0;
            
            newNights.forEach(nightNum => {
                const nightDate = moment(getHotelNightPlanStart()).add(nightNum - 1, 'days');
                
                // Determine weekend based on hotel's configured weekend_days
                const isWeekend = isWeekendForSelectedHotel(nightDate);
                
                const nightPrice = isWeekend ? weekendPrice : weekdayPrice;
                totalRoomPrice += nightPrice;
                
                if (isWeekend) {
                    weekendNights++;
                } else {
                    weekdayNights++;
                }
                
                priceBreakdown.push({
                    night: nightNum,
                    date: nightDate.format('MMM DD'),
                    dayOfWeek: nightDate.format('ddd'),
                    isWeekend: isWeekend,
                    price: nightPrice
                });
            });
            
            // Update hotel object with recalculated values
            hotel.price = totalRoomPrice;
            hotel.pricePerNight = totalRoomPrice / newNights.length;
            hotel.priceBreakdown = priceBreakdown;
            hotel.weekdayNights = weekdayNights;
            hotel.weekendNights = weekendNights;
            
            console.log(`🔄 Recalculated hotel "${hotel.name}" prices:`, {
                totalNights: newNights.length,
                weekdayNights: weekdayNights,
                weekendNights: weekendNights,
                totalPrice: totalRoomPrice
            });
        }
        
        function validateAndCleanServicesOnDateChange(newStartDate, newEndDate) {
            console.log('🔍 Validating services for new date range:', newStartDate, 'to', newEndDate);
            
            let removedServices = {
                hotels: 0,
                attractions: 0,
                restaurants: 0,
                guides: 0
            };
            
            // Helper function to check if a date is within range
            function isDateInRange(dateStr, startDate, endDate) {
                // Extract year from range dates
                const rangeYear = moment(startDate).year();
                
                // Parse service date with the correct year
                const date = moment(dateStr + ' ' + rangeYear, 'MMM DD YYYY');
                const start = moment(startDate);
                const end = moment(endDate);
                
                const inRange = date.isSameOrAfter(start, 'day') && date.isSameOrBefore(end, 'day');
                
                console.log('Checking date in range:', {
                    serviceDate: date.format('YYYY-MM-DD'),
                    rangeStart: start.format('YYYY-MM-DD'),
                    rangeEnd: end.format('YYYY-MM-DD'),
                    inRange: inRange
                });
                
                return inRange;
            }
            
            // Helper function to check if service dates overlap with new range
            function serviceDatesOverlap(serviceStartDate, serviceEndDate, rangeStart, rangeEnd) {
                // Extract year from range dates
                const rangeYear = moment(rangeStart).year();
                
                // Parse service dates with the correct year
                const sStart = moment(serviceStartDate + ' ' + rangeYear, 'MMM DD YYYY');
                const sEnd = moment(serviceEndDate + ' ' + rangeYear, 'MMM DD YYYY');
                const rStart = moment(rangeStart);
                const rEnd = moment(rangeEnd);
                
                console.log('Checking hotel overlap:', {
                    serviceStart: sStart.format('YYYY-MM-DD'),
                    serviceEnd: sEnd.format('YYYY-MM-DD'),
                    rangeStart: rStart.format('YYYY-MM-DD'),
                    rangeEnd: rEnd.format('YYYY-MM-DD')
                });
                
                // Check if there's any overlap
                const hasOverlap = sStart.isSameOrBefore(rEnd, 'day') && sEnd.isSameOrAfter(rStart, 'day');
                console.log('Has overlap:', hasOverlap);
                
                return hasOverlap;
            }
            
            // 1. VALIDATE AND UPDATE HOTELS
            if (selectedHotels && selectedHotels.length > 0) {
                const hotelsToRemove = [];
                let hotelsUpdated = false;
                
                selectedHotels.forEach((hotel, index) => {
                    if (hotel.checkInDate && hotel.checkOutDate) {
                        // Parse hotel dates
                        const rangeYear = moment(newStartDate).year();
                        const hotelStart = moment(hotel.checkInDate + ' ' + rangeYear, 'MMM DD YYYY');
                        const hotelEnd = moment(hotel.checkOutDate + ' ' + rangeYear, 'MMM DD YYYY');
                        const hotelNights = hotelEnd.diff(hotelStart, 'days');
                        
                        const newRangeStart = moment(newStartDate);
                        const newRangeEnd = moment(newEndDate);
                        const newRangeNights = newRangeEnd.diff(newRangeStart, 'days');
                        
                        // Check if hotel dates overlap with new range
                        const hotelInRange = serviceDatesOverlap(
                            hotel.checkInDate, 
                            hotel.checkOutDate, 
                            newStartDate, 
                            newEndDate
                        );
                        
                        if (!hotelInRange) {
                            // Hotel is completely outside new range - remove it
                            console.log(`❌ Hotel "${hotel.name}" (${hotel.checkInDate} - ${hotel.checkOutDate}) is outside new date range. Removing...`);
                            hotelsToRemove.push(index);
                            removedServices.hotels++;
                        } else {
                            // Hotel is within range - update its dates to start from first day of new range
                            const nightsToUse = Math.min(hotelNights, newRangeNights);
                            const updatedCheckIn = newRangeStart.clone();
                            const updatedCheckOut = newRangeStart.clone().add(nightsToUse, 'days');
                            
                            console.log(`🔄 Updating hotel "${hotel.name}" dates from ${hotel.checkInDate} - ${hotel.checkOutDate} to ${updatedCheckIn.format('MMM DD')} - ${updatedCheckOut.format('MMM DD')}`);
                            
                            // Update hotel dates
                            hotel.checkInDate = updatedCheckIn.format('MMM DD');
                            hotel.checkOutDate = updatedCheckOut.format('MMM DD');
                            hotel.totalNights = nightsToUse;
                            
                            // Update nights array to match new dates
                            const newNights = [];
                            for (let i = 1; i <= nightsToUse; i++) {
                                newNights.push(i);
                            }
                            hotel.nights = newNights;
                            
                            // Recalculate hotel prices based on new nights
                            recalculateHotelPrices(hotel, newNights);
                            
                            hotelsUpdated = true;
                        }
                    }
                });
                
                // Remove hotels in reverse order to maintain indices
                hotelsToRemove.reverse().forEach(index => {
                    selectedHotels.splice(index, 1);
                });
                
                // Update hotel display if hotels were removed or updated
                if (hotelsToRemove.length > 0 || hotelsUpdated) {
                    displaySelectedHotels();
                }
            }
            
            // 2. VALIDATE ATTRACTIONS
            if (selectedAttractions && selectedAttractions.length > 0) {
                const attractionsToRemove = [];
                
                selectedAttractions.forEach((attraction, index) => {
                    if (attraction.date) {
                        const attractionInRange = isDateInRange(attraction.date, newStartDate, newEndDate);
                        
                        if (!attractionInRange) {
                            console.log(`❌ Attraction "${attraction.name}" (${attraction.date}) is outside new date range. Removing...`);
                            attractionsToRemove.push(index);
                            removedServices.attractions++;
                        }
                    }
                });
                
                attractionsToRemove.reverse().forEach(index => {
                    selectedAttractions.splice(index, 1);
                });
                
                if (attractionsToRemove.length > 0) {
                    displaySelectedAttractions();
                }
            }
            
            // 3. VALIDATE RESTAURANTS
            if (selectedRestaurants && selectedRestaurants.length > 0) {
                const restaurantsToRemove = [];
                
                selectedRestaurants.forEach((restaurant, index) => {
                    if (restaurant.date) {
                        const restaurantInRange = isDateInRange(restaurant.date, newStartDate, newEndDate);
                        
                        if (!restaurantInRange) {
                            console.log(`❌ Restaurant "${restaurant.name}" (${restaurant.date}) is outside new date range. Removing...`);
                            restaurantsToRemove.push(index);
                            removedServices.restaurants++;
                        }
                    }
                });
                
                restaurantsToRemove.reverse().forEach(index => {
                    selectedRestaurants.splice(index, 1);
                });
                
                if (restaurantsToRemove.length > 0) {
                    displaySelectedRestaurants();
                }
            }
            
            // 4. VALIDATE GUIDES
            if (selectedGuides && selectedGuides.length > 0) {
                const guidesToRemove = [];
                
                selectedGuides.forEach((guide, index) => {
                    if (guide.date) {
                        const guideInRange = isDateInRange(guide.date, newStartDate, newEndDate);
                        
                        if (!guideInRange) {
                            console.log(`❌ Guide "${guide.name}" (${guide.date}) is outside new date range. Removing...`);
                            guidesToRemove.push(index);
                            removedServices.guides++;
                        }
                    }
                });
                
                guidesToRemove.reverse().forEach(index => {
                    selectedGuides.splice(index, 1);
                });
                
                if (guidesToRemove.length > 0) {
                    displaySelectedGuides();
                }
            }
            
            // 5. Recalculate total price
            calculateTotalPackagePrice();
            
            // 6. Show notification if services were removed
            const totalRemoved = removedServices.hotels + removedServices.attractions + 
                                removedServices.restaurants + removedServices.guides;
            
            if (totalRemoved > 0) {
                let message = '⚠️ Travel dates changed! Removed services outside new date range:\n\n';
                if (removedServices.hotels > 0) message += `• ${removedServices.hotels} Hotel(s)\n`;
                if (removedServices.attractions > 0) message += `• ${removedServices.attractions} Attraction(s)\n`;
                if (removedServices.restaurants > 0) message += `• ${removedServices.restaurants} Restaurant(s)\n`;
                if (removedServices.guides > 0) message += `• ${removedServices.guides} Guide(s)\n`;
                message += '\nPlease select services within the new date range.';
                
                showNotification(message, 'warning');
                
                console.log('✅ Service cleanup completed:', removedServices);
            } else {
                console.log('✅ All services are within new date range. No cleanup needed.');
            }
        }

            // Wait for all dependencies to load
        $(document).ready(function() {
            // Date Range Picker Initialization - only if not locked
            const travelDatesField = $('#travel_dates');
            if (travelDatesField.attr('data-locked') !== 'true') {
                travelDatesField.daterangepicker({
                    opens: 'left',
                    autoUpdateInput: false,
                    minDate: moment(),
                    locale: {
                        format: 'MMM DD, YYYY',
                        cancelLabel: 'Clear'
                    }
                });
            }

            // Function to check which services will be removed (without actually removing them)
            function checkServicesToRemove(newStartDate, newEndDate) {
                const servicesToRemove = {
                    hotels: [],
                    attractions: [],
                    restaurants: [],
                    guides: []
                };
                
                const servicesToUpdate = {
                    hotels: []
                };
                
                // Helper function to check if service dates overlap with new range
                function serviceDatesOverlap(serviceStartDate, serviceEndDate, rangeStart, rangeEnd) {
                    const rangeYear = moment(rangeStart).year();
                    const sStart = moment(serviceStartDate + ' ' + rangeYear, 'MMM DD YYYY');
                    const sEnd = moment(serviceEndDate + ' ' + rangeYear, 'MMM DD YYYY');
                    const rStart = moment(rangeStart);
                    const rEnd = moment(rangeEnd);
                    return sStart.isSameOrBefore(rEnd, 'day') && sEnd.isSameOrAfter(rStart, 'day');
                }
                
                // Helper function to check if a date is within range
                function isDateInRange(dateStr, startDate, endDate) {
                    const rangeYear = moment(startDate).year();
                    const date = moment(dateStr + ' ' + rangeYear, 'MMM DD YYYY');
                    const start = moment(startDate);
                    const end = moment(endDate);
                    return date.isSameOrAfter(start, 'day') && date.isSameOrBefore(end, 'day');
                }
                
                // Check hotels
                if (selectedHotels && selectedHotels.length > 0) {
                    selectedHotels.forEach((hotel, index) => {
                        if (hotel.checkInDate && hotel.checkOutDate) {
                            const rangeYear = moment(newStartDate).year();
                            const hotelStart = moment(hotel.checkInDate + ' ' + rangeYear, 'MMM DD YYYY');
                            const hotelEnd = moment(hotel.checkOutDate + ' ' + rangeYear, 'MMM DD YYYY');
                            const hotelNights = hotelEnd.diff(hotelStart, 'days');
                            
                            const newRangeStart = moment(newStartDate);
                            const newRangeEnd = moment(newEndDate);
                            const newRangeNights = newRangeEnd.diff(newRangeStart, 'days');
                            
                            const hotelInRange = serviceDatesOverlap(
                                hotel.checkInDate, 
                                hotel.checkOutDate, 
                                newStartDate, 
                                newEndDate
                            );
                            
                            if (!hotelInRange) {
                                // Hotel will be removed
                                servicesToRemove.hotels.push({
                                    index: index,
                                    name: hotel.name,
                                    dates: `${hotel.checkInDate} - ${hotel.checkOutDate}`
                                });
                            } else {
                                // Hotel will be updated - calculate new dates
                                const nightsToUse = Math.min(hotelNights, newRangeNights);
                                const updatedCheckIn = newRangeStart.clone();
                                const updatedCheckOut = newRangeStart.clone().add(nightsToUse, 'days');
                                
                                // Only add to update list if dates actually change
                                if (hotel.checkInDate !== updatedCheckIn.format('MMM DD') || 
                                    hotel.checkOutDate !== updatedCheckOut.format('MMM DD')) {
                                    servicesToUpdate.hotels.push({
                                        index: index,
                                        name: hotel.name,
                                        oldDates: `${hotel.checkInDate} - ${hotel.checkOutDate}`,
                                        newDates: `${updatedCheckIn.format('MMM DD')} - ${updatedCheckOut.format('MMM DD')}`,
                                        nights: nightsToUse
                                    });
                                }
                            }
                        }
                    });
                }
                
                // Check attractions
                if (selectedAttractions && selectedAttractions.length > 0) {
                    selectedAttractions.forEach((attraction, index) => {
                        if (attraction.date) {
                            const attractionInRange = isDateInRange(attraction.date, newStartDate, newEndDate);
                            if (!attractionInRange) {
                                servicesToRemove.attractions.push({
                                    index: index,
                                    name: attraction.name,
                                    date: attraction.date
                                });
                            }
                        }
                    });
                }
                
                // Check restaurants
                if (selectedRestaurants && selectedRestaurants.length > 0) {
                    selectedRestaurants.forEach((restaurant, index) => {
                        if (restaurant.date) {
                            const restaurantInRange = isDateInRange(restaurant.date, newStartDate, newEndDate);
                            if (!restaurantInRange) {
                                servicesToRemove.restaurants.push({
                                    index: index,
                                    name: restaurant.name,
                                    date: restaurant.date
                                });
                            }
                        }
                    });
                }
                
                // Check guides
                if (selectedGuides && selectedGuides.length > 0) {
                    selectedGuides.forEach((guide, index) => {
                        if (guide.date) {
                            const guideInRange = isDateInRange(guide.date, newStartDate, newEndDate);
                            if (!guideInRange) {
                                servicesToRemove.guides.push({
                                    index: index,
                                    name: guide.name,
                                    date: guide.date
                                });
                            }
                        }
                    });
                }
                
                return {
                    toRemove: servicesToRemove,
                    toUpdate: servicesToUpdate
                };
            }
            
            // Function to apply date changes after confirmation
            function applyDateChanges(picker, newStartDate, newEndDate) {
                const travelDatesInput = document.getElementById('travel_dates');
                
                // Update the input field
                $(travelDatesInput).val(picker.startDate.format('MMM DD') + ' - ' + picker.endDate.format('MMM DD, YYYY'));
                
                // Set hidden date fields
                document.getElementById('start_date').value = newStartDate;
                document.getElementById('end_date').value = newEndDate;
                // Hidden fields are updated programmatically, so trigger listeners that depend on them.
                $('#start_date').trigger('change');
                $('#end_date').trigger('change');
                if (typeof window.updateAddCityPlanButtonState === 'function') {
                    window.updateAddCityPlanButtonState();
                }
                
                // Update global variables
                tourStartDate = newStartDate;
                tourEndDate = newEndDate;
                tourNights = picker.endDate.diff(picker.startDate, 'days');
                
                // Update the hotel section date display
                document.getElementById('tourDates').textContent = picker.startDate.format('MMM DD') + ' - ' + picker.endDate.format('MMM DD, YYYY');
                document.getElementById('hotelNights').textContent = tourNights + ' Nights Selected';
                
                // Generate night selection buttons FIRST (before validation)
                generateNightSelection();
                // Initialize night display
                updateNightDisplay();
                
                // Generate daily services for transport section
                generateDailyServices();
                populatePortsDropdowns();
                
                // Validate and clean up services outside new date range
                validateAndCleanServicesOnDateChange(newStartDate, newEndDate);
            }

            // Only attach event handlers if field is not locked
            if (travelDatesField.attr('data-locked') !== 'true') {
                $('#travel_dates').on('apply.daterangepicker', function(ev, picker) {
                    const newStartDate = picker.startDate.format('YYYY-MM-DD');
                    const newEndDate = picker.endDate.format('YYYY-MM-DD');
                    
                    // Check if dates have actually changed
                    const oldStartDate = tourStartDate;
                    const oldEndDate = tourEndDate;
                    const datesChanged = (oldStartDate !== newStartDate || oldEndDate !== newEndDate);
                    
                    // If dates haven't changed, just return
                    if (!datesChanged) {
                        return;
                    }
                    
                    // Check if there are any selected services
                    const hasServices = (selectedHotels && selectedHotels.length > 0) ||
                                    (selectedAttractions && selectedAttractions.length > 0) ||
                                    (selectedRestaurants && selectedRestaurants.length > 0) ||
                                    (selectedGuides && selectedGuides.length > 0);
                    
                    if (hasServices) {
                        // Check which services will be removed or updated
                        const serviceChanges = checkServicesToRemove(newStartDate, newEndDate);
                        const servicesToRemove = serviceChanges.toRemove;
                        const servicesToUpdate = serviceChanges.toUpdate;
                        
                        const totalToRemove = servicesToRemove.hotels.length + 
                                            servicesToRemove.attractions.length + 
                                            servicesToRemove.restaurants.length + 
                                            servicesToRemove.guides.length;
                        
                        const totalToUpdate = servicesToUpdate.hotels.length;
                        
                        // Show alert if services will be removed or updated
                        if (totalToRemove > 0 || totalToUpdate > 0) {
                            // Build alert message
                            let message = '⚠️ WARNING: Changing travel dates will affect the following services:\n\n';
                            
                            // Show hotels that will be updated
                            if (servicesToUpdate.hotels.length > 0) {
                                message += `🔄 Hotels to be UPDATED (${servicesToUpdate.hotels.length}):\n`;
                                servicesToUpdate.hotels.forEach(hotel => {
                                    message += `   • ${hotel.name}\n`;
                                    message += `     ${hotel.oldDates} → ${hotel.newDates} (${hotel.nights} nights)\n`;
                                });
                                message += '\n';
                            }
                            
                            // Show services that will be removed
                            if (servicesToRemove.hotels.length > 0) {
                                message += `🏨 Hotels to be REMOVED (${servicesToRemove.hotels.length}):\n`;
                                servicesToRemove.hotels.forEach(hotel => {
                                    message += `   • ${hotel.name} (${hotel.dates})\n`;
                                });
                                message += '\n';
                            }
                            
                            if (servicesToRemove.attractions.length > 0) {
                                message += `🎯 Attractions to be REMOVED (${servicesToRemove.attractions.length}):\n`;
                                servicesToRemove.attractions.forEach(attraction => {
                                    message += `   • ${attraction.name} (${attraction.date})\n`;
                                });
                                message += '\n';
                            }
                            
                            if (servicesToRemove.restaurants.length > 0) {
                                message += `🍽️ Restaurants to be REMOVED (${servicesToRemove.restaurants.length}):\n`;
                                servicesToRemove.restaurants.forEach(restaurant => {
                                    message += `   • ${restaurant.name} (${restaurant.date})\n`;
                                });
                                message += '\n';
                            }
                            
                            if (servicesToRemove.guides.length > 0) {
                                message += `👤 Guides to be REMOVED (${servicesToRemove.guides.length}):\n`;
                                servicesToRemove.guides.forEach(guide => {
                                    message += `   • ${guide.name} (${guide.date})\n`;
                                });
                                message += '\n';
                            }
                            
                            message += `\nNew Date Range: ${picker.startDate.format('MMM DD, YYYY')} - ${picker.endDate.format('MMM DD, YYYY')}\n\n`;
                            
                            if (totalToRemove > 0 && totalToUpdate > 0) {
                                message += 'Do you want to proceed? Hotels within range will be updated, and services outside range will be permanently removed.';
                            } else if (totalToUpdate > 0) {
                                message += 'Do you want to proceed? Hotel dates will be updated to match the new date range.';
                            } else {
                                message += 'Do you want to proceed? These services will be permanently removed.';
                            }
                            
                            // Show confirmation dialog
                            if (confirm(message)) {
                                // User confirmed - apply the changes
                                applyDateChanges(picker, newStartDate, newEndDate);
                            } else {
                                // User cancelled - revert the date picker to old dates
                                const travelDatesInput = $(this);
                                
                                // Revert the picker to previous dates
                                if (oldStartDate && oldEndDate) {
                                    const oldStart = moment(oldStartDate);
                                    const oldEnd = moment(oldEndDate);
                                    
                                    // Set the picker back to old dates
                                    picker.setStartDate(oldStart);
                                    picker.setEndDate(oldEnd);
                                    
                                    // Update the input field to show old dates
                                    travelDatesInput.val(oldStart.format('MMM DD') + ' - ' + oldEnd.format('MMM DD, YYYY'));
                                    
                                    // Keep hidden fields as old dates
                                    document.getElementById('start_date').value = oldStartDate;
                                    document.getElementById('end_date').value = oldEndDate;
                                } else {
                                    // If no old dates, clear the field
                                    travelDatesInput.val('');
                                    document.getElementById('start_date').value = '';
                                    document.getElementById('end_date').value = '';
                                }
                                
                                console.log('❌ Date change cancelled by user');
                                return false;
                            }
                        } else {
                            // No services to remove - apply changes directly
                            applyDateChanges(picker, newStartDate, newEndDate);
                        }
                    } else {
                        // No services selected - apply changes directly
                        applyDateChanges(picker, newStartDate, newEndDate);
                    }
                });

                $('#travel_dates').on('cancel.daterangepicker', function(ev, picker) {
                    $(this).val('');
                    document.getElementById('start_date').value = '';
                    document.getElementById('end_date').value = '';
                    $('#start_date').trigger('change');
                    $('#end_date').trigger('change');
                    if (typeof window.updateAddCityPlanButtonState === 'function') {
                        window.updateAddCityPlanButtonState();
                    }
                    tourStartDate = null;
                    tourEndDate = null;
                    tourNights = 0;
                });
            } else {
                // If field is locked with enquiry data, set the global variables
                @if($enquiry && $enquiry->check_in_time && $enquiry->check_out_time)
                tourStartDate = moment('{{ \Carbon\Carbon::parse($enquiry->check_in_time)->format('Y-m-d') }}');
                tourEndDate = moment('{{ \Carbon\Carbon::parse($enquiry->check_out_time)->format('Y-m-d') }}');
                tourNights = tourEndDate.diff(tourStartDate, 'days');
                
                // Update the hotel section date display
                if (document.getElementById('tourDates')) {
                    document.getElementById('tourDates').textContent = '{{ \Carbon\Carbon::parse($enquiry->check_in_time)->format('M d') }} - {{ \Carbon\Carbon::parse($enquiry->check_out_time)->format('M d, Y') }}';
                }
                if (document.getElementById('hotelNights')) {
                    document.getElementById('hotelNights').textContent = tourNights + ' Nights Selected';
                }
                
                // Generate night selection buttons for enquiry data
                generateNightSelection();
                updateNightDisplay();
                @endif
            }
        });

            // Update total adults count and hidden field
            const updateAdultsCount = () => {
