            // Add Hotel Function
        window.addHotel = function() {
            // Check if travel dates are set
            if (!tourStartDate) {
                alert('Please add travel dates first before adding hotels.');
                return;
            }
            
            // Check if guests (pax) are added
            const adults = parseInt(document.getElementById('adults').value) || 0;
            const children = parseInt(document.getElementById('children').value) || 0;
            const totalGuests = adults + children;
            
            if (totalGuests === 0) {
                alert('Please add guests (PAX) first before adding hotels.');
                return;
            }
            
            const hotelSelect = document.getElementById('hotelSelect');
            const roomType = document.getElementById('roomTypeSelect').value;
            const bedType = document.getElementById('bedTypeSelect').value;
            const mealPlan = document.getElementById('mealPlanSelect').value;
            const selectedPersons = document.getElementById('selectedPersons').value || '1';
            // Get number of rooms from the input field
            const numberOfRoomsInput = document.getElementById('numberOfRooms');
            let numberOfRooms = 1; // default
            if (numberOfRoomsInput) {
                numberOfRooms = parseInt(numberOfRoomsInput.value) || 1;
            }
            console.log(`Number of rooms from user input: ${numberOfRooms} rooms`);
            
            if (!hotelSelect.value) {
                showNotification('Please select a hotel first.', 'warning');
                return;
            }
            
            const selectedNights = document.querySelectorAll('.night-btn.active');
            if (selectedNights.length === 0) {
                showNotification('Please select at least one night for this hotel.', 'warning');
                return;
            }
            
            // Get selected night numbers and dates
            const nightNumbers = Array.from(selectedNights).map(btn => parseInt(btn.dataset.night));
            nightNumbers.sort((a, b) => a - b);
            
            const startNight = Math.min(...nightNumbers);
            const endNight = Math.max(...nightNumbers);
            // IMPORTANT: in multi-city mode, hotel nights are relative to the active segment stay start
            // (window.multiSegmentStayRange.start). Using tourStartDate here causes wrong ranges to be stored.
            const __hotelPlanStart = getHotelNightPlanStart();
            const checkInDate = moment(__hotelPlanStart).add(startNight-1, 'days');
            const checkOutDate = moment(__hotelPlanStart).add(endNight, 'days');
            
            // Get bed information if available
            const bedInfo = window.selectedBedInfo || {};
            
            // Calculate price per night based on each night's day of the week
            const roomTypeSelect = document.getElementById('roomTypeSelect');
            let totalRoomPrice = 0;
            let priceBreakdown = [];
            let weekdayNights = 0;
            let weekendNights = 0;
            
            if (roomTypeSelect && roomTypeSelect.value === roomType) {
                const selectedOption = roomTypeSelect.options[roomTypeSelect.selectedIndex];
                if (selectedOption && selectedOption.dataset) {
                    // Get guest count to determine single vs double occupancy
                    const adults = parseInt(document.getElementById('adults').value) || 0;
                    const children = parseInt(document.getElementById('children').value) || 0;
                    const totalGuests = adults + children;
                    
                    // Determine if single or double occupancy
                    const isSingleOccupancy = totalGuests <= 1;
                    
                    // Get prices from dataset
                    const weekdayPrice = isSingleOccupancy 
                        ? parseFloat(selectedOption.dataset.weekdayPrice) || 0
                        : parseFloat(selectedOption.dataset.doubleWeekdayPrice) || 0;
                    const weekendPrice = isSingleOccupancy 
                        ? parseFloat(selectedOption.dataset.weekendPrice) || 0
                        : parseFloat(selectedOption.dataset.doubleWeekendPrice) || 0;
                    
            // Calculate price for each selected night
            nightNumbers.forEach(nightNum => {
                const nightDate = moment(getHotelNightPlanStart()).add(nightNum-1, 'days');
                
                // Determine weekend based on hotel's configured weekend_days
                const isWeekend = isWeekendForSelectedHotel(nightDate);
                
                const nightPrice = isWeekend ? weekendPrice : weekdayPrice;
                totalRoomPrice += nightPrice;
                
                if (isWeekend) {
                    weekendNights++;
                } else {
                    weekdayNights++;
                }
                
                priceBreakdown.push({
                    night: nightNum,
                    date: nightDate.format('MMM DD'),
                    dayOfWeek: nightDate.format('ddd'),
                    isWeekend: isWeekend,
                    price: nightPrice
                });
            });
                    
                    console.log(`=== PRICE BREAKDOWN FOR ${roomType} ===`);
                    console.log(`Total nights: ${nightNumbers.length}`);
                    console.log(`Weekday nights: ${weekdayNights} @ $${weekdayPrice} each`);
                    console.log(`Weekend nights: ${weekendNights} @ $${weekendPrice} each`);
                    console.log(`Total room price: $${totalRoomPrice}`);
                    console.log('Per-night breakdown:', priceBreakdown);
                }
            }
            
            // Validate that we have a valid price
            if (totalRoomPrice <= 0) {
                showNotification('Warning: Room price is $0.00. Please check room type selection.', 'warning');
                console.warn('Room price is 0 or invalid:', totalRoomPrice);
            }
            
            // Get meal price information from the selected room type
            let mealPrices = {
                breakfast_price: 0,
                lunch_price: 0,
                dinner_price: 0
            };
            
            console.log('=== MEAL PRICE FETCHING DEBUG ===');
            console.log('Room type select element:', roomTypeSelect);
            console.log('Room type value:', roomType);
            console.log('Room type select value:', roomTypeSelect ? roomTypeSelect.value : 'N/A');
            
            if (roomTypeSelect && roomTypeSelect.value === roomType) {
                const selectedOption = roomTypeSelect.options[roomTypeSelect.selectedIndex];
                console.log('Selected option:', selectedOption);
                console.log('Selected option dataset:', selectedOption ? selectedOption.dataset : 'N/A');
                
                if (selectedOption && selectedOption.dataset) {
                                    // Get meal prices directly from the room type option dataset
                    // Get meal prices from database (no fallback defaults)
                    mealPrices = {
                        breakfast_price: parseFloat(selectedOption.dataset.breakfastPrice) || 0,
                        lunch_price: parseFloat(selectedOption.dataset.lunchPrice) || 0,
                        dinner_price: parseFloat(selectedOption.dataset.dinnerPrice) || 0
                    };
                    
                    console.log('Meal prices from room type option:', mealPrices);
                    console.log('Dataset values:', {
                        breakfastPrice: selectedOption.dataset.breakfastPrice,
                        lunchPrice: selectedOption.dataset.lunchPrice,
                        dinnerPrice: selectedOption.dataset.dinnerPrice
                    });
                    
                    // Also log the meal availability flags
                    console.log('Meal availability flags:', {
                        breakfast: selectedOption.dataset.breakfast,
                        lunch: selectedOption.dataset.lunch,
                        dinner: selectedOption.dataset.dinner
                    });
                } else {
                    console.warn('No selected option or dataset available');
                }
            } else {
                console.warn('Room type select not found or value mismatch');
            }
            console.log('Bed type in hotel data===:', bedInfo.bedType);
            
            // Capture transfer options at the time this hotel is added
            const transferOptions = window.captureTransferOptions ? window.captureTransferOptions() : null;
            console.log('Transfer options captured for this hotel:', transferOptions);
            
            // Store weekday and weekend prices for recalculation
            let storedWeekdayPrice = 0;
            let storedWeekendPrice = 0;
            if (roomTypeSelect && roomTypeSelect.value === roomType) {
                const selectedOption = roomTypeSelect.options[roomTypeSelect.selectedIndex];
                if (selectedOption && selectedOption.dataset) {
                    const adults = parseInt(document.getElementById('adults').value) || 0;
                    const children = parseInt(document.getElementById('children').value) || 0;
                    const totalGuests = adults + children;
                    const isSingleOccupancy = totalGuests <= 1;
                    
                    storedWeekdayPrice = isSingleOccupancy 
                        ? parseFloat(selectedOption.dataset.weekdayPrice) || 0
                        : parseFloat(selectedOption.dataset.doubleWeekdayPrice) || 0;
                    storedWeekendPrice = isSingleOccupancy 
                        ? parseFloat(selectedOption.dataset.weekendPrice) || 0
                        : parseFloat(selectedOption.dataset.doubleWeekendPrice) || 0;
                }
            }

            const customRoomPrice = document.getElementById('roomPriceDisplay').value;
            // SGD is now a fixed prefix, value is already numeric
            const customRoomPriceNum = parseFloat(customRoomPrice);

            // Child pricing from rooms table (child_with_bed, child_without_bed)
            let childWithBedPrice = 0, childWithoutBedPrice = 0;
            const rtVal = roomTypeSelect ? roomTypeSelect.value : '';
            const rtOpt = rtVal ? Array.from(roomTypeSelect.options || []).find(function(o){ return o.value === rtVal; }) : null;
            if (rtOpt && rtOpt.dataset) {
                childWithBedPrice = parseFloat(rtOpt.dataset.childWithBed) || 0;
                childWithoutBedPrice = parseFloat(rtOpt.dataset.childWithoutBed) || 0;
            }
            if ((childWithBedPrice === 0 || childWithoutBedPrice === 0) && window.roomData && Array.isArray(window.roomData)) {
                const room = window.roomData.find(function(r){ return r.room_type === roomType; });
                if (room) {
                    if (childWithBedPrice === 0) childWithBedPrice = parseFloat(room.child_with_bed) || 0;
                    if (childWithoutBedPrice === 0) childWithoutBedPrice = parseFloat(room.child_without_bed) || 0;
                }
            }
            const chkCwb = document.getElementById('chkChildWithBed');
            const chkCnb = document.getElementById('chkChildWithoutBed');
            const childWithBedEnabled = chkCwb ? chkCwb.checked : false;
            const childWithoutBedEnabled = chkCnb ? chkCnb.checked : false;
            const numChildren = parseInt(document.getElementById('children').value) || 0;

            console.log('Custom room price:', customRoomPrice);
            console.log('Weekday nights*storedWeekdayPrice:', weekdayNights*storedWeekdayPrice);
            console.log('Weekend nights*storedWeekendPrice:', weekendNights*storedWeekendPrice);
            console.log('Total room price (weekday+weekend per room):', totalRoomPrice);
            // Always use the calculated totalRoomPrice (weekday + weekend) so Cost Summary total is correct.
            // Do NOT overwrite with roomPriceDisplay value, which may be stale or weekday-only.
            if (customRoomPriceNum > 0 && Math.abs((customRoomPriceNum / numberOfRooms) - totalRoomPrice) > 0.01) {
                console.log('Syncing room price display to calculated total:', (totalRoomPrice * numberOfRooms).toFixed(2));
                const roomPriceDisplayEl = document.getElementById('roomPriceDisplay');
                if (roomPriceDisplayEl) {
                    roomPriceDisplayEl.value = (totalRoomPrice * numberOfRooms).toFixed(2);
                    roomPriceDisplayEl.dataset.manuallyEdited = 'false';
                }
            }

            // Capture remarks from hotel remarks textarea (below Add button)
            const hotelRemarksInput = document.getElementById('hotel_remarks');
            const hotelRemarks = hotelRemarksInput ? hotelRemarksInput.value : '';
            
            const hotelData = {
                id: hotelSelect.value,
                name: hotelSelect.options[hotelSelect.selectedIndex].text,
                roomType: roomType || 'Standard',
                bedType: bedInfo.bedType || null,
                bedId: bedInfo.bedId || null,
                selectedPersons: parseInt(selectedPersons) || 1,
                maxOccupancy: bedInfo.maxOccupancy || null,
                availableRooms: bedInfo.noOfRooms || null,
                extraBedPrice: bedInfo.extraBedPrice || 0,
                babyCotPrice: bedInfo.babyCotPrice || 0,
                price: totalRoomPrice, // Store the total calculated room price for all nights
                pricePerNight: totalRoomPrice / nightNumbers.length, // Average price per night for reference
                priceBreakdown: priceBreakdown, // Store detailed per-night pricing
                weekdayNights: weekdayNights, // Number of weekday nights
                weekendNights: weekendNights, // Number of weekend nights
                weekdayPrice: storedWeekdayPrice, // Store weekday price for recalculation
                weekendPrice: storedWeekendPrice, // Store weekend price for recalculation
                customRoomPrice: customRoomPriceNum, // Store custom room price for display
                mealPlan: mealPlan || 'Not specified',
                mealPrices: mealPrices, // Store meal prices for calculation
                numberOfRooms: numberOfRooms,
                nights: nightNumbers,
                checkInDate: checkInDate.format('MMM DD'),
                checkOutDate: checkOutDate.format('MMM DD'),
                totalNights: nightNumbers.length,
                transferOptions: transferOptions,
                childWithBedEnabled: childWithBedEnabled,
                childWithoutBedEnabled: childWithoutBedEnabled,
                childWithBedPrice: childWithBedPrice,
                childWithoutBedPrice: childWithoutBedPrice,
                children: numChildren,
                remarks: hotelRemarks
            };
            
            console.log('=== ADDING HOTEL ===');
            console.log('Hotel data being added:', hotelData);
            console.log('Total room price (all nights):', hotelData.price);
            console.log('Weekday nights:', hotelData.weekdayNights);
            console.log('Weekend nights:', hotelData.weekendNights);
            console.log('Room type:', hotelData.roomType);
            console.log('Total nights:', hotelData.totalNights);
            console.log('Number of rooms:', hotelData.numberOfRooms);
            console.log('Meal plan:', hotelData.mealPlan);
            console.log('Meal prices:', hotelData.mealPrices);
            console.log('Price breakdown:', hotelData.priceBreakdown);
            
            selectedHotels.push(hotelData);
            // Track last selected hotel id for defaulting pickup locations
            lastSelectedHotelId = hotelData.id;
            displaySelectedHotels();
            
            // Update hotel_data JSON field
            if (typeof window.updateHotelDataField === 'function') {
                window.updateHotelDataField();
            } else {
                console.error('updateHotelDataField is not defined. Please ensure the function is loaded.');
            }
            
            // Show success notification
            showNotification(`Hotel "${hotelData.name}" added successfully for ${hotelData.totalNights} nights!`, 'success');
            
            // Reset all hotel form fields to empty/initial state
            try {
                const __isMultiCity = ($('input[name="city_mode"]:checked').val() === 'multi');

                // In multi-city mode, do NOT clear hotel city; it must stay locked to active segment city.
                // Clearing it disables hotel select and breaks the "add more hotels" flow.
                if (!__isMultiCity) {
                    // Reset hotel city select - this will trigger change handler to disable hotel select
                    $('#hotelCitySelect').val(null).trigger('change');
                }
                
                // Reset hotel select
                const hotelSelectEl = document.getElementById('hotelSelect');
                if (hotelSelectEl) {
                    if (__isMultiCity) {
                        // Keep existing city + loaded hotel list; just clear selection.
                        $('#hotelSelect').val(null).trigger('change');
                        hotelSelectEl.disabled = false;
                        $('#hotelSelect').prop('disabled', false);
                    } else {
                        // Destroy Select2 first, then reset DOM
                        if ($('#hotelSelect').hasClass('select2-hidden-accessible')) {
                            $('#hotelSelect').select2('destroy');
                        }
                        hotelSelectEl.innerHTML = '<option value="">Select a city first to load hotels</option>';
                        hotelSelectEl.value = '';
