                `;
                }
            }
            
            container.innerHTML = servicesHTML;
            
            // After HTML is rendered, populate entry and exit port fields for each day
            let day = 1;
            for (let dayIndex = 0; dayIndex < daysToShow.length; dayIndex++) {
                day = daysToShow[dayIndex];
                
                // Populate entry pickup and dropoff fields based on zone_on
                populateEntryPortFields(day);
                
                // Populate exit pickup and dropoff fields based on zone_on
            
            }
            populateExitPortFields(day);
            
            // Initialize guest summaries for all services
            initializeServiceGuestSummaries();
            
            // Load attractions for all attraction dropdowns
            loadAttractionsForAllDays();
            
            // Load guides for all guide dropdowns
            loadGuidesForAllDays();
            
            // Populate all city dropdowns after generating day content
            setTimeout(() => {
                const userCountrySelect = document.getElementById('user_country');
                if (userCountrySelect && userCountrySelect.value) {
                    console.log('Populating all city dropdowns after generating day content');
                    
                    // Find all city dropdowns and populate them INCLUDING port city selects
                    const allCityDropdowns = [
                        document.getElementById('hotelCitySelect'),
                        document.getElementById('modal_local_transfer_city'),  // Entry port city
                        document.getElementById('modal_exit_city'),            // Exit port city
                        ...document.querySelectorAll('.attraction-city-select'),
                        ...document.querySelectorAll('.guide-city-select'),
                        ...document.querySelectorAll('.restaurant-city-select'),
                        ...document.querySelectorAll('.transport-city-select')
                    ].filter(dropdown => dropdown !== null);
                    
                    console.log('Found city dropdowns to populate:', allCityDropdowns.length);
                    
                    // Populate each dropdown
                    allCityDropdowns.forEach(dropdown => {
                        if (dropdown.options.length <= 1) {
                            populateCityDropdown(dropdown);
                        }
                    });
                }
            }, 500);
            
            // Setup event listeners for static point-to-point fields
            setTimeout(() => {
                for (let day = 1; day <= 7; day++) {
                    // City select
                    const citySelect = document.getElementById(`day${day}_transport_city_0`);
                    if (citySelect) {
                        const validatePointToPoint = () => {
                            setTimeout(() => enableSearchButton(day, 'transport_additional', 0), 50);
                        };
                        citySelect.addEventListener('change', validatePointToPoint);
                        // Handle Select2 events - check after a delay to allow Select2 to initialize
                        setTimeout(() => {
                            if (typeof jQuery !== 'undefined' && jQuery(citySelect).data('select2')) {
                                jQuery(citySelect).off('select2:select.pointToPoint').on('select2:select.pointToPoint', validatePointToPoint);
                                jQuery(citySelect).off('select2:unselect.pointToPoint').on('select2:unselect.pointToPoint', validatePointToPoint);
                            }
                        }, 500);
                    }
                    
                    // Pickup location input
                    const pickupLocationInput = document.getElementById(`day${day}_transport_pickup_location`);
                    if (pickupLocationInput) {
                        const validatePointToPoint = () => {
                            const pickupLatField = document.getElementById(`day${day}_transport_pickup_lat`);
                            const pickupLngField = document.getElementById(`day${day}_transport_pickup_lng`);
                            if (!pickupLocationInput.value || pickupLocationInput.value.trim() === '') {
                                if (pickupLatField) pickupLatField.value = '';
                                if (pickupLngField) pickupLngField.value = '';
                            }
                            setTimeout(() => enableSearchButton(day, 'transport_additional', 0), 50);
                        };
                        pickupLocationInput.addEventListener('input', validatePointToPoint);
                        pickupLocationInput.addEventListener('change', validatePointToPoint);
                        pickupLocationInput.addEventListener('blur', validatePointToPoint);
                    }
                    
                    // Dropoff location input
                    const dropoffLocationInput = document.getElementById(`day${day}_transport_dropoff_location`);
                    if (dropoffLocationInput) {
                        const validatePointToPoint = () => {
                            const dropoffLatField = document.getElementById(`day${day}_transport_dropoff_lat`);
                            const dropoffLngField = document.getElementById(`day${day}_transport_dropoff_lng`);
                            if (!dropoffLocationInput.value || dropoffLocationInput.value.trim() === '') {
                                if (dropoffLatField) dropoffLatField.value = '';
                                if (dropoffLngField) dropoffLngField.value = '';
                            }
                            setTimeout(() => enableSearchButton(day, 'transport_additional', 0), 50);
                        };
                        dropoffLocationInput.addEventListener('input', validatePointToPoint);
                        dropoffLocationInput.addEventListener('change', validatePointToPoint);
                        dropoffLocationInput.addEventListener('blur', validatePointToPoint);
                    }
                    
                    // Hidden lat/lng fields (polling for programmatic changes)
                    const latLngFields = [
                        document.getElementById(`day${day}_transport_pickup_lat`),
                        document.getElementById(`day${day}_transport_pickup_lng`),
                        document.getElementById(`day${day}_transport_dropoff_lat`),
                        document.getElementById(`day${day}_transport_dropoff_lng`)
                    ];
                    latLngFields.forEach(field => {
                        if (field) {
                            const validatePointToPoint = () => {
                                setTimeout(() => enableSearchButton(day, 'transport_additional', 0), 50);
                            };
                            field.addEventListener('change', validatePointToPoint);
                            
                            // Polling for programmatic changes
                            let lastValue = field.value || '';
                            const checkValue = setInterval(() => {
                                const currentValue = field.value || '';
                                if (currentValue !== lastValue) {
                                    lastValue = currentValue;
                                    validatePointToPoint();
                                }
                            }, 150);
                            
                            // Store interval ID for cleanup if needed
                            field.setAttribute('data-validation-interval-id', checkValue);
                        }
                    });
                    
                    // Pickup time select (uses name attribute, not id)
                    const additionalPickupTimeInput = document.getElementById(`day${day}_transport_additional_pickup_time_input`);
                    const additionalPickupTimeAmpm = document.getElementById(`day${day}_transport_additional_pickup_time_ampm`);
                    const validatePointToPoint = () => {
                        setTimeout(() => enableSearchButton(day, 'transport_additional', 0), 50);
                    };
                    if (additionalPickupTimeInput) {
                        additionalPickupTimeInput.addEventListener('input', () => { formatTimeInput(additionalPickupTimeInput); syncTransportAdditionalPickupTime(day); validatePointToPoint(); });
                        additionalPickupTimeInput.addEventListener('change', () => { syncTransportAdditionalPickupTime(day); validatePointToPoint(); });
                    }
                    if (additionalPickupTimeAmpm) {
                        additionalPickupTimeAmpm.addEventListener('change', () => { syncTransportAdditionalPickupTime(day); validatePointToPoint(); });
                    }
                }
            }, 1000);
            
            // Load restaurants for all restaurant dropdowns
            loadRestaurantsForAllDays();
        }
        
        // Load attractions for all days
        function loadAttractionsForAllDays() {
            const attractionSelects = document.querySelectorAll('.attraction-select');
            attractionSelects.forEach(select => {
                loadAttractionsDropdown(select);
            });
        }
        
        // Load attractions into dropdown
        function loadAttractionsDropdown(selectElement) {
            selectElement.innerHTML = '<option value="">Loading attractions...</option>';
            
            fetch('{{ route('fetch-attractions-by-dmc') }}')
                .then(response => response.json())
                .then(data => {
                    selectElement.innerHTML = '<option value="">Search Attraction</option>';
                    
                    if (data.success && data.attractions) {
                        console.log('Loading attractions data:', data.attractions);
                        data.attractions.forEach(attraction => {
                            console.log('Processing attraction:', attraction.name, 'Time slots:', attraction.time_slots);
                            const option = document.createElement('option');
                            option.value = attraction.attraction_id;
                            option.textContent = attraction.name + (attraction.location ? ' - ' + attraction.location : '');
                            
                            // Get open_time and close_time from attraction data
                            let openTime = null;
                            let closeTime = null;
                            
                            // Check if open_time and close_time are provided in the JSON
                            if (attraction.open_time) {
                                try {
                                    // If it's a JSON string, parse it
                                    if (typeof attraction.open_time === 'string' && attraction.open_time.includes('{')) {
                                        const openTimeData = JSON.parse(attraction.open_time);
                                        openTime = openTimeData.time || null;
                                    } else {
                                        openTime = attraction.open_time;
                                    }
                                } catch (e) {
                                    console.error('Error parsing open_time:', e);
                                    openTime = attraction.open_time; // Use as-is if parsing fails
                                }
                            }
                            
                            if (attraction.close_time) {
                                try {
                                    // If it's a JSON string, parse it
                                    if (typeof attraction.close_time === 'string' && attraction.close_time.includes('{')) {
                                        const closeTimeData = JSON.parse(attraction.close_time);
                                        closeTime = closeTimeData.time || null;
                                    } else {
                                        closeTime = attraction.close_time;
                                    }
                                } catch (e) {
                                    console.error('Error parsing close_time:', e);
                                    closeTime = attraction.close_time; // Use as-is if parsing fails
                                }
                            }
                            
                            // Set all data attributes
                            option.dataset.timeSlots = JSON.stringify(attraction.time_slots || []);
                            option.dataset.openTime = openTime || '';
                            option.dataset.closeTime = closeTime || '';
                            
                            // Set pricing data attributes
                            option.dataset.adultPrice = attraction.adult_price || 0;
                            option.dataset.childPrice = attraction.child_price || 0;
                            option.dataset.seniorPrice = attraction.senior_price || 0;
                            
                            selectElement.appendChild(option);
                            console.log('Added attraction:', attraction.name, 'Open:', openTime, 'Close:', closeTime);
                        });
                    } else {
                        const option = document.createElement('option');
                        option.value = '';
                        option.textContent = data.message || 'No attractions available';
                        option.disabled = true;
                        selectElement.appendChild(option);
                    }
                })
                .catch(error => {
                    console.error('Error loading attractions:', error);
                    selectElement.innerHTML = '<option value="">Error loading attractions</option>';
                });
        }
        
        // Load attraction details (time slots and tickets)
        window.loadAttractionDetails = function(day, attractionId, index = 1) {
            console.log('Loading attraction details for day:', day, 'attraction:', attractionId, 'index:', index);
            
            if (!attractionId) {
                // Clear time slots and tickets if no attraction selected
                document.getElementById('day' + day + '_attraction_' + index + '_time').innerHTML = '<option value="">Select Time Slot</option>';
                document.getElementById('day' + day + '_attraction_' + index + '_ticket').innerHTML = '<option value="">Select Ticket</option>';
                // Hide price display
                const priceDisplay = document.getElementById(`day${day}_attraction_${index}_price_display`);
                if (priceDisplay) {
                    priceDisplay.style.display = 'none';
                }
                return;
            }
            
            // Get attraction select element and selected option
            const attractionSelect = document.getElementById('day' + day + '_attraction_' + index);
            const selectedOption = attractionSelect.options[attractionSelect.selectedIndex];
            
            // Get open_time and close_time from the selected attraction option
            const openTime = selectedOption.dataset.openTime;
            const closeTime = selectedOption.dataset.closeTime;
            
            console.log('Attraction operating hours:', openTime, 'to', closeTime);
            console.log('Selected option data attributes:', {
                openTime: selectedOption.dataset.openTime,
                closeTime: selectedOption.dataset.closeTime,
                timeSlots: selectedOption.dataset.timeSlots
            });
            
            // Get time slot select element
            const timeSlotSelect = document.getElementById('day' + day + '_attraction_' + index + '_time');
            timeSlotSelect.innerHTML = '<option value="">Select Time Slot</option>';
            
            // First, try to use pre-defined time slots if available
            const timeSlotsData = selectedOption.dataset.timeSlots || '[]';
            
            let timeSlots = [];
            try {
                timeSlots = JSON.parse(timeSlotsData);
            } catch (e) {
                console.error('Error parsing time slots:', e);
                timeSlots = [];
            }
            
            if (timeSlots && timeSlots.length > 0) {
                // Use the time slots array to populate all available time slots
                timeSlots.forEach(slot => {
                    const option = document.createElement('option');
                    // If slot has open and close times, format them properly
                    if (slot.open && slot.close) {
                        const slotOpenTime = parseTime(slot.open);
                        const slotCloseTime = parseTime(slot.close);
                        if (slotOpenTime && slotCloseTime) {
                            const openDisplay = formatTime12(slotOpenTime);
                            const closeDisplay = formatTime12(slotCloseTime);
                            option.value = formatTime24(slotOpenTime) + ' - ' + formatTime24(slotCloseTime);
                            option.textContent = openDisplay + ' - ' + closeDisplay;
                        } else {
                            option.value = slot.slot;
                            option.textContent = slot.slot;
                        }
                    } else {
                        option.value = slot.slot;
                        option.textContent = slot.slot;
                    }
                    timeSlotSelect.appendChild(option);
                });
            } else if (openTime && closeTime) {
                // Fallback to generating time slots from operating hours if no time slots array is available
                generateTimeSlots(openTime, closeTime, timeSlotSelect);
            } else {
                timeSlotSelect.innerHTML += '<option value="" disabled>No time slots available</option>';
                console.log('No time slots found for attraction');
            }
            
            // Load tickets for the selected attraction
            loadTicketsForAttraction(day, attractionId, index);
            
            // Update attraction pricing display
            updateAttractionPricing(day, index);
        };
        
        // Generate time slots between open and close time at 30-minute intervals
        function generateTimeSlots(openTime, closeTime, selectElement) {
            console.log('Generating time slots for:', openTime, 'to', closeTime);
            
            if (!openTime || !closeTime) {
                console.log('Missing open or close time');
                selectElement.innerHTML += '<option value="" disabled>No time slots available</option>';
                return;
            }
            
            // Parse times (handling different formats)
            const startTime = parseTime(openTime);
            const endTime = parseTime(closeTime);
            
            console.log('Parsed times:', startTime, endTime);
            
            if (!startTime || !endTime) {
                console.log('Failed to parse times');
                selectElement.innerHTML += '<option value="" disabled>Invalid time range</option>';
                return;
            }
            
            // Show operating hours as a single time slot (open time - close time)
            const openTimeDisplay = formatTime12(startTime);
            const closeTimeDisplay = formatTime12(endTime);
            const timeSlotValue = formatTime24(startTime) + ' - ' + formatTime24(endTime);
            const timeSlotDisplay = openTimeDisplay + ' - ' + closeTimeDisplay;
            
            const option = document.createElement('option');
            option.value = timeSlotValue;
            option.textContent = timeSlotDisplay;
            selectElement.appendChild(option);
            
            console.log(`Generated operating hours slot: ${timeSlotDisplay} (${timeSlotValue})`);
        }
        
        // Update attraction pricing display
        window.updateAttractionPricing = function(day, index = 1) {
            console.log(`=== UPDATING ATTRACTION PRICING: Day ${day}, Index ${index} ===`);
            
            const attractionSelect = document.getElementById(`day${day}_attraction_${index}`);
            const ticketSelect = document.getElementById(`day${day}_attraction_${index}_ticket`);
            const priceDisplay = document.getElementById(`day${day}_attraction_${index}_price_display`);
            
            console.log('Elements found:', {
                attractionSelect: !!attractionSelect,
                ticketSelect: !!ticketSelect,
                priceDisplay: !!priceDisplay
            });
            
            if (!attractionSelect || !priceDisplay) {
                console.log('Required elements not found for attraction pricing update');
                return;
            }
            
            const selectedAttraction = attractionSelect.options[attractionSelect.selectedIndex];
            const selectedTicket = ticketSelect && ticketSelect.selectedIndex >= 0 ? ticketSelect.options[ticketSelect.selectedIndex] : null;
            
            console.log('Selected values:', {
                attractionValue: selectedAttraction?.value,
                attractionText: selectedAttraction?.text,
                ticketValue: selectedTicket?.value,
                ticketText: selectedTicket?.text,
                ticketSelectedIndex: ticketSelect?.selectedIndex,
                ticketSelectLength: ticketSelect?.options?.length
            });
            
            if (!selectedAttraction || !selectedAttraction.value) {
                console.log('No attraction selected, hiding price display');
                priceDisplay.style.display = 'block';
                const ticketPricingContent = document.getElementById(`day${day}_attraction_${index}_ticket_pricing_content`);
                if (ticketPricingContent) {
                    ticketPricingContent.innerHTML = '<div class="text-muted small">Please select an attraction</div>';
                }
                const pricingColumns = document.getElementById(`day${day}_attraction_${index}_pricing_columns`);
                const totalPriceRow = document.getElementById(`day${day}_attraction_${index}_total_price_row`);
                if (pricingColumns) pricingColumns.style.display = 'none';
                if (totalPriceRow) totalPriceRow.style.display = 'none';
                return;
            }
            
            // Check if ticket is selected (required for pricing)
            // Check both value and text to handle cases where value might be empty but text exists
            const hasTicketValue = selectedTicket && selectedTicket.value && selectedTicket.value.trim() !== '';
            const hasTicketText = selectedTicket && selectedTicket.text && selectedTicket.text.trim() !== '' && selectedTicket.text.trim() !== 'Select Ticket';
            
            if (!selectedTicket || (!hasTicketValue && !hasTicketText)) {
                console.log('No ticket selected, showing info message');
                priceDisplay.style.display = 'block';
                
                // Update ticket pricing column with message
                const ticketPricingContent = document.getElementById(`day${day}_attraction_${index}_ticket_pricing_content`);
                if (ticketPricingContent) {
                    ticketPricingContent.innerHTML = `
                        <div class="text-muted small">
                            <strong>Attraction Selected: ${selectedAttraction.text}</strong><br>
                            Please select a ticket to see pricing information
                        </div>
                    `;
                }
                
                // Hide pricing columns and total row
                const pricingColumns = document.getElementById(`day${day}_attraction_${index}_pricing_columns`);
                const totalPriceRow = document.getElementById(`day${day}_attraction_${index}_total_price_row`);
                if (pricingColumns) pricingColumns.style.display = 'none';
                if (totalPriceRow) totalPriceRow.style.display = 'none';
                
                return;
            }
            
            // Get pricing data from the selected ticket option
            // Try multiple ways to get the pricing data
            let adultPrice = parseFloat(selectedTicket.dataset.adultPrice || selectedTicket.dataset.adult_price || selectedTicket.getAttribute('data-adult-price') || '0') || 0;
            let childPrice = parseFloat(selectedTicket.dataset.childPrice || selectedTicket.dataset.child_price || selectedTicket.getAttribute('data-child-price') || '0') || 0;
            let seniorPrice = parseFloat(selectedTicket.dataset.seniorPrice || selectedTicket.dataset.senior_price || selectedTicket.getAttribute('data-senior-price') || '0') || 0;
            
            // If no pricing data in dataset, try to extract from ticket text content
            if (adultPrice === 0 && childPrice === 0 && seniorPrice === 0) {
                console.log('No pricing data in dataset, extracting from ticket text...');
                const ticketText = selectedTicket.textContent;
                
                // Extract adult price
                const adultMatch = ticketText.match(/Adult:\s*\$(\d+(?:\.\d+)?)/);
                if (adultMatch) {
                    adultPrice = parseFloat(adultMatch[1]);
                    console.log('Extracted adult price from text:', adultPrice);
                }
                
                // Extract child price
                const childMatch = ticketText.match(/Child:\s*\$(\d+(?:\.\d+)?)/);
                if (childMatch) {
                    childPrice = parseFloat(childMatch[1]);
                    console.log('Extracted child price from text:', childPrice);
                }
                
                // Extract senior price
                const seniorMatch = ticketText.match(/Senior:\s*\$(\d+(?:\.\d+)?)/);
                if (seniorMatch) {
                    seniorPrice = parseFloat(seniorMatch[1]);
                    console.log('Extracted senior price from text:', seniorPrice);
                }
            }
            
            // Debug logging for ticket pricing
            console.log('=== TICKET PRICING DEBUG ===');
            console.log('Selected ticket option:', selectedTicket);
            console.log('Ticket dataset:', selectedTicket.dataset);
            console.log('Raw adult_price:', selectedTicket.dataset.adultPrice);
            console.log('Raw child_price:', selectedTicket.dataset.childPrice);
            console.log('Raw senior_price:', selectedTicket.dataset.seniorPrice);
            console.log('Final parsed prices:', { adultPrice, childPrice, seniorPrice });
            
            // Get current guest counts from the guest summary
            const guestSummaryElement = document.getElementById(`day${day}_attraction_${index}_guest_summary`);
            if (!guestSummaryElement) {
                priceDisplay.style.display = 'block';
                const ticketPricingContent = document.getElementById(`day${day}_attraction_${index}_ticket_pricing_content`);
                if (ticketPricingContent) {
                    ticketPricingContent.innerHTML = '<div class="text-muted small">Please configure guests to see pricing</div>';
                }
                const pricingColumns = document.getElementById(`day${day}_attraction_${index}_pricing_columns`);
                const totalPriceRow = document.getElementById(`day${day}_attraction_${index}_total_price_row`);
                if (pricingColumns) pricingColumns.style.display = 'none';
                if (totalPriceRow) totalPriceRow.style.display = 'none';
                return;
            }
            
            const guestInfo = parseGuestSummary(guestSummaryElement.innerHTML || guestSummaryElement.textContent || '');
            
            if (guestInfo.adults === 0 && guestInfo.children === 0 && guestInfo.seniors === 0) {
                priceDisplay.style.display = 'block';
                const ticketPricingContent = document.getElementById(`day${day}_attraction_${index}_ticket_pricing_content`);
                if (ticketPricingContent) {
                    ticketPricingContent.innerHTML = '<div class="text-muted small">Please configure guests to see pricing</div>';
                }
                const pricingColumns = document.getElementById(`day${day}_attraction_${index}_pricing_columns`);
                const totalPriceRow = document.getElementById(`day${day}_attraction_${index}_total_price_row`);
                if (pricingColumns) pricingColumns.style.display = 'none';
                if (totalPriceRow) totalPriceRow.style.display = 'none';
                return;
            }
            
            // Calculate total price
            const totalPrice = (guestInfo.adults * adultPrice) + 
                            (guestInfo.children * childPrice) + 
                            (guestInfo.seniors * seniorPrice);
            
            // Always show the price display when we have data
            priceDisplay.style.display = 'block';
            
            // Update ticket pricing column (show only calculation, not base ticket prices)
            const ticketPricingContent = document.getElementById(`day${day}_attraction_${index}_ticket_pricing_content`);
            if (ticketPricingContent) {
                if (totalPrice > 0) {
                    ticketPricingContent.innerHTML = `
                        <div class="small">
                            <div class="mb-2"><strong>${selectedTicket.text}</strong></div>
                            <div class="mb-1"><strong>Calculation:</strong></div>
                            <div class="mb-1">Adult: $${adultPrice.toFixed(2)} × ${guestInfo.adults} = $${(adultPrice * guestInfo.adults).toFixed(2)}</div>
                            <div class="mb-1">Child: $${childPrice.toFixed(2)} × ${guestInfo.children} = $${(childPrice * guestInfo.children).toFixed(2)}</div>
                            <div class="mb-2">Senior: $${seniorPrice.toFixed(2)} × ${guestInfo.seniors} = $${(seniorPrice * guestInfo.seniors).toFixed(2)}</div>
                            <hr class="my-2">
                            <div class="fw-bold text-info">Total: $${totalPrice.toFixed(2)}</div>
                        </div>
                    `;
                } else {
                    ticketPricingContent.innerHTML = '<div class="text-muted small">No pricing available</div>';
                }
            }
            
            // Show pricing columns
            const pricingColumns = document.getElementById(`day${day}_attraction_${index}_pricing_columns`);
            if (pricingColumns) {
                pricingColumns.style.display = 'flex';
            }
            
            // Update guide and transport pricing columns
            updateAttractionGuidePricing(day, index);
            updateAttractionTransportPricing(day, index);
            
            // Update total price
            updateAttractionTotalPrice(day, index);
            
            console.log(`Ticket pricing updated for day ${day}, index ${index}: Total: $${totalPrice}`);
        }
        
        // Function to update total price (attraction + guide + transport)
        window.updateAttractionTotalPrice = function(day, index) {
            // Get ticket pricing
            let ticketPrice = 0;
            const ticketPricingContent = document.getElementById(`day${day}_attraction_${index}_ticket_pricing_content`);
            if (ticketPricingContent) {
                const ticketTotalMatch = ticketPricingContent.textContent.match(/Total:\s*\$([\d.]+)/);
                if (ticketTotalMatch) {
                    ticketPrice = parseFloat(ticketTotalMatch[1]) || 0;
                }
            }
            
            // Get guide pricing
            let guidePrice = 0;
            const guideTotalPriceField = document.getElementById(`day${day}_attraction_${index}_guide_total_price`);
            if (guideTotalPriceField) {
                guidePrice = parseFloat(guideTotalPriceField.value) || 0;
            }
            
            // Get transport pricing
            let transportPrice = 0;
            const transportCostField = document.getElementById(`day${day}_attraction_${index}_transfer_cost`);
            const transferType = document.getElementById(`day${day}_attraction_${index}_transfer_type`);
            if (transportCostField && transportCostField.value) {
                let baseTransportPrice = parseFloat(transportCostField.value) || 0;
                // For Shared transfers, multiply by attraction guest count
                if (transferType && transferType.value === 'Shared' && baseTransportPrice > 0) {
                    const guestSummaryElement = document.getElementById(`day${day}_attraction_${index}_guest_summary`);
                    if (guestSummaryElement && typeof parseGuestSummary === 'function') {
                        const guestInfo = parseGuestSummary(guestSummaryElement.innerHTML || guestSummaryElement.textContent || '');
                        const guestCount = (guestInfo.adults || 0) + (guestInfo.children || 0) + (guestInfo.infants || 0);
                        if (guestCount > 0) {
                            transportPrice = baseTransportPrice * guestCount;
                        } else {
                            transportPrice = baseTransportPrice; // Default to base if no guests found
                        }
                    } else {
                        transportPrice = baseTransportPrice;
                    }
                } else {
                    transportPrice = baseTransportPrice;
                }
            }
            
            // Calculate total
            const totalPrice = ticketPrice + guidePrice + transportPrice;
            
            // Update total price display
            const totalPriceDisplay = document.getElementById(`day${day}_attraction_${index}_total_price_display`);
            const totalPriceRow = document.getElementById(`day${day}_attraction_${index}_total_price_row`);
            
            if (totalPriceDisplay) {
                totalPriceDisplay.textContent = `$${totalPrice.toFixed(2)}`;
            }
            
            if (totalPriceRow && totalPrice > 0) {
                totalPriceRow.style.display = 'block';
            } else if (totalPriceRow) {
                totalPriceRow.style.display = 'none';
            }
            
            console.log(`Total price updated for day ${day}, index ${index}: Ticket: $${ticketPrice}, Guide: $${guidePrice}, Transport: $${transportPrice}, Total: $${totalPrice}`);

            // After updating this attraction row, refresh header + section totals
            if (typeof updateAttractionSectionSummary === 'function') {
                updateAttractionSectionSummary(day);
            }
        }

        // Overall attraction section summary (names + total incl. guide + vehicle)
        window.updateAttractionSectionSummary = function(day = 1) {
            try {
                const headerSpan = document.getElementById(`day${day}_attractionHeaderSummary`);
                const attractionTotalPriceEl = document.getElementById(`day${day}_attractionTotalPrice`);
                const container = document.getElementById(`day${day}_attractions_container`);
                if (!container) {
                    if (headerSpan) headerSpan.textContent = '';
                    if (attractionTotalPriceEl) attractionTotalPriceEl.textContent = 'SGD 0.00';
                    return;
                }

                const items = container.querySelectorAll('.attraction-item');
                if (!items.length) {
                    if (headerSpan) headerSpan.textContent = '';
                    if (attractionTotalPriceEl) attractionTotalPriceEl.textContent = 'SGD 0.00';
                    return;
                }

                const names = [];
                let grandTotal = 0;

                items.forEach(item => {
                    const idx = item.getAttribute('data-attraction-index');
                    if (!idx) return;

                    const attractionSelect = document.getElementById(`day${day}_attraction_${idx}`);
                    const totalDisplay = document.getElementById(`day${day}_attraction_${idx}_total_price_display`);

                    // Collect name
                    if (attractionSelect && attractionSelect.value) {
                        const txt = attractionSelect.options[attractionSelect.selectedIndex].text;
                        if (txt) names.push(txt);
                        // Only sum totals when an attraction is selected (avoid stale display after segment switch).
                        if (totalDisplay && totalDisplay.textContent) {
                            const match = totalDisplay.textContent.match(/([\d,.]+)/);
                            if (match) {
                                grandTotal += parseFloat(match[1].replace(/,/g, '')) || 0;
                            }
                        }
                    }
                });

                if (!headerSpan) return;

                if (!names.length) {
                    headerSpan.textContent = '';
                    if (attractionTotalPriceEl) attractionTotalPriceEl.textContent = 'SGD 0.00';
                    return;
                }

                // Build compact names string
                const uniqueNames = [...new Set(names)];
                let nameSummary = '';
                if (uniqueNames.length === 1) {
                    nameSummary = uniqueNames[0];
                } else if (uniqueNames.length === 2) {
                    nameSummary = `${uniqueNames[0]} & ${uniqueNames[1]}`;
                } else if (uniqueNames.length === 3) {
                    nameSummary = `${uniqueNames[0]}, ${uniqueNames[1]} & ${uniqueNames[2]}`;
                } else {
                    const remaining = uniqueNames.length - 2;
                    nameSummary = `${uniqueNames[0]}, ${uniqueNames[1]} + ${remaining} more`;
                }

                const formattedTotal = grandTotal.toLocaleString('en-US', {
                    minimumFractionDigits: 2,
                    maximumFractionDigits: 2
                });

                // Only show names in header, price is shown on right side
                headerSpan.textContent = `– ${nameSummary}`;
                
                // Update right side price display
                if (attractionTotalPriceEl) {
                    attractionTotalPriceEl.textContent = `SGD ${formattedTotal}`;
                }
            } catch (e) {
                console.error('Error updating attraction section summary:', e);
            }
        }
        
        // Function to update transport pricing column
        window.updateAttractionTransportPricing = function(day, index) {
            const transportCostField = document.getElementById(`day${day}_attraction_${index}_transfer_cost`);
            const transportPricingContent = document.getElementById(`day${day}_attraction_${index}_transport_pricing_content`);
            const transferRequired = document.getElementById(`day${day}_attraction_${index}_transfer_required`);
            const transferType = document.getElementById(`day${day}_attraction_${index}_transfer_type`);
            const transferWay = document.getElementById(`day${day}_attraction_${index}_transfer_way`);
            const transferVehicle = document.getElementById(`day${day}_attraction_${index}_transfer_vehicle`);
            const pickupLocationSelect = document.getElementById(`day${day}_attraction_${index}_transfer_pickup_location`);
            
            if (!transportPricingContent) return;
            
            // Check if transfer is required
            if (!transferRequired || transferRequired.value !== 'Yes') {
                transportPricingContent.innerHTML = '<div class="text-muted small">No transport selected</div>';
                updateAttractionTotalPrice(day, index);
                return;
            }
            
            let cost = transportCostField ? (parseFloat(transportCostField.value) || 0) : 0;
            const type = transferType ? transferType.value : '';
            const way = transferWay ? transferWay.value : '';
            const vehicleSelect = transferVehicle;
            let vehicleName = 'N/A';
            
            if (vehicleSelect && vehicleSelect.value) {
                const selectedOption = vehicleSelect.options[vehicleSelect.selectedIndex];
                if (selectedOption) {
                    vehicleName = selectedOption.textContent || 'N/A';
                }
            }
            
            // Get attraction guest count for Shared transfer multiplication
            let guestCount = 1;
            let baseCost = cost;
            if (type === 'Shared' && cost > 0) {
                const guestSummaryElement = document.getElementById(`day${day}_attraction_${index}_guest_summary`);
                if (guestSummaryElement && typeof parseGuestSummary === 'function') {
                    const guestInfo = parseGuestSummary(guestSummaryElement.innerHTML || guestSummaryElement.textContent || '');
                    guestCount = (guestInfo.adults || 0) + (guestInfo.children || 0) + (guestInfo.infants || 0);
                    if (guestCount === 0) guestCount = 1; // Default to 1 if no guests found
                    // Multiply base cost by guest count for Shared transfers
                    cost = baseCost * guestCount;
                }
            }
            
            // Check if this price came from AJAX (zone-based pricing)
            const isAjaxPrice = transportCostField && transportCostField.getAttribute('data-ajax-base-price');
            const priceSource = isAjaxPrice ? ' (Zone-based)' : '';
            
            if (cost > 0) {
                let transportHtml = `
                    <div class="small">
                        <div class="mb-1"><strong>Type:</strong> ${type || 'N/A'}</div>
                        <div class="mb-1"><strong>Way:</strong> ${way || 'N/A'}</div>
                        <div class="mb-1"><strong>Vehicle:</strong> ${vehicleName}</div>
                        ${isAjaxPrice ? '<div class="mb-1 text-info"><small><i class="ri-checkbox-circle-line me-1"></i>Zone-based pricing</small></div>' : ''}
                        ${type === 'Shared' && guestCount > 1 ? `<div class="mb-1"><small>Base Cost: $${baseCost.toFixed(2)} × ${guestCount} guests</small></div>` : ''}
                        <hr class="my-2">
                        <div class="fw-bold text-success">Total: $${cost.toFixed(2)}${priceSource}</div>
                    </div>
                `;
                transportPricingContent.innerHTML = transportHtml;
                
                // Show pricing columns if not already shown
                const pricingColumns = document.getElementById(`day${day}_attraction_${index}_pricing_columns`);
                if (pricingColumns) {
                    pricingColumns.style.display = 'flex';
                }
            } else {
                // If pickup location is selected but cost is 0, try to fetch pricing
                if (pickupLocationSelect && pickupLocationSelect.value &&
                    vehicleSelect && vehicleSelect.value &&
                    transferType && transferType.value &&
                    transferWay && transferWay.value) {
                    
                    // Check if pricing fetch has already failed to prevent infinite loop
                    const pricingFetchFailed = transportCostField && transportCostField.getAttribute('data-pricing-fetch-failed') === 'true';
                    const errorMessage = transportCostField ? transportCostField.getAttribute('data-pricing-error-message') : null;
                    
                    if (pricingFetchFailed) {
                        // Pricing fetch already failed, show error message instead of retrying
                        transportPricingContent.innerHTML = `<div class="text-danger small"><i class="ri-error-warning-line me-1"></i>${errorMessage || 'No pricing found'}</div>`;
                    } else {
                        transportPricingContent.innerHTML = '<div class="text-muted small">Fetching pricing...</div>';
                        // Trigger AJAX call to get pricing
                        fetchAttractionTransferPricing(day, index);
                    }
                } else {
                    transportPricingContent.innerHTML = '<div class="text-muted small">Transport selected but cost not set</div>';
                }
            }
            
            // Update total price
            updateAttractionTotalPrice(day, index);
        }
        
        // Load tickets for specific attraction
        function loadTicketsForAttraction(day, attractionId, index = 1) {
            const ticketSelect = document.getElementById('day' + day + '_attraction_' + index + '_ticket');
            ticketSelect.innerHTML = '<option value="">Loading tickets...</option>';
            
            // Get current DMC ID
            const currentDmcId = '{{ $finalDmcId }}';
            
            fetch('{{ route('fetch-tickets-by-attraction') }}?attraction_id=' + attractionId + '&dmc_id=' + currentDmcId)
                .then(response => response.json())
                .then(data => {
                    ticketSelect.innerHTML = '<option value="">Select Ticket</option>';
                    
                    if (data.success && data.tickets) {
                        data.tickets.forEach(ticket => {
                            const option = document.createElement('option');
                            option.value = ticket.ticket_id;
                            // Store only the ticket name without price information
                            option.textContent = ticket.name;
                            
                            // Set pricing data attributes for the ticket
                            option.dataset.adultPrice = ticket.adult_price || 0;
                            option.dataset.childPrice = ticket.child_price || 0;
                            option.dataset.seniorPrice = ticket.senior_adult_price || 0;
                            option.dataset.description = ticket.description || '';
                            
                            ticketSelect.appendChild(option);
                        });
                        
                        if (data.tickets.length === 0) {
                            const option = document.createElement('option');
                            option.value = '';
                            option.textContent = 'No tickets available for this attraction';
                            option.disabled = true;
                            ticketSelect.appendChild(option);
                        }
                        
                        // Update pricing display after loading tickets
                        updateAttractionPricing(day, index);
                    } else {
                        const option = document.createElement('option');
                        option.value = '';
                        option.textContent = data.message || 'No tickets available';
                        option.disabled = true;
                        ticketSelect.appendChild(option);
                    }
                })
                .catch(error => {
                    console.error('Error loading tickets:', error);
                    ticketSelect.innerHTML = '<option value="">Error loading tickets</option>';
                });
        }
        
        function initializeServiceGuestSummaries() {
            // Get current guest values from main form
            const male = parseInt(document.getElementById('male')?.value) || 0;
            const female = parseInt(document.getElementById('female')?.value) || 0;
            const children = parseInt(document.getElementById('children')?.value) || 0;
            const infants = parseInt(document.getElementById('infants')?.value) || 0;
            const adults = male + female;
            
            // Use same badge design as main Guests section (406-436)
            const summaryHTML = `<span class="d-flex align-items-center gap-1"><span class="badge d-flex align-items-center gap-1" style="background: #667eea; border-radius: 4px; font-size: 0.7rem; padding: 0.2rem 0.4rem;" title="Adults"><i class="ri-group-line" style="font-size: 0.75rem;"></i><span>${adults} Adults</span></span><span class="badge d-flex align-items-center gap-1" style="background: #667eea; border-radius: 4px; font-size: 0.7rem; padding: 0.2rem 0.4rem; opacity: 0.8;" title="Male"><i class="ri-men-line" style="font-size: 0.75rem;"></i><span>${male}</span></span><span class="badge d-flex align-items-center gap-1" style="background: #667eea; border-radius: 4px; font-size: 0.7rem; padding: 0.2rem 0.4rem; opacity: 0.8;" title="Female"><i class="ri-women-line" style="font-size: 0.75rem;"></i><span>${female}</span></span></span><span class="d-flex align-items-center gap-1"><span class="badge d-flex align-items-center gap-1" style="background: #28a745; border-radius: 4px; font-size: 0.7rem; padding: 0.2rem 0.4rem;" title="Children"><i class="ri-user-smile-line" style="font-size: 0.75rem;"></i><span>${children}</span></span><span class="badge d-flex align-items-center gap-1" style="background: #ffc107; color: #000; border-radius: 4px; font-size: 0.7rem; padding: 0.2rem 0.4rem;" title="Infants"><i class="ri-user-heart-line" style="font-size: 0.75rem;"></i><span>${infants}</span></span></span>`;
            
            const summaryElements = document.querySelectorAll('[id$="_guest_summary"]');
            summaryElements.forEach(element => {
                if (element.id === 'mainGuestSummary' || element.id === 'guestSummary') return;
                element.innerHTML = summaryHTML;
            });
        }

