                // Populate the city dropdown for the new guide section
                if (newCitySelect) {
                    populateCityDropdown(newCitySelect);
                }

                // Multi-city: inherit the active segment city into newly added section
                const _segCityG = (typeof window.getActiveSegmentCityLabelForServices === 'function') ? window.getActiveSegmentCityLabelForServices() : '';
