    // Function to enable search button when pickup time changes
    function enableSearchButton(day, section, index=null) {
        const searchBtn = document.getElementById(`day${day}_${section}_search_btn`);
        if (!searchBtn) return;

        // In multi-city, frozen segment snapshots can contain duplicate inputs with the same
        // name/id patterns. Scope DOM lookups to the live services bundle when present.
        const bundleRoot = document.getElementById('segmentServicesBundle');
        const qs = function (sel) {
            return bundleRoot ? bundleRoot.querySelector(sel) : document.querySelector(sel);
        };
        
        // Check if Point-to-Point mode is enabled
        const dmcUser = @json($UserDmc);
        const isPointToPointElement = dmcUser.zone_on;
        const isPointToPoint = dmcUser.zone_on;
        
        console.log('enableSearchButton debug:', {
            section: section,
            isPointToPointElement: !!isPointToPointElement,
            isPointToPointValue: isPointToPointElement,
            isPointToPoint: isPointToPoint,
            searchBtnExists: !!searchBtn
        });
        
        // For entry/exit ports in Point-to-Point mode, only need city
        if (isPointToPoint==1 && (section === 'entry' || section === 'exit')) {
            console.log(`Taking Point-to-Point path for ${section} port`);
            const citySelectId = section === 'entry' ? 'modal_local_transfer_city' : 'modal_exit_city';
            const citySelect = document.getElementById(citySelectId);
            
            if (citySelect && citySelect.value) {
                searchBtn.disabled = false;
                searchBtn.classList.remove('btn-secondary');
                searchBtn.classList.add('btn-primary');
                console.log(`Search button enabled for Point-to-Point ${section} port`);
            } else {
                searchBtn.disabled = true;
                searchBtn.classList.remove('btn-primary');
                searchBtn.classList.add('btn-secondary');
                console.log(`Search button disabled for Point-to-Point ${section} port - missing city`);
            }
            return;
        }
        
        // For entry/exit ports in zone-based mode, check all required fields
        if (isPointToPoint!=1 && (section === 'entry' || section === 'exit')) {
            console.log(`Taking zone-based path for ${section} port`);
            // Get the appropriate city select based on section
            const citySelectId = section === 'entry' ? 'modal_local_transfer_city' : 'modal_exit_city';
            const citySelect = document.getElementById(citySelectId);
            
            // Get pickup and dropoff elements
            // When zone_on = 0 → entry uses Google Maps inputs; when zone_on = 1 → entry uses selects
            // Exit generally uses selects (zone-assigned lists)
            const userDmcConfig = UserDmc || null;
            const zoneOn = userDmcConfig && typeof userDmcConfig.zone_on !== 'undefined'
                ? parseInt(userDmcConfig.zone_on)
                : 1; // default to 1 (zones enabled)
                
            console.log(`Zone configuration for ${section} port:`, {
                userDmcConfig: userDmcConfig,
                zoneOn: zoneOn,
                section: section
            });

            let pickupSelect, dropoffSelect;
            if (section === 'entry') {
                if (zoneOn === 0) {
                    // Entry with Google Maps inputs
                    pickupSelect = document.querySelector(`input[name="day${day}_${section}_pickup_location"]`);
                    dropoffSelect = document.querySelector(`input[name="day${day}_${section}_dropoff_location"]`);
                } else {
                    // Entry with zone selects
                    pickupSelect = document.querySelector(`select[name="day${day}_${section}_pickup_zone_id"]`);
                    dropoffSelect = document.querySelector(`select[name="day${day}_${section}_dropoff_zone_id"]`);
                }
            } else {
                // Exit ports - also depend on zone_on setting
                if (zoneOn === 0) {
                    // Exit with Google Maps inputs
                    pickupSelect = document.querySelector(`input[name="day${day}_${section}_pickup_location"]`);
                    dropoffSelect = document.querySelector(`input[name="day${day}_${section}_dropoff_location"]`);
                } else {
                    // Exit with zone selects
                    pickupSelect = document.querySelector(`select[name="day${day}_${section}_pickup_zone_id"]`);
                    dropoffSelect = document.querySelector(`select[name="day${day}_${section}_dropoff_zone_id"]`);
                }
            }
            const pickupFeildName = pickupSelect ? pickupSelect.name : null;
            const dropoffFeildName = dropoffSelect ? dropoffSelect.name : null;
            
            // Get time and date fields
            const timeFieldName = section === 'exit' ? `day${day}_exit_time` : `day${day}_${section}_pickup_time`;
            const timeSelect = document.querySelector(`[name="${timeFieldName}"]`);

            // Date field handling
            // Try section-specific date first (when present), otherwise fallback to main travel_dates
            let dateInput;
            if (section === 'exit') {
                const exitDateFieldName = `day${day}_exit_date`;
                dateInput = document.querySelector(`input[name="${exitDateFieldName}"]`);
            } else {
                const entryDateFieldName = `day${day}_${section}_pickup_date`;
                dateInput = document.querySelector(`input[name="${entryDateFieldName}"]`);
            }
            if (!dateInput) {
                // Fallback to global travel dates control
                dateInput = document.getElementById('travel_dates');
            }
            
            console.log(`Checking ${section} port fields:`, {
                city: citySelect?.value || 'missing',
                pickup: pickupSelect?.value || 'missing',
                dropoff: dropoffSelect?.value || 'missing',
                time: timeSelect?.value || 'missing',
                date: dateInput?.value || 'missing',
                timeFieldName: timeFieldName,
                timeSelectElement: timeSelect,
                dateInputElement: dateInput,
                pickupFeildName: pickupFeildName,
                dropoffFeildName: dropoffFeildName,
                // Debug: Show actual field elements and their properties
                pickupElement: pickupSelect,
                dropoffElement: dropoffSelect,
                pickupElementValue: pickupSelect ? pickupSelect.value : 'NO_ELEMENT',
                dropoffElementValue: dropoffSelect ? dropoffSelect.value : 'NO_ELEMENT',
                pickupElementName: pickupSelect ? pickupSelect.name : 'NO_ELEMENT',
                dropoffElementName: dropoffSelect ? dropoffSelect.name : 'NO_ELEMENT'
            });
            
            // Check if all required fields are filled
            const allFieldsFilled = citySelect?.value && 
                                    pickupSelect?.value && 
                                    dropoffSelect?.value && 
                                    timeSelect?.value && 
                                    dateInput?.value;
            
            if (allFieldsFilled) {
                searchBtn.disabled = false;
                searchBtn.classList.remove('btn-secondary');
                searchBtn.classList.add('btn-primary');
                console.log(`Search button enabled for zone-based ${section} port - all fields filled`);
            } else {
                searchBtn.disabled = true;
                searchBtn.classList.remove('btn-primary');
                searchBtn.classList.add('btn-secondary');
                console.log(`Search button disabled for zone-based ${section} port - missing required fields`);
            }
            return;
        }
        
        // Normalize section name for transport type detection
        let baseSection = section;
        let transportIndex = index;
        
        if (section === 'transport_additional' || section === 'transport_hourly') {
            baseSection = 'transport';
            // For transport_additional, index should be 0 for initial transport
            if (transportIndex === null || transportIndex === undefined) {
                transportIndex = 0;
            }
        } else if (section.match(/^transport_\d+_(additional|hourly)$/)) {
            // Extract the index from section names like 'transport_2_additional' or 'transport_2_hourly'
            const match = section.match(/^transport_(\d+)_(additional|hourly)$/);
            if (match) {
                transportIndex = parseInt(match[1]);
                baseSection = `transport_${transportIndex}`;
            }
        }
        
        // Check transport type to determine enablement criteria
        // For initial transport (index 0), the service type radio name doesn't have an index
        let pointToPointRadio, hourlyRadio, localTransferRadio;
        if (transportIndex === 0 || transportIndex === null) {
            pointToPointRadio = qs(`input[name="day${day}_transport_service_type"][value="point_to_point"]`);
            hourlyRadio = qs(`input[name="day${day}_transport_service_type"][value="hourly"]`);
            localTransferRadio = qs(`input[name="day${day}_transport_service_type"][value="local_transfer"]`);
        } else {
            pointToPointRadio = qs(`input[name="day${day}_transport_${transportIndex}_service_type"][value="point_to_point"]`);
            hourlyRadio = qs(`input[name="day${day}_transport_${transportIndex}_service_type"][value="hourly"]`);
            localTransferRadio = qs(`input[name="day${day}_transport_${transportIndex}_service_type"][value="local_transfer"]`);
        }
        
        let transportType = null;
        if (pointToPointRadio && pointToPointRadio.checked) {
            transportType = 'point_to_point';
        } else if (hourlyRadio && hourlyRadio.checked) {
            transportType = 'hourly';
        } else if (localTransferRadio && localTransferRadio.checked) {
            transportType = 'local_transfer';
        }
        
        console.log('enableSearchButton called:', {
            day: day,
            section: section,
            baseSection: baseSection,
            transportIndex: transportIndex,
            transportType: transportType,
            buttonExists: !!searchBtn
        });
        
            // For point_to_point, need all fields: city, pickup location (with coordinates), dropoff location (with coordinates), and pickup time
        if (transportType === 'point_to_point') {
            console.log('Point to point transport type detected', transportIndex);
            
            // Use transportIndex instead of index (which might be null/undefined)
            const fieldIndex = (transportIndex === null || transportIndex === undefined) ? 0 : transportIndex;
            
            // Determine field IDs based on fieldIndex
            let cityId, pickupLocationId, dropoffLocationId, pickupLatId, pickupLngId, dropoffLatId, dropoffLngId, pickupTimeName;
            
            if (fieldIndex === 0) {
                // Initial transport (index 0)
                cityId = `day${day}_transport_city_0`;
                pickupLocationId = `day${day}_transport_pickup_location`;
                dropoffLocationId = `day${day}_transport_dropoff_location`;
                pickupLatId = `day${day}_transport_pickup_lat`;
                pickupLngId = `day${day}_transport_pickup_lng`;
                dropoffLatId = `day${day}_transport_dropoff_lat`;
                dropoffLngId = `day${day}_transport_dropoff_lng`;
                pickupTimeName = `day${day}_transport_additional_pickup_time`;
            } else {
                // Dynamic transport (index > 0)
                cityId = `day${day}_transport_city_${fieldIndex}`;
                pickupLocationId = `day${day}_transport_${fieldIndex}_pickup_location`;
                dropoffLocationId = `day${day}_transport_${fieldIndex}_dropoff_location`;
                pickupLatId = `day${day}_transport_${fieldIndex}_pickup_lat`;
                pickupLngId = `day${day}_transport_${fieldIndex}_pickup_lng`;
                dropoffLatId = `day${day}_transport_${fieldIndex}_dropoff_lat`;
                dropoffLngId = `day${day}_transport_${fieldIndex}_dropoff_lng`;
                pickupTimeName = `day${day}_transport_${fieldIndex}_additional_pickup_time`;
            }
            
            // Get all field elements
            const cityField = document.getElementById(cityId);
            const pickupLocationField = document.getElementById(pickupLocationId);
            const dropoffLocationField = document.getElementById(dropoffLocationId);
            const pickupLatField = document.getElementById(pickupLatId);
            const pickupLngField = document.getElementById(pickupLngId);
            const dropoffLatField = document.getElementById(dropoffLatId);
            const dropoffLngField = document.getElementById(dropoffLngId);
            // Find the transport container to search within it
            let transportContainer = null;
            if (fieldIndex === 0) {
                // For initial transport, find container with data-transport-index="1"
                transportContainer = document.querySelector(`[data-transport-index="1"]`);
            } else {
                // For dynamic transports, find container with data-transport-index matching fieldIndex
                transportContainer = document.querySelector(`[data-transport-index="${fieldIndex}"]`);
            }
            
            // Pickup time now stored in hidden input with name pickupTimeName
            let pickupTimeField = null;
            const timeFieldContainer = document.getElementById(fieldIndex === 0 ? `day${day}_transport_additional_time_field` : `day${day}_transport_${fieldIndex}_additional_time_field`);
            if (timeFieldContainer) {
                const computedStyle = window.getComputedStyle(timeFieldContainer);
                if (computedStyle.display !== 'none' && computedStyle.visibility !== 'hidden') {
                    pickupTimeField = timeFieldContainer.querySelector(`[name="${pickupTimeName}"]`);
                }
            }
            
            // If not found, try within transport container
            if (!pickupTimeField && transportContainer) {
                pickupTimeField = transportContainer.querySelector(`[name="${pickupTimeName}"]`);
            }
            
            // If still not found, search globally
            if (!pickupTimeField) {
                pickupTimeField = document.querySelector(`[name="${pickupTimeName}"]`);
            }
            
            // Check if point-to-point fields are visible
            let pointToPointVisible = false;
            if (pickupLocationField) {
                const pickupContainer = pickupLocationField.closest('.point-to-point-field');
                if (pickupContainer) {
                    const computedStyle = window.getComputedStyle(pickupContainer);
                    pointToPointVisible = computedStyle.display !== 'none' && computedStyle.visibility !== 'hidden';
                }
            }
            
            // If point-to-point fields are not visible, disable button and return early
            if (!pointToPointVisible) {
                searchBtn.disabled = true;
                return;
            }
            
            // Check if all required fields are filled
            const cityFilled = cityField && cityField.value && String(cityField.value).trim() !== '';
            const pickupLocationFilled = pickupLocationField && pickupLocationField.value && String(pickupLocationField.value).trim() !== '';
            const pickupCoordinatesFilled = pickupLatField && pickupLngField && 
                                            pickupLatField.value && pickupLngField.value && 
                                            String(pickupLatField.value).trim() !== '' && String(pickupLngField.value).trim() !== '';
            const dropoffLocationFilled = dropoffLocationField && dropoffLocationField.value && String(dropoffLocationField.value).trim() !== '';
            const dropoffCoordinatesFilled = dropoffLatField && dropoffLngField && 
                                            dropoffLatField.value && dropoffLngField.value && 
                                            String(dropoffLatField.value).trim() !== '' && String(dropoffLngField.value).trim() !== '';
            
            // For pickup time, with hidden input, simply check if it has a non-empty value
            let pickupTimeFilled = false;
            if (pickupTimeField && pickupTimeField.value && pickupTimeField.value.trim() !== '') {
                pickupTimeFilled = true;
            }
            
            // All fields must be filled
            const allFieldsFilled = cityFilled && 
                                pickupLocationFilled && 
                                pickupCoordinatesFilled && 
                                dropoffLocationFilled && 
                                dropoffCoordinatesFilled && 
                                pickupTimeFilled;
            
            if (allFieldsFilled) {
                searchBtn.disabled = false;
                searchBtn.classList.remove('btn-secondary');
                searchBtn.classList.add('btn-primary');
                console.log('Search button enabled for point_to_point - all fields filled');
            } else {
                searchBtn.disabled = true;
                searchBtn.classList.remove('btn-primary');
                searchBtn.classList.add('btn-secondary');
                console.log('Search button disabled for point_to_point - missing fields:', {
                    cityFilled,
                    pickupLocationFilled,
                    pickupCoordinatesFilled,
                    dropoffLocationFilled,
                    dropoffCoordinatesFilled,
                    pickupTimeFilled,
                    pickupTimeField: pickupTimeField ? 'found' : 'not found',
                    pickupTimeValue: pickupTimeField ? pickupTimeField.value : 'N/A',
                    pickupTimeName: pickupTimeName,
                    fieldIndex: fieldIndex
                });
            }
        } else if (transportType === 'hourly') {
            console.log('Hourly transport type detected', index, 'transportIndex:', transportIndex);
            
            // Use transportIndex instead of index (which might be null/undefined)
            // For static transport, transportIndex will be 0
            // For dynamic transport, transportIndex will be the actual index (e.g., 2, 3, etc.)
            const fieldIndex = (transportIndex === null || transportIndex === undefined) ? 0 : transportIndex;
            
            // For static transport (index 0), field names don't include the index
            // For dynamic transport (index > 0), field names include the index
            const fieldNamePattern = fieldIndex === 0 ? `day${day}_transport` : `day${day}_transport_${fieldIndex}`;
            
            // Check city - city select always uses the index (0 for static, actual index for dynamic)
            const citySelect = document.getElementById(`day${day}_transport_city_${fieldIndex}`);
            const cityFilled = citySelect && citySelect.value && citySelect.value.trim() !== '';
            
            // Check pickup location (with coordinates)
            const pickupLocationField = document.querySelector(`input[name="${fieldNamePattern}_hourly_pickup_location"]`);
            const pickupLatField = document.getElementById(`${fieldNamePattern}_hourly_pickup_lat`);
            const pickupLngField = document.getElementById(`${fieldNamePattern}_hourly_pickup_lng`);
            const pickupLocationFilled = pickupLocationField && pickupLocationField.value && pickupLocationField.value.trim() !== '';
            const pickupCoordinatesFilled = pickupLatField && pickupLngField && pickupLatField.value && pickupLngField.value && pickupLatField.value.trim() !== '' && pickupLngField.value.trim() !== '';
            
            // Check pickup time (stored in hidden input with name "${fieldNamePattern}_hourly_pickup_time")
            const pickupTimeField = document.querySelector(`[name="${fieldNamePattern}_hourly_pickup_time"]`);
            const pickupTimeFilled = pickupTimeField && pickupTimeField.value && pickupTimeField.value.trim() !== '';
            
            // Check selected hours
            const selectedHoursField = document.querySelector(`select[name="${fieldNamePattern}_hourly_selected_hours"]`);
            const selectedHoursFilled = selectedHoursField && selectedHoursField.value && selectedHoursField.value.trim() !== '';
            
            console.log('Hourly transport validation:', {
                cityFilled: cityFilled ? citySelect.value : false,
                pickupLocationFilled: pickupLocationFilled ? pickupLocationField.value : false,
                pickupCoordinatesFilled: pickupCoordinatesFilled ? `${pickupLatField.value}, ${pickupLngField.value}` : false,
                pickupTimeFilled: pickupTimeFilled ? pickupTimeField.value : false,
                selectedHoursFilled: selectedHoursFilled ? selectedHoursField.value : false,
                fieldIndex: fieldIndex,
                fieldNamePattern: fieldNamePattern,
                citySelectId: `day${day}_transport_city_${fieldIndex}`,
                citySelectFound: !!citySelect,
                pickupLocationField: pickupLocationField ? pickupLocationField.name : 'NOT FOUND',
                pickupLocationValue: pickupLocationField ? pickupLocationField.value : 'N/A',
                pickupTimeField: pickupTimeField ? pickupTimeField.name : 'NOT FOUND',
                pickupTimeValue: pickupTimeField ? pickupTimeField.value : 'N/A',
                selectedHoursField: selectedHoursField ? selectedHoursField.name : 'NOT FOUND',
                selectedHoursValue: selectedHoursField ? selectedHoursField.value : 'N/A'
            });
            
            // All fields must be filled - if ANY field is missing, button should be disabled
            const allFieldsFilled = cityFilled && 
                                pickupLocationFilled && 
                                pickupCoordinatesFilled && 
                                pickupTimeFilled && 
                                selectedHoursFilled;
            
            if (allFieldsFilled) {
                searchBtn.disabled = false;
                searchBtn.classList.remove('btn-secondary');
                searchBtn.classList.add('btn-primary');
                console.log('Search button enabled for hourly - all fields filled');
            } else {
                searchBtn.disabled = true;
                searchBtn.classList.remove('btn-primary');
                searchBtn.classList.add('btn-secondary');
                console.log('Search button disabled for hourly - missing fields:', {
                    cityFilled,
                    pickupLocationFilled,
                    pickupCoordinatesFilled,
                    pickupTimeFilled,
                    selectedHoursFilled
                });
            }
        } else if (transportType === 'local_transfer') {
            // For local_transfer, only need pickup zone selected (dropoff will be populated based on pickup)
            console.log('Local transfer transport type detected', index);
            const pickupZoneSelect = qs(`select[name="day${day}_${baseSection}_pickup_zone_id"]`);
            const dropoffZoneSelect = qs(`select[name="day${day}_${baseSection}_dropoff_zone_id"]`);
            
            console.log('Local transfer validation:', {
                pickup: pickupZoneSelect?.value,
                dropoff: dropoffZoneSelect?.value,
                baseSection: baseSection
            });
            
            if (pickupZoneSelect && pickupZoneSelect.value) {
                searchBtn.disabled = false;
                searchBtn.classList.remove('btn-secondary');
                searchBtn.classList.add('btn-primary');
                console.log('Search button enabled for local_transfer - pickup zone selected');
            } else {
                searchBtn.disabled = true;
                searchBtn.classList.remove('btn-primary');
                searchBtn.classList.add('btn-secondary');
                console.log('Search button disabled for local_transfer - no pickup zone selected');
            }
        } else {
            // Default behavior for other sections (entry, exit) or when no transport type is detected
            // If this is a transport section and no specific type is detected, check if we have pickup zones
            if (baseSection.includes('transport')) {
                const pickupZoneSelect = qs(`select[name="day${day}_${baseSection}_pickup_zone_id"]`);
                if (pickupZoneSelect && pickupZoneSelect.value) {
                    searchBtn.disabled = false;
                    searchBtn.classList.remove('btn-secondary');
                    searchBtn.classList.add('btn-primary');
                    console.log('Search button enabled for transport (default/local transfer with pickup zone)');
                } else {
                    searchBtn.disabled = true;
                    searchBtn.classList.remove('btn-primary');
                    searchBtn.classList.add('btn-secondary');
                    console.log('Search button disabled for transport (no pickup zone selected)');
                }
            } else {
                // For non-transport sections (entry, exit)
                searchBtn.disabled = false;
                searchBtn.classList.remove('btn-secondary');
                searchBtn.classList.add('btn-primary');
                console.log('Search button enabled for default section');
            }
        }
    }
    
    // Add event listeners to pickup time fields for entry port and transport sections
    function setupSearchButtonListeners() {
        // For each day, set up listeners for pickup time fields
        for (let day = 1; day <= 7; day++) {
            const entrySearchBtn = document.getElementById(`day${day}_entry_search_btn`);
            const entryPickupTimeInput = document.getElementById(`day${day}_entry_pickup_time_input`);
            const entryPickupTimeAmpm = document.getElementById(`day${day}_entry_pickup_time_ampm`);
            const transportPickupTimeInput = document.getElementById(`day${day}_transport_pickup_time_input`);
            const transportPickupTimeAmpm = document.getElementById(`day${day}_transport_pickup_time_ampm`);
            const transportSearchBtn = document.getElementById(`day${day}_transport_search_btn`);
            
            if (entryPickupTimeInput) {
                entryPickupTimeInput.addEventListener('input', () => { formatTimeInput(entryPickupTimeInput); syncEntryPickupTime(day); enableSearchButton(day, 'entry'); });
                entryPickupTimeInput.addEventListener('change', () => { syncEntryPickupTime(day); enableSearchButton(day, 'entry'); });
            }
            if (entryPickupTimeAmpm) {
                entryPickupTimeAmpm.addEventListener('change', () => { syncEntryPickupTime(day); enableSearchButton(day, 'entry'); });
            }
            
            // Add event listener for transport pickup time (local transfer)
            if (transportPickupTimeInput) {
                transportPickupTimeInput.addEventListener('input', () => { formatTimeInput(transportPickupTimeInput); syncTransportPickupTime(day); enableSearchButton(day, 'transport'); });
                transportPickupTimeInput.addEventListener('change', () => { syncTransportPickupTime(day); enableSearchButton(day, 'transport'); });
            }
            if (transportPickupTimeAmpm) {
                transportPickupTimeAmpm.addEventListener('change', () => { syncTransportPickupTime(day); enableSearchButton(day, 'transport'); });
            }
            
            // Initially enable search buttons
            if (entrySearchBtn) {
                entrySearchBtn.disabled = false;
                entrySearchBtn.classList.remove('btn-secondary');
                entrySearchBtn.classList.add('btn-primary');
            }
            if (transportSearchBtn) {
                transportSearchBtn.disabled = false;
                transportSearchBtn.classList.remove('btn-secondary');
                transportSearchBtn.classList.add('btn-primary');
            }
        }
        
        // Transport search button states are now managed per section when cities are selected
        
        // Enable all search buttons on page load
        setTimeout(() => {
            for (let day = 1; day <= 7; day++) {
                enableSearchButton(day, 'entry');
                enableSearchButton(day, 'transport');
                enableSearchButton(day, 'exit');
                
                // Enable additional transport sections
                const additionalTransports = document.querySelectorAll(`[data-transport-index]`);
                additionalTransports.forEach(transport => {
                    const index = transport.getAttribute('data-transport-index');
                    if (index && index !== '1') {
                        enableSearchButton(day, `transport_${index}`);
                    }
                });
            }
        }, 1000);
    }

    function fetchZonesForAllTransportSections(city) {
    console.log('Fetching zones and locations for city:', city);
    
    // Fetch both zones and locations data
    Promise.all([
        fetch(`{{ route('fetch-zones-by-dmc') }}?city=${encodeURIComponent(city)}`).then(response => response.json()),
        fetch(`{{ route('fetch-zone-assigned-locations') }}`).then(response => response.json())
    ]).then(([zonesData, locationsData]) => {
        console.log('Zones data received:', zonesData);
        console.log('Locations data received:', locationsData);
        
        if (zonesData.success && zonesData.zones) {
                    // Store zones data globally for use in other functions
            window.allZonesData = zonesData.zones;
        }
        
        if (locationsData.success && locationsData.locations) {
            // Store locations data globally for use in other functions
            window.allLocationsData = locationsData.locations;
        }
                    
                    // Update all pickup zone selects
                    const pickupZoneSelects = document.querySelectorAll('.pickup-zone-select');
                    console.log('Found pickup zone selects:', pickupZoneSelects.length);
                    
                    pickupZoneSelects.forEach((select, index) => {
            // Skip entry port pickup dropdowns (they should show ports, not zones)
            if (select.name && select.name.includes('_entry_pickup_zone_id')) {
                console.log(`Skipping entry port pickup select ${index}:`, select.name);
                return;
            }
            
            // Skip exit port pickup dropdowns (they're handled separately below)
            if (select.name && select.name.includes('_exit_pickup_zone_id')) {
                console.log(`Skipping exit port pickup select ${index}:`, select.name);
                return;
            }
            
            // For local transfer pickup selects, use location data with hotels, attractions, restaurants
            if (select.name && select.name.includes('_transport_') && locationsData.success && locationsData.locations) {
                console.log(`Updating local transfer pickup select ${index} with locations:`, select.name);
                select.innerHTML = '<option value="">Select pickup location</option>';
                
                locationsData.locations.forEach(location => {
                    const option = document.createElement('option');
                    option.value = location.id;
                    
                    // Enhanced display format with icons for different types
                    let icon = '';
                    switch(location.type) {
                        case 'hotel':
                            icon = '🏨';
                            break;
                        case 'restaurant':
                            icon = '🍽️';
                            break;
                        case 'attraction':
                            icon = '🎯';
                            break;
                        default:
                            icon = '📍';
                    }
                    
                    option.textContent = `${icon} ${location.name} (${location.type}) - ${location.location}`;
                    option.dataset.type = location.type;
                    option.dataset.latitude = location.latitude || '';
                    option.dataset.longitude = location.longitude || '';
                    select.appendChild(option);
                });
                
                select.disabled = false;
            } else if (zonesData.success && zonesData.zones) {
                // For other pickup selects, use zone data
                console.log(`Updating pickup zone select ${index} with zones:`, select.name);
                        select.innerHTML = '<option value="">Select pickup zone</option>';
                zonesData.zones.forEach(zone => {
                            select.innerHTML += `<option value="${zone.zone_id}">${zone.zone_name} (${zone.zone_type})</option>`;
                        });
                        select.disabled = false;
            }
                    });
                    
                    // Populate exit port pickup dropdowns with zone-assigned locations
                    const exitPickupSelects = document.querySelectorAll('select[name*="_exit_pickup_zone_id"]');
                    console.log('Found exit port pickup selects:', exitPickupSelects.length);
                    
                    exitPickupSelects.forEach((select, index) => {
                        console.log(`Populating exit port pickup select ${index}:`, select.name);
                        select.innerHTML = '<option value="">Loading locations...</option>';
                        
                        fetch(`{{ route('fetch-zone-assigned-locations') }}`)
                            .then(response => response.json())
                            .then(data => {
                                console.log('Zone-assigned locations response for exit pickup:', data);
                                if (data.success && data.locations && Array.isArray(data.locations)) {
                                    console.log('Zone-assigned locations fetched for exit pickup:', data.locations.length);
                                    
                                    // Count locations by type for debugging
                                    const locationsByType = {
                                        attraction: data.locations.filter(loc => loc.type === 'attraction').length,
                                        hotel: data.locations.filter(loc => loc.type === 'hotel').length,
                                        restaurant: data.locations.filter(loc => loc.type === 'restaurant').length
                                    };
                                    console.log('Exit pickup locations breakdown:', locationsByType);
                                    console.log('Hotels found:', data.locations.filter(loc => loc.type === 'hotel'));
                                    
                                    select.innerHTML = '<option value="">Select pickup location</option>';
                                    
                                    data.locations.forEach(location => {
                                        const option = document.createElement('option');
                                        option.value = location.id;
                                        
                                        // Enhanced display format with icons for different types
                                        let icon = '';
                                        switch(location.type) {
                                            case 'hotel':
                                                icon = '🏨';
                                                break;
                                            case 'restaurant':
                                                icon = '🍽️';
                                                break;
                                            case 'attraction':
                                                icon = '🎯';
                                                break;
                                            default:
                                                icon = '📍';
                                        }
                                        
                                        option.textContent = `${icon} ${location.name} (${location.type}) - ${location.location}`;
                                        option.dataset.type = location.type;
                                        option.dataset.latitude = location.latitude || '';
                                        option.dataset.longitude = location.longitude || '';
                                        select.appendChild(option);
                                    });
                                    
                                    select.disabled = false;
                                } else {
                                    console.log('No valid locations data received for exit pickup:', data);
                                    select.innerHTML = '<option value="">No locations available</option>';
                                    select.disabled = true;
                                }
                            })
                            .catch(error => {
                                console.error('Error fetching zone-assigned locations for exit pickup:', error);
                                select.innerHTML = '<option value="">Error loading locations</option>';
                                select.disabled = true;
                            });
                    });
                    
                    // Update all dropoff zone selects initially
                    const dropoffZoneSelects = document.querySelectorAll('.dropoff-zone-select');
                    console.log('Found dropoff zone selects:', dropoffZoneSelects.length);
                    
                    dropoffZoneSelects.forEach((select, index) => {
                        // Skip exit port dropoff dropdowns (they should show ports, not zones)
                        if (select.name && select.name.includes('_exit_dropoff_zone_id')) {
                            console.log(`Skipping exit port dropoff select ${index}:`, select.name);
                            return;
                        }
                        
                        // For local transfer dropoff selects, prepare for location data
                        if (select.name && select.name.includes('_transport_') && locationsData.success && locationsData.locations) {
                            console.log(`Updating local transfer dropoff select ${index} for locations:`, select.name);
                            select.innerHTML = '<option value="">Select pickup location first</option>';
                            select.disabled = true;
                        } else if (zonesData.success && zonesData.zones) {
                            // For other dropoff selects, use zone data
                            console.log(`Updating dropoff zone select ${index} with zones:`, select.name);
                        select.innerHTML = '<option value="">Select pickup zone first</option>';
                            zonesData.zones.forEach(zone => {
                            select.innerHTML += `<option value="${zone.zone_id}">${zone.zone_name} (${zone.zone_type})</option>`;
                        });
                        select.disabled = true;
                            console.log(`Dropoff select ${index} has ${zonesData.zones.length} zones but is disabled`);
                        }
                    });
                    
                    const vehicleSelects = document.querySelectorAll('.vehicle-select');
                    vehicleSelects.forEach(select => {
                        select.innerHTML = '<option value="">Select pickup first</option>';
                        select.disabled = true;
                    });
                    
                    const serviceTypeSelects = document.querySelectorAll('.service-type-select');
                    serviceTypeSelects.forEach(select => {
                        // Keep hardcoded options, just disable and reset selection
                        select.disabled = true;
                        select.value = "";
                    });
                    
                    // Populate ports dropdowns after zones are loaded
                    populatePortsDropdowns();
                    
                    // Check if Point-to-Point functionality should be enabled
                    const isPointToPointElement = document.getElementById('is_point_to_point');
                    const isPointToPoint = isPointToPointElement && isPointToPointElement.value === '1';
                    console.log('Point-to-Point check:', {
                        element: !!isPointToPointElement,
                        value: isPointToPointElement ? isPointToPointElement.value : 'not found',
                        isEnabled: isPointToPoint
                    });
                    
                    if (isPointToPoint) {
                        console.log('Point-to-Point functionality enabled (zone_on = 0)');
                        enablePointToPointFunctionality();
                    } else {
                        console.log('Point-to-Point functionality disabled (zone_on != 0 or not found)');
                    }
            })
            .catch(error => {
            console.error('Error fetching zones and locations:', error);
            
            // Reset all selects in case of error
            const allPickupSelects = document.querySelectorAll('.pickup-zone-select');
            const allDropoffSelects = document.querySelectorAll('.dropoff-zone-select');
            
            allPickupSelects.forEach(select => {
                if (!select.name || (!select.name.includes('_entry_pickup_zone_id') && !select.name.includes('_exit_pickup_zone_id'))) {
                    select.innerHTML = '<option value="">Error loading data</option>';
                    select.disabled = true;
                }
            });
            
            allDropoffSelects.forEach(select => {
                if (!select.name || !select.name.includes('_exit_dropoff_zone_id')) {
                    select.innerHTML = '<option value="">Error loading data</option>';
                    select.disabled = true;
                }
            });
            });
    }

    // Function to load attractions, hotels and restaurants when city is selected
    function loadPortsForCity(cityName) {
        console.log('Loading locations for city:', cityName);
        
        // Reset pickup port select when city changes
        const pickupSelect = document.getElementById('entry_pickup_port_select');
        if (pickupSelect) {
            // Reset to default option
            pickupSelect.value = '';
            // If Select2 is initialized, trigger change to update it
            if (typeof jQuery !== 'undefined' && jQuery(pickupSelect).hasClass('select2-hidden-accessible')) {
                jQuery(pickupSelect).val(null).trigger('change');
            }
            console.log('Pickup port select reset');
        }
        
        if (!cityName) {
            console.log('No city selected, clearing dropoff options');
            const dropoffSelect = document.getElementById('entry_dropoff_location_select');
            if (dropoffSelect) {
                dropoffSelect.innerHTML = '<option value="">Select city first</option>';
                dropoffSelect.disabled = true;
            }
            // Re-evaluate search button state
            enableSearchButton(1, 'entry');
            return;
        }
        
        // Get DMC ID for the requests
        const dmcId = '{{ $finalDmcId }}';
        const dropoffSelect = document.getElementById('entry_dropoff_location_select');
        
        if (!dropoffSelect) {
            console.warn('Entry dropoff select not found');
            return;
        }
        
        // Show loading state
        dropoffSelect.innerHTML = '<option value="">Loading locations...</option>';
        dropoffSelect.disabled = true;
        
        // Make AJAX calls for attractions, hotels and restaurants
        console.log('Making AJAX calls for city:', cityName, 'DMC ID:', dmcId);
        
        Promise.all([
            window.fetchJsonDeduped(`{{ route('fetch-hotels-by-dmc') }}?city=${encodeURIComponent(cityName)}&dmc_id=${dmcId}`),
            window.fetchJsonDeduped(`{{ route('fetch-attractions-by-dmc') }}?city=${encodeURIComponent(cityName)}&dmc_id=${dmcId}`),
            window.fetchJsonDeduped(`{{ route('fetch-restaurants-by-dmc') }}?city=${encodeURIComponent(cityName)}&dmc_id=${dmcId}`)
        ])
        .then(([hotelsData, attractionsData, restaurantsData]) => {
            console.log('AJAX responses received:');
            console.log('Hotels:', hotelsData);
            console.log('Attractions:', attractionsData);
            console.log('Restaurants:', restaurantsData);
            
            // Clear the dropdown
            dropoffSelect.innerHTML = '<option value="">Select pickup port first</option>';
            
            // Add Ports first (use filtered ports from country selection if available, otherwise use static ports)
            const ports = window.filteredPortsData || @json($ports ?? []);
            if (ports && ports.length > 0) {
                const portGroup = document.createElement('optgroup');
                portGroup.label = 'Ports';
                
                ports.forEach(port => {
                    const option = document.createElement('option');
                    // Handle both filtered port format (port.id) and static port format (port.port_id)
                    option.value = port.id || port.port_id;
                    option.textContent = port.port_name;
                    option.setAttribute('data-type', 'Port');
                    option.setAttribute('data-port', JSON.stringify(port));
                    if (port.port_id) {
                        option.dataset.portId = port.port_id;
                    }
                    portGroup.appendChild(option);
                });
                
                dropoffSelect.appendChild(portGroup);
                console.log(`Added ${ports.length} ports to entry dropoff location`);
            }
            
            // Add Hotels: always show ALL hotels from API for the city (not only previously selected)
            if (hotelsData.success && hotelsData.hotels && hotelsData.hotels.length > 0) {
                const hotelGroup = document.createElement('optgroup');
                hotelGroup.label = 'Hotels';
                
                hotelsData.hotels.forEach(hotel => {
                    const option = document.createElement('option');
                    const starInfo = hotel.hotel_star_rating ? ` (${hotel.hotel_star_rating} ⭐)` : '';
                    option.value = hotel.hotel_unique_id;
                    option.textContent = hotel.name + starInfo;
                    option.setAttribute('data-type', 'Hotel');
                    option.setAttribute('data-hotel', JSON.stringify(hotel));
                    hotelGroup.appendChild(option);
                });
                
                dropoffSelect.appendChild(hotelGroup);
                console.log(`Added ${hotelsData.hotels.length} hotels to entry dropoff`);
                
                // Auto-select last added hotel from package if it exists in the list
                if (typeof selectedHotels !== 'undefined' && Array.isArray(selectedHotels) && selectedHotels.length > 0) {
                    const lastHotel = selectedHotels[selectedHotels.length - 1];
                    const lastHotelId = lastHotel.id || lastHotel.hotel_unique_id;
                    const lastHotelOption = Array.from(dropoffSelect.options).find(opt => {
                        return opt.value === String(lastHotelId) || opt.value === lastHotelId;
                    });
                    if (lastHotelOption) {
                        dropoffSelect.value = lastHotelOption.value;
                        dropoffSelect.dispatchEvent(new Event('change', { bubbles: true }));
                        console.log('Auto-selected last hotel for entry dropoff:', lastHotel.name);
                    }
                }
            }
            
            // Add Attractions
            if (attractionsData.success && attractionsData.attractions && attractionsData.attractions.length > 0) {
                const attractionGroup = document.createElement('optgroup');
                attractionGroup.label = 'Attractions';
                
                attractionsData.attractions.forEach(attraction => {
                    const option = document.createElement('option');
                    option.value = attraction.attraction_id;
                    option.textContent = attraction.name;
                    option.setAttribute('data-type', 'Attraction');
                    option.setAttribute('data-attraction', JSON.stringify(attraction));
                    attractionGroup.appendChild(option);
                });
                
                dropoffSelect.appendChild(attractionGroup);
                console.log(`Added ${attractionsData.attractions.length} attractions`);
            }
            
            // Add Restaurants
            if (restaurantsData.success && restaurantsData.restaurants && restaurantsData.restaurants.length > 0) {
                const restaurantGroup = document.createElement('optgroup');
                restaurantGroup.label = 'Restaurants';
                
                restaurantsData.restaurants.forEach(restaurant => {
                    const option = document.createElement('option');
                    option.value = restaurant.restaurant_id;
                    option.textContent = restaurant.name;
                    option.setAttribute('data-type', 'Restaurant');
                    option.setAttribute('data-restaurant', JSON.stringify(restaurant));
                    restaurantGroup.appendChild(option);
                });
                
                dropoffSelect.appendChild(restaurantGroup);
                console.log(`Added ${restaurantsData.restaurants.length} restaurants`);
            }
            
            console.log('Successfully loaded all locations for city:', cityName);
            // Note: Dropdown remains disabled until pickup port is selected
            
            // Re-evaluate search button state after loading locations
            enableSearchButton(1, 'entry');
        })
        .catch(error => {
            console.error('Error loading locations:', error);
            dropoffSelect.innerHTML = '<option value="">Error loading locations</option>';
            dropoffSelect.disabled = true;
        });
    }

    // Function to load ports and locations for exit port when city is selected
