                const pickupInput = document.getElementById(`day${day}_exit_pickup_location`);
                const dropoffInput = document.getElementById(`day${day}_exit_dropoff_location`);
                
                if (pickupInput) {
                    pickupInput.addEventListener('input', () => enableSearchButton(day, 'exit'));
                    
                    // Automatically set pickup location to last selected hotel
                    if (typeof selectedHotels !== 'undefined' && selectedHotels && selectedHotels.length > 0) {
                        const lastHotel = selectedHotels[selectedHotels.length - 1];
                        const lastHotelName = lastHotel.name;
                        if (lastHotelName && !pickupInput.value) {
                            pickupInput.value = lastHotelName;
                            console.log('Auto-filled exit pickup location with last hotel:', lastHotelName);
                            // Trigger input event to update search button state
                            pickupInput.dispatchEvent(new Event('input', { bubbles: true }));
                        }
                    } else if (lastSelectedHotelId && typeof hotelData !== 'undefined' && hotelData.length > 0) {
                        // Fallback: find hotel by lastSelectedHotelId
                        const lastHotel = hotelData.find(h => h.hotel_unique_id == lastSelectedHotelId);
                        if (lastHotel && lastHotel.name && !pickupInput.value) {
                            pickupInput.value = lastHotel.name;
                            console.log('Auto-filled exit pickup location with last hotel (fallback):', lastHotel.name);
                            pickupInput.dispatchEvent(new Event('input', { bubbles: true }));
                        }
                    }
                }
                if (dropoffInput) {
                    dropoffInput.addEventListener('input', () => enableSearchButton(day, 'exit'));
                }
                
                // Apply zone_on = 0 logic to primary exit port - show custom price field and set service type to Private
                setTimeout(() => {
                    console.log(`Zone = 0 detected for primary exit port - showing custom price field and setting service type to Private`);
                    
                    // Show custom price field for primary exit port
                    const exitPriceField = document.getElementById(`day${day}_exit_0_price_field`);
                    if (exitPriceField) {
                        exitPriceField.style.display = 'block';
                        console.log(`Showing custom price field for primary exit port (zone=0): day${day}_exit_0_price_field`);
                    }
                    
                    // Set service type to Private and make it readonly for primary exit port
                    const serviceTypeSelect = document.getElementById(`day${day}_exit_0_service_type`);
                    if (serviceTypeSelect) {
                        serviceTypeSelect.value = 'Private';
                        serviceTypeSelect.disabled = true;
                        serviceTypeSelect.style.backgroundColor = '#f8f9fa';
                        serviceTypeSelect.style.cursor = 'not-allowed';
                        console.log(`Set primary exit port service type to Private (readonly) for zone=0: day${day}_exit_0_service_type`);
                    }
                }, 200);
            }, 100);
            
        } else {
            // zone_on = 1: Create zone-based select dropdowns
            console.log('Creating zone-based select dropdowns for exit port (zone_on = 1)');
            
            // Pickup field (hotels, attractions, restaurants - where customer is staying/visiting)
            pickupContainer.innerHTML = `
                <select class="form-select pickup-zone-select border-2" name="day${day}_exit_pickup_zone_id" style="padding-left: 45px;" id="exit_pickup_location_select" onchange="handlePickupZoneChange(${day}, 'exit')">
                    <option value="">Select city first</option>
