    // Function to enable Point-to-Point functionality when zone_on = 0
    function enablePointToPointFunctionality() {
        console.log('Enabling Point-to-Point functionality for entry and exit ports...');
        
        // Find all entry and exit port zone select containers
        const entryPickupSelects = document.querySelectorAll('select[name*="_entry_pickup_zone_id"]');
        const entryDropoffSelects = document.querySelectorAll('select[name*="_entry_dropoff_zone_id"]');
        const exitPickupSelects = document.querySelectorAll('select[name*="_exit_pickup_zone_id"]');
        const exitDropoffSelects = document.querySelectorAll('select[name*="_exit_dropoff_zone_id"]');
        
        console.log(`Found ${entryPickupSelects.length} entry pickup selects`);
        console.log(`Found ${entryDropoffSelects.length} entry dropoff selects`);
        console.log(`Found ${exitPickupSelects.length} exit pickup selects`);
        console.log(`Found ${exitDropoffSelects.length} exit dropoff selects`);
        
        // Convert entry pickup selects to Google Maps location inputs
        entryPickupSelects.forEach((select, index) => {
            if (select.name) {
                const dayMatch = select.name.match(/day(\d+)/);
                const day = dayMatch ? dayMatch[1] : index + 1;
                convertSelectToLocationInput(select, day, 'entry', 'pickup');
            }
        });
        
        // Convert entry dropoff selects to Google Maps location inputs
        entryDropoffSelects.forEach((select, index) => {
            if (select.name) {
                const dayMatch = select.name.match(/day(\d+)/);
                const day = dayMatch ? dayMatch[1] : index + 1;
                convertSelectToLocationInput(select, day, 'entry', 'dropoff');
            }
        });
        
        // Convert exit pickup selects to Google Maps location inputs
        exitPickupSelects.forEach((select, index) => {
            if (select.name) {
                const dayMatch = select.name.match(/day(\d+)/);
                const day = dayMatch ? dayMatch[1] : index + 1;
                convertSelectToLocationInput(select, day, 'exit', 'pickup');
            }
        });
        
        // Convert exit dropoff selects to Google Maps location inputs
        exitDropoffSelects.forEach((select, index) => {
            if (select.name) {
                const dayMatch = select.name.match(/day(\d+)/);
                const day = dayMatch ? dayMatch[1] : index + 1;
                convertSelectToLocationInput(select, day, 'exit', 'dropoff');
            }
        });
        
        // Initialize Google Maps autocomplete for the new location inputs
        setTimeout(() => {
            initializeGoogleMapsAutocomplete();
            console.log('Google Maps autocomplete initialized for Point-to-Point entry/exit ports');
            
            // Enable search buttons for entry/exit ports since we now have location inputs
            enablePointToPointSearchButtons();
        }, 500);
        
        console.log('Point-to-Point functionality enabled successfully for entry and exit ports');
    }

    // Function to convert zone select to Google Maps location input
    function convertSelectToLocationInput(selectElement, day, portType, direction) {
        const container = selectElement.closest('.position-relative') || selectElement.parentElement;
        
        if (!container) {
            console.warn(`Container not found for select: ${selectElement.name}`);
            return;
        }
        
        // Create Google Maps location input HTML
        const locationInputHtml = `
            <input type="text" 
                class="form-control border-2 google-maps-autocomplete" 
                name="day${day}_${portType}_${direction}_location" 
                id="day${day}_${portType}_${direction}_location" 
                placeholder="Search for ${direction} location..." 
                style="padding-left: 45px;">
            <i class="ri-map-pin-line position-absolute text-${direction === 'pickup' ? 'success' : 'danger'} location-icon" 
            style="left: 15px; top: 50%; transform: translateY(-50%); z-index: 5;"></i>
            <input type="hidden" name="day${day}_${portType}_${direction}_lat" id="day${day}_${portType}_${direction}_lat">
            <input type="hidden" name="day${day}_${portType}_${direction}_lng" id="day${day}_${portType}_${direction}_lng">
            <input type="hidden" name="day${day}_${portType}_${direction}_place_id" id="day${day}_${portType}_${direction}_place_id">
        `;
        
        // Replace the select with location input
        container.innerHTML = locationInputHtml;
        container.classList.add('location-input');
        
        console.log(`Converted ${portType} ${direction} select to Google Maps location input for day ${day}`);
    }

    // Function to enable search buttons for Point-to-Point entry/exit ports
    function enablePointToPointSearchButtons() {
        console.log('Enabling search buttons for Point-to-Point entry/exit ports...');
        
        // Find all entry and exit search buttons
        const entrySearchButtons = document.querySelectorAll('button[id*="_entry_search_btn"]');
        const exitSearchButtons = document.querySelectorAll('button[id*="_exit_search_btn"]');
        
        console.log(`Found ${entrySearchButtons.length} entry search buttons`);
        console.log(`Found ${exitSearchButtons.length} exit search buttons`);
        
        // Check if city is selected in the transport section (required for Point-to-Point vehicle search)
        const transportCitySelect = document.getElementById(`day${day}_transport_city_1`);
        const citySelected = transportCitySelect && transportCitySelect.value;
        
        if (citySelected) {
            // Enable entry port search buttons
            entrySearchButtons.forEach(button => {
                button.disabled = false;
                button.classList.remove('btn-secondary');
                button.classList.add('btn-primary');
                console.log(`Enabled entry search button: ${button.id}`);
            });
            
            // Enable exit port search buttons
            exitSearchButtons.forEach(button => {
                button.disabled = false;
                button.classList.remove('btn-secondary');
                button.classList.add('btn-primary');
                console.log(`Enabled exit search button: ${button.id}`);
            });
            
            console.log('All Point-to-Point entry/exit search buttons enabled');
        } else {
            console.log('City not selected - search buttons remain disabled');
        }
    }

    function loadDropoffZones(day, section) {
        const pickupZoneSelect = document.querySelector(`select[name="day${day}_${section}_pickup_zone_id"]`);
        const dropoffZoneSelect = document.querySelector(`select[name="day${day}_${section}_dropoff_zone_id"]`);
        
        if (!pickupZoneSelect || !dropoffZoneSelect) return;
        
        const pickupZoneId = pickupZoneSelect.value;
        
        if (pickupZoneId) {
            // Check if this is an entry port dropoff (should show zone-assigned locations, not zones)
            if (section === 'entry' && dropoffZoneSelect.name.includes('_entry_dropoff_zone_id')) {
                // For entry port dropoff, populate with zone-assigned locations
                console.log('Populating entry port dropoff with zone-assigned locations');
                dropoffZoneSelect.innerHTML = '<option value="">Loading locations...</option>';
                
                fetch(`{{ route('fetch-zone-assigned-locations') }}`)
                                    .then(response => response.json())
                    .then(data => {
                        console.log('Zone-assigned locations response:', data);
                        if (data.success && data.locations && Array.isArray(data.locations)) {
                            console.log('Zone-assigned locations fetched:', data.locations.length);
                            dropoffZoneSelect.innerHTML = '<option value="">Select dropoff location</option>';
                            
                            // Add Ports first (use filtered ports from country selection if available, otherwise use static ports)
                            const ports = window.filteredPortsData || @json($ports ?? []);
                            if (ports && ports.length > 0) {
                                const portGroup = document.createElement('optgroup');
                                portGroup.label = 'Ports';
                                
                                ports.forEach(port => {
                                    const option = document.createElement('option');
                                    // Handle both filtered port format (port.id) and static port format (port.port_id)
                                    option.value = port.id || port.port_id;
                                    option.textContent = port.port_name;
                                    option.setAttribute('data-type', 'Port');
                                    option.setAttribute('data-port', JSON.stringify(port));
                                    if (port.port_id) {
                                        option.dataset.portId = port.port_id;
                                    }
                                    portGroup.appendChild(option);
                                });
                                
                                dropoffZoneSelect.appendChild(portGroup);
                                console.log(`Added ${ports.length} ports to dropoff`);
                            }
                            
                            data.locations.forEach(location => {
                                const option = document.createElement('option');
                                option.value = location.id;
                                
                                // Enhanced display format with icons for different types
                                let icon = '';
                                switch(location.type) {
                                    case 'hotel':
                                        icon = '🏨';
                                        break;
                                    case 'restaurant':
                                        icon = '🍽️';
                                        break;
                                    case 'attraction':
                                        icon = '🎯';
                                        break;
                                    default:
                                        icon = '📍';
                                }
                                
                                option.textContent = `${icon} ${location.name} (${location.type}) - ${location.location}`;
                                option.dataset.type = location.type;
                                option.dataset.latitude = location.latitude || '';
                                option.dataset.longitude = location.longitude || '';
                                dropoffZoneSelect.appendChild(option);
                            });
                            
                            dropoffZoneSelect.disabled = false;
                        } else {
                            console.log('No valid locations data received:', data);
                            dropoffZoneSelect.innerHTML = '<option value="">No locations available</option>';
                            dropoffZoneSelect.disabled = true;
                        }
                    })
                    .catch(error => {
                        console.error('Error fetching zone-assigned locations:', error);
                        dropoffZoneSelect.innerHTML = '<option value="">Error loading locations</option>';
                        dropoffZoneSelect.disabled = true;
                    });
                    } else if (section === 'transport' && dropoffZoneSelect.name.includes('_transport_')) {
                // For local transfer dropoff, populate with zone-assigned locations (excluding pickup location)
                dropoffZoneSelect.innerHTML = '<option value="">Loading locations...</option>';
                
                fetch(`{{ route('fetch-zone-assigned-locations') }}`)
                    .then(response => response.json())
                    .then(data => {
                        console.log('Zone-assigned locations response for local transfer:', data);
                        if (data.success && data.locations && Array.isArray(data.locations)) {
                            console.log('Zone-assigned locations fetched for local transfer:', data.locations.length);
                            dropoffZoneSelect.innerHTML = '<option value="">Select dropoff location</option>';
                            
                            data.locations.forEach(location => {
                                // Skip the currently selected pickup location
                                if (location.id == pickupZoneId) {
                                    console.log(`Skipping pickup location in dropoff list: ${location.name}`);
                                    return;
                                }
                                
                                const option = document.createElement('option');
                                option.value = location.id;
                                
                                // Enhanced display format with icons for different types
                                let icon = '';
                                switch(location.type) {
                                    case 'hotel':
                                        icon = '🏨';
                                        break;
                                    case 'restaurant':
                                        icon = '🍽️';
                                        break;
                                    case 'attraction':
                                        icon = '🎯';
                                        break;
                                    default:
                                        icon = '📍';
                                }
                                
                                option.textContent = `${icon} ${location.name} (${location.type}) - ${location.location}`;
                                option.dataset.type = location.type;
                                option.dataset.latitude = location.latitude || '';
                                option.dataset.longitude = location.longitude || '';
                                dropoffZoneSelect.appendChild(option);
                            });
                            
                            dropoffZoneSelect.disabled = false;
                        } else {
                            console.log('No valid locations data received for local transfer:', data);
                            dropoffZoneSelect.innerHTML = '<option value="">No locations available</option>';
                            dropoffZoneSelect.disabled = true;
                        }
                    })
                    .catch(error => {
                        console.error('Error fetching zone-assigned locations for local transfer:', error);
                        dropoffZoneSelect.innerHTML = '<option value="">Error loading locations</option>';
                        dropoffZoneSelect.disabled = true;
                    });
            } else {
                // For all other dropoffs, use zones (city will come from transport section)
            const transportCitySelect = document.querySelector('.transport-city-select');
            const city = transportCitySelect ? transportCitySelect.value : '';
            
            fetch(`{{ route('fetch-zones-by-dmc') }}?city=${encodeURIComponent(city)}`)
                .then(response => response.json())
                .then(data => {
                    if (data.success && data.zones) {
                        dropoffZoneSelect.innerHTML = '<option value="">Select dropoff zone</option>';
                        // Show all zones except the selected pickup zone
                        data.zones.forEach(zone => {
                            if (zone.zone_id !== pickupZoneId) {
                                dropoffZoneSelect.innerHTML += `<option value="${zone.zone_id}">${zone.zone_name} (${zone.zone_type})</option>`;
                            }
                        });
                        dropoffZoneSelect.disabled = false;
                    }
                })
                .catch(error => {
                    console.error('Error fetching dropoff zones:', error);
                });
            }
        } else {
            dropoffZoneSelect.innerHTML = '<option value="">Select pickup zone first</option>';
            dropoffZoneSelect.disabled = true;
        }
        
        // Reset vehicle and service type selects
        const vehicleSelect = document.querySelector(`select[name="day${day}_${section}_vehicle_id"]`);
        const serviceTypeSelect = document.querySelector(`select[name="day${day}_${section}_service_type"]`);
        
        if (vehicleSelect) {
            vehicleSelect.innerHTML = '<option value="">Select zones first</option>';
            vehicleSelect.disabled = true;
        }
        
        if (serviceTypeSelect) {
            // Keep the hardcoded options, just disable and reset selection
            serviceTypeSelect.disabled = true;
            serviceTypeSelect.value = "";
            serviceTypeSelect.disabled = true;
        }
    }

    // New function to handle pickup zone changes with section-specific exclusion
    window.handlePickupZoneChange = function(day, section) {
        console.log(`=== HANDLING PICKUP ZONE CHANGE FOR STATIC ${section.toUpperCase()} ===`);

        // Scope to live services bundle only. In multi-city, frozen segment snapshots can contain
        // duplicate name="dayX_*" fields; document.querySelector would match the wrong (first) one.
        const bundleRoot = document.getElementById('segmentServicesBundle');
        const qs = function (sel) {
            return bundleRoot ? bundleRoot.querySelector(sel) : document.querySelector(sel);
        };
        
        // For transport section, try both static and dynamic patterns
        let pickupZoneSelect, dropoffZoneSelect;
        
        if (section === 'transport') {
            // Only handle static transport (without index) - dynamic transport uses handlePickupZoneChangeForAdditionalTransport
            pickupZoneSelect = qs(`select[name="day${day}_transport_pickup_zone_id"]`);
            dropoffZoneSelect = qs(`select[name="day${day}_transport_dropoff_zone_id"]`);
            
            // Additional safeguard: ensure we're not accidentally targeting dynamic transport elements
            if (pickupZoneSelect && pickupZoneSelect.name.includes('_transport_') && pickupZoneSelect.name.includes('_pickup_zone_id') && !pickupZoneSelect.name.includes('_transport_1_') && !pickupZoneSelect.name.includes('_transport_2_') && !pickupZoneSelect.name.includes('_transport_3_') && !pickupZoneSelect.name.includes('_transport_4_') && !pickupZoneSelect.name.includes('_transport_5_')) {
                console.log('Confirmed: Working with static transport (no index in name)');
            } else if (pickupZoneSelect) {
                console.warn('Warning: Detected dynamic transport element in static handler:', pickupZoneSelect.name);
            }
            
            console.log('Static transport selectors:', {
                pickup: pickupZoneSelect ? pickupZoneSelect.name : 'NOT FOUND',
                dropoff: dropoffZoneSelect ? dropoffZoneSelect.name : 'NOT FOUND'
            });
        } else {
            // For other sections, use the standard pattern
            pickupZoneSelect = qs(`select[name="day${day}_${section}_pickup_zone_id"]`);
            dropoffZoneSelect = qs(`select[name="day${day}_${section}_dropoff_zone_id"]`);
            
            console.log('Other section selectors:', {
                pickup: pickupZoneSelect ? pickupZoneSelect.name : 'NOT FOUND',
                dropoff: dropoffZoneSelect ? dropoffZoneSelect.name : 'NOT FOUND'
            });
        }
        
        if (!pickupZoneSelect || !dropoffZoneSelect) {
            console.error('Static transport elements not found for section:', section);
            return;
        }
        
        const pickupZoneId = pickupZoneSelect.value;
        console.log('Static transport pickup value:', pickupZoneId);
        
        if (pickupZoneId) {
            // Check if this is an entry port dropoff (should show zone-assigned locations, not zones)
            if (section === 'entry' && dropoffZoneSelect.name.includes('_entry_dropoff_zone_id')) {
                // For entry port dropoff, check if it already has static options or needs API data
                const hasStaticOptions = dropoffZoneSelect.querySelectorAll('optgroup').length > 0;
                
                if (hasStaticOptions) {
                    // Already has static options (all hotels from API, attractions, restaurants) - keep them, just enable
                    console.log('Entry port dropoff already has static options, enabling...');
                    
                    // Do NOT replace hotels - list already has all hotels from loadPortsForCity. Just auto-select last added if present.
                    if (typeof selectedHotels !== 'undefined' && Array.isArray(selectedHotels) && selectedHotels.length > 0) {
                        const lastHotel = selectedHotels[selectedHotels.length - 1];
                        const lastHotelId = lastHotel.id || lastHotel.hotel_unique_id;
                        const lastHotelOption = Array.from(dropoffZoneSelect.options).find(opt => {
                            return opt.value === String(lastHotelId) || opt.value === lastHotelId;
                        });
                        if (lastHotelOption) {
                            dropoffZoneSelect.value = lastHotelOption.value;
                            dropoffZoneSelect.dispatchEvent(new Event('change', { bubbles: true }));
                            console.log('Auto-selected last hotel for entry dropoff:', lastHotel.name);
                        }
                    }
                    
                    dropoffZoneSelect.disabled = false;
                    
                    // Update the first option text
                    const firstOption = dropoffZoneSelect.querySelector('option[value=""]');
                    if (firstOption) {
                        firstOption.textContent = 'Select dropoff location';
                    }
                    
                    // Re-evaluate search button state after enabling dropoff
                    enableSearchButton(day, 'entry');
                    
                    // Add event listener to dropoff select to trigger search button update
                    dropoffZoneSelect.addEventListener('change', () => {
                        enableSearchButton(day, 'entry');
                    });
                } else {
                    // No static options, fetch from API
                    console.log('Populating entry port dropoff with zone-assigned locations from API');
                dropoffZoneSelect.innerHTML = '<option value="">Loading locations...</option>';
                
                fetch(`{{ route('fetch-zone-assigned-locations') }}`)
                                    .then(response => response.json())
                    .then(data => {
                        console.log('Zone-assigned locations response:', data);
                        if (data.success && data.locations && Array.isArray(data.locations)) {
                            console.log('Zone-assigned locations fetched:', data.locations.length);
                            dropoffZoneSelect.innerHTML = '<option value="">Select dropoff location</option>';
                            
                            // Add Ports first (use filtered ports from country selection if available, otherwise use static ports)
                            const ports = window.filteredPortsData || @json($ports ?? []);
                            if (ports && ports.length > 0) {
                                const portGroup = document.createElement('optgroup');
                                portGroup.label = 'Ports';
                                
                                ports.forEach(port => {
                                    const option = document.createElement('option');
                                    // Handle both filtered port format (port.id) and static port format (port.port_id)
                                    option.value = port.id || port.port_id;
                                    option.textContent = port.port_name;
                                    option.setAttribute('data-type', 'Port');
                                    option.setAttribute('data-port', JSON.stringify(port));
                                    if (port.port_id) {
                                        option.dataset.portId = port.port_id;
                                    }
                                    portGroup.appendChild(option);
                                });
                                
                                dropoffZoneSelect.appendChild(portGroup);
                                console.log(`Added ${ports.length} ports to dropoff`);
                            }
                            
                            data.locations.forEach(location => {
                                const option = document.createElement('option');
                                option.value = location.id;
                                
                                // Enhanced display format with icons for different types
                                let icon = '';
                                switch(location.type) {
                                    case 'hotel':
                                        icon = '🏨';
                                        break;
                                    case 'restaurant':
                                        icon = '🍽️';
                                        break;
                                    case 'attraction':
                                        icon = '🎯';
                                        break;
                                    default:
                                        icon = '📍';
                                }
                                
                                option.textContent = `${icon} ${location.name} (${location.type}) - ${location.location}`;
                                option.dataset.type = location.type;
                                option.dataset.latitude = location.latitude || '';
                                option.dataset.longitude = location.longitude || '';
                                dropoffZoneSelect.appendChild(option);
                            });
                            
                            dropoffZoneSelect.disabled = false;
                            
                            // Re-evaluate search button state after populating dropoff
                            enableSearchButton(day, 'entry');
                            
                            // Add event listener to dropoff select to trigger search button update
                            dropoffZoneSelect.addEventListener('change', () => {
                                enableSearchButton(day, 'entry');
                            });
                        } else {
                            console.log('No valid locations data received:', data);
                            dropoffZoneSelect.innerHTML = '<option value="">No locations available</option>';
                            dropoffZoneSelect.disabled = true;
                        }
                    })
                    .catch(error => {
                        console.error('Error fetching zone-assigned locations:', error);
                        dropoffZoneSelect.innerHTML = '<option value="">Error loading locations</option>';
                        dropoffZoneSelect.disabled = true;
                    });
            }
            }
            // Check if this is an exit port pickup (should show zone-assigned locations - hotels/attractions/restaurants)
            else if (section === 'exit' && pickupZoneSelect.name.includes('_exit_pickup_zone_id')) {
                // For exit port pickup, check if it already has static options or needs API data
                const hasStaticOptions = pickupZoneSelect.querySelectorAll('optgroup').length > 0;
                
                if (hasStaticOptions) {
                    // Already has static options (hotels, attractions, restaurants), just enable it
                    console.log('Exit port pickup already has static options, enabling...');
                    pickupZoneSelect.disabled = false;
                    
                    // Update the first option text
                    const firstOption = pickupZoneSelect.querySelector('option[value=""]');
                    if (firstOption) {
                        firstOption.textContent = 'Select pickup location';
                    }
                    
                    // Re-evaluate search button state after enabling pickup
                    console.log('Calling enableSearchButton for exit port after pickup selection...');
                    enableSearchButton(day, 'exit');
                    
                    // Debug the current state
                    setTimeout(() => {
                        console.log('=== DEBUG AFTER PICKUP SELECTION ===');
                        if (window.debugExitPortFields) {
                            window.debugExitPortFields();
                        }
                    }, 100);
                } else {
                    // No static options, fetch from API
                    console.log('Populating exit port pickup with zone-assigned locations from API');
                    pickupZoneSelect.innerHTML = '<option value="">Loading locations...</option>';
                    
                    fetch(`{{ route('fetch-zone-assigned-locations') }}`)
                        .then(response => response.json())
                        .then(data => {
                            console.log('Zone-assigned locations response for exit port pickup:', data);
                            if (data.success && data.locations && Array.isArray(data.locations)) {
                                console.log('Zone-assigned locations fetched for exit port pickup:', data.locations.length);
                                pickupZoneSelect.innerHTML = '<option value="">Select pickup location</option>';
                                
                                data.locations.forEach(location => {
                                    const option = document.createElement('option');
                                    option.value = location.id;
                                    
                                    // Enhanced display format with icons for different types
                                    let icon = '';
                                    switch(location.type) {
                                        case 'hotel':
                                            icon = '🏨';
                                            break;
                                        case 'restaurant':
                                            icon = '🍽️';
                                            break;
                                        case 'attraction':
                                            icon = '🎯';
                                            break;
                                        default:
                                            icon = '📍';
                                    }
                                    
                                    option.textContent = `${icon} ${location.name} (${location.type}) - ${location.location}`;
                                    option.dataset.type = location.type;
                                    option.dataset.latitude = location.latitude || '';
                                    option.dataset.longitude = location.longitude || '';
                                    pickupZoneSelect.appendChild(option);
                                });
                                
                                pickupZoneSelect.disabled = false;
                                
                                // Re-evaluate search button state after populating pickup
                                enableSearchButton(day, 'exit');
                } else {
                                console.log('No valid locations data received for exit port pickup:', data);
                                pickupZoneSelect.innerHTML = '<option value="">No locations available</option>';
                                pickupZoneSelect.disabled = true;
                            }
                        })
                        .catch(error => {
                            console.error('Error fetching zone-assigned locations for exit port pickup:', error);
                            pickupZoneSelect.innerHTML = '<option value="">Error loading locations</option>';
                            pickupZoneSelect.disabled = true;
                    });
                }
            } else if (section === 'transport') {
                // For local transfer dropoff, populate with zone-assigned locations (excluding pickup location)
                console.log('Populating local transfer dropoff with zone-assigned locations (excluding pickup)');
                console.log('Dropoff select name:', dropoffZoneSelect.name);
                console.log('Pickup zone ID:', pickupZoneId);
                
                // Check if pickup value is a location ID (numeric) or zone ID
                const isLocationId = /^\d+$/.test(pickupZoneId);
                console.log('Pickup value type:', isLocationId ? 'Location ID' : 'Zone ID');
                
                // Preserve existing dropoff selection before repopulating
                const existingDropoffValue = dropoffZoneSelect.value;
                const existingDropoffText = dropoffZoneSelect.options[dropoffZoneSelect.selectedIndex]?.textContent || '';
                console.log('Preserving existing dropoff selection:', existingDropoffValue, existingDropoffText);
                
                dropoffZoneSelect.innerHTML = '<option value="">Loading locations...</option>';
                
                fetch(`{{ route('fetch-zone-assigned-locations') }}`)
                    .then(response => response.json())
                    .then(data => {
                        console.log('Zone-assigned locations response for local transfer:', data);
                        if (data.success && data.locations && Array.isArray(data.locations)) {
                            console.log('Zone-assigned locations fetched for local transfer:', data.locations.length);
                            dropoffZoneSelect.innerHTML = '<option value="">Select dropoff location</option>';
                            
                            data.locations.forEach(location => {
                                // Skip the currently selected pickup location
                                console.log(`Comparing location.id: ${location.id} (${typeof location.id}) with pickupZoneId: ${pickupZoneId} (${typeof pickupZoneId})`);
                                if (location.id == pickupZoneId) {
                                    console.log(`Skipping pickup location in local transfer dropoff list: ${location.name}`);
                                    return;
                                }
                                
                                const option = document.createElement('option');
                                option.value = location.id;
                                
                                // Enhanced display format with icons for different types
                                let icon = '';
                                switch(location.type) {
                                    case 'hotel':
                                        icon = '🏨';
                                        break;
                                    case 'restaurant':
                                        icon = '🍽️';
                                        break;
                                    case 'attraction':
                                        icon = '🎯';
                                        break;
                                    default:
                                        icon = '📍';
                                }
                                
                                option.textContent = `${icon} ${location.name} (${location.type}) - ${location.location}`;
                                option.dataset.type = location.type;
                                option.dataset.latitude = location.latitude || '';
                                option.dataset.longitude = location.longitude || '';
                                dropoffZoneSelect.appendChild(option);
                            });
                            
                            // Restore the previously selected dropoff value if it still exists and is not the pickup location
                            if (existingDropoffValue && existingDropoffValue !== pickupZoneId) {
                                const optionToRestore = dropoffZoneSelect.querySelector(`option[value="${existingDropoffValue}"]`);
                                if (optionToRestore) {
                                    dropoffZoneSelect.value = existingDropoffValue;
                                    console.log('Restored previous dropoff selection:', existingDropoffValue);
                                } else {
                                    console.log('Previous dropoff selection no longer available, keeping default');
                                }
                            }
                            
                            dropoffZoneSelect.disabled = false;
                        } else {
                            console.log('No valid locations data received for local transfer:', data);
                            dropoffZoneSelect.innerHTML = '<option value="">No locations available</option>';
                            dropoffZoneSelect.disabled = true;
                        }
                    })
                    .catch(error => {
                        console.error('Error fetching zone-assigned locations for local transfer:', error);
                        dropoffZoneSelect.innerHTML = '<option value="">Error loading locations</option>';
                        dropoffZoneSelect.disabled = true;
                    });
                
                // Ensure dropoff select is enabled for transport sections
                setTimeout(() => {
                    if (dropoffZoneSelect.disabled) {
                        console.log('Force enabling dropoff select for transport section');
                        dropoffZoneSelect.disabled = false;
                    }
                    
                    // Re-evaluate search button state after pickup zone change
                    enableSearchButton(day, 'transport');
                    
                    // Populate pickup coordinates for static transport
                    if (pickupZoneSelect.value && pickupZoneSelect.selectedIndex > 0) {
                        const selectedOption = pickupZoneSelect.options[pickupZoneSelect.selectedIndex];
                        const latField = document.getElementById(`day${day}_transport_pickup_lat`);
                        const lngField = document.getElementById(`day${day}_transport_pickup_lng`);
                        if (latField && lngField && selectedOption.dataset.latitude && selectedOption.dataset.longitude) {
                            latField.value = selectedOption.dataset.latitude;
                            lngField.value = selectedOption.dataset.longitude;
                            console.log(`Set pickup coordinates for static transport:`, latField.value, lngField.value);
                        }
                    }
                }, 100);
            } else {
                // For all other dropoffs, use zones
            console.log('Falling back to zones logic for section:', section);
            console.log('Dropoff select name:', dropoffZoneSelect.name);
            const allZones = window.allZonesData || [];
            console.log('Using stored zones data:', allZones.length, 'zones');
            console.log('Zones to exclude:', pickupZoneId);
            
            // Update dropoff select with all zones except the selected pickup zone
            dropoffZoneSelect.innerHTML = '<option value="">Select dropoff zone</option>';
            allZones.forEach(zone => {
                if (zone.zone_id != pickupZoneId) {
                    dropoffZoneSelect.innerHTML += `<option value="${zone.zone_id}">${zone.zone_name} (${zone.zone_type})</option>`;
                }
            });
            }
            
            dropoffZoneSelect.disabled = false;
            console.log('Dropoff select enabled for section:', section);
            
            // Add event listener for dropoff zone change to populate coordinates
            if (section === 'transport') {
                dropoffZoneSelect.addEventListener('change', function() {
                    if (this.value && this.selectedIndex > 0) {
                        const selectedOption = this.options[this.selectedIndex];
                        const latField = document.getElementById(`day${day}_transport_dropoff_lat`);
                        const lngField = document.getElementById(`day${day}_transport_dropoff_lng`);
                        if (latField && lngField && selectedOption.dataset.latitude && selectedOption.dataset.longitude) {
                            latField.value = selectedOption.dataset.latitude;
                            lngField.value = selectedOption.dataset.longitude;
                            console.log(`Set dropoff coordinates for static transport:`, latField.value, lngField.value);
                        }
                    }
                });
            }
            
            // Re-evaluate search button state after pickup zone change
            enableSearchButton(day, section);
        } else {
            // Pickup zone is empty - disable dropoff but handle differently based on section
            if (section === 'exit') {
                // For exit port, dropoff contains ports which don't depend on pickup
                // Just disable it and update the placeholder, but keep the port options
                const firstOption = dropoffZoneSelect.querySelector('option[value=""]');
                if (firstOption) {
                    firstOption.textContent = 'Select pickup location first';
                }
                dropoffZoneSelect.disabled = true;
                // Clear selection but preserve options
                dropoffZoneSelect.value = '';
                console.log('Exit port: Disabled dropoff but preserved port options');
            } else {
                // For other sections, clear the options as they depend on pickup
                dropoffZoneSelect.innerHTML = '<option value="">Select pickup zone first</option>';
                dropoffZoneSelect.disabled = true;
            }
        }
        
        // Reset vehicle and service type selects only for non-transport sections
        // For transport sections (local transfer), preserve the existing vehicle and service type data
        if (section !== 'transport') {
            const vehicleSelect = document.querySelector(`select[name="day${day}_${section}_vehicle_id"]`);
            const serviceTypeSelect = document.querySelector(`select[name="day${day}_${section}_service_type"]`);
            
            if (vehicleSelect) {
                vehicleSelect.innerHTML = '<option value="">Select zones first</option>';
                vehicleSelect.disabled = true;
            }
            
            if (serviceTypeSelect) {
                // Keep the hardcoded options, just disable and reset selection
                serviceTypeSelect.disabled = true;
                serviceTypeSelect.value = "";
                serviceTypeSelect.disabled = true;
            }
        }
        
        // Reset search button and hide vehicle results only for non-transport sections
        // For transport sections (local transfer), preserve the existing state
        if (section !== 'transport') {
            const searchBtn = document.getElementById(`day${day}_${section}_search_btn`);
            const vehicleResultsDiv = document.getElementById(`day${day}_${section}_vehicle_results`);
            
            if (searchBtn) {
                searchBtn.disabled = true;
                searchBtn.classList.remove('btn-primary');
                searchBtn.classList.add('btn-secondary');
            }
            if (vehicleResultsDiv) {
                vehicleResultsDiv.style.display = 'none';
            }
            
            // Check if search button should be enabled after zone selection
            setTimeout(() => enableSearchButton(day, section), 100);
        }
    }

    function loadVehiclesForZones(day, section) {
        const pickupZoneSelect = document.querySelector(`select[name="day${day}_${section}_pickup_zone_id"]`);
        const dropoffZoneSelect = document.querySelector(`select[name="day${day}_${section}_dropoff_zone_id"]`);
        const vehicleSelect = document.querySelector(`select[name="day${day}_${section}_vehicle_id"]`);
        
        if (!pickupZoneSelect || !dropoffZoneSelect || !vehicleSelect) return;
        
        const fromZoneId = pickupZoneSelect.value;
        const toZoneId = dropoffZoneSelect.value;
        
        if (fromZoneId && toZoneId) {
            vehicleSelect.innerHTML = '<option value="">Loading vehicles...</option>';
            vehicleSelect.disabled = true;
            
            fetch(`{{ url(route('fetch-vehicles-by-zones')) }}`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').getAttribute('content')
                },
                body: JSON.stringify({
                    from_zone_id: fromZoneId,
                    to_zone_id: toZoneId
                })
            })
                .then(response => response.json())
                .then(data => {
                    // Store dropoff zone vehicle_type for UI restrictions (Shared/Private/Both)
                    try {
                        const zvt = String(data.zone_vehicle_type || '').trim();
                        window.zoneVehicleTypeBySection = window.zoneVehicleTypeBySection || {};
                        window.zoneVehicleTypeBySection[`${day}_${section}`] = zvt;
                        // Also store common transport variants
                        if (section === 'transport') {
                            window.zoneVehicleTypeBySection[`${day}_transport_0`] = zvt;
                            window.zoneVehicleTypeBySection[`${day}_transport`] = zvt;
                        }
                    } catch (e) {
                        console.warn('Failed to store zone_vehicle_type for UI (loadVehiclesForZones)', e);
                    }

                    if (data.success && data.vehicles && data.vehicles.length > 0) {
                        vehicleSelect.innerHTML = '<option value="">Select vehicle</option>';
                        
                        data.vehicles.forEach(vehicle => {
                            const entryOrExitMaxPax = ((section === 'entry' || section === 'exit') && (vehicle.city_tour_seating_capacity != null && vehicle.city_tour_seating_capacity !== '')) ? vehicle.city_tour_seating_capacity : vehicle.seating_capacity;
                            const vehicleInfo = `${vehicle.vehicle_name} (${vehicle.vehicle_type}) - ${vehicle.seating_capacity} seats`;
                            
                            // Debug logging for vehicle data
                            console.log('=== VEHICLE DATA DEBUG ===');
                            console.log('Vehicle:', vehicle);
                            console.log('Private price:', vehicle.private_price);
                            console.log('Shared price:', vehicle.shared_price);
                            
                            vehicleSelect.innerHTML += `<option value="${vehicle.vehicle_id}" 
                                data-private-price="${vehicle.private_price}" 
                                data-shared-price="${vehicle.shared_price}"
                                data-service-type="${vehicle.service_type}"
                                data-mapping-id="${vehicle.mapping_id}"
                                data-seatingCapacity="${entryOrExitMaxPax}" data-sharable="${vehicle.sharable}"
                                data-image="${vehicle.image || ''}">
                                ${vehicleInfo}
                            </option>`;
                        });
                        
                        vehicleSelect.disabled = false;
                        
                        // Reset service type select and price display when vehicles are loaded
                        updateVehicleDetails(day, section);
                    } else {
                        vehicleSelect.innerHTML = '<option value="">No vehicles available for this route</option>';
                        vehicleSelect.disabled = true;
                        
                        // Reset service type select and price display when no vehicles
                        updateVehicleDetails(day, section);
                    }
                })
                .catch(error => {
                    console.error('Error fetching vehicles:', error);
                    vehicleSelect.innerHTML = '<option value="">Error loading vehicles</option>';
                    vehicleSelect.disabled = true;
                });
        } else {
            vehicleSelect.innerHTML = '<option value="">Select zones first</option>';
            vehicleSelect.disabled = true;
        }
        
        // Reset service type select
        const serviceTypeSelect = document.querySelector(`select[name="day${day}_${section}_service_type"]`);
        if (serviceTypeSelect) {
            // Keep the hardcoded options, just disable and reset selection
            serviceTypeSelect.disabled = true;
            serviceTypeSelect.value = "";
            serviceTypeSelect.disabled = true;
        }
    }

        window.updateVehicleDetails = function(day, section) {
        console.log(`updateVehicleDetails called with day: ${day}, section: ${section}`);
        
        // Handle dynamic transport sections with index
        let vehicleSelect, serviceTypeSelect, priceDisplay;
        
        if (section.startsWith('transport_')) {
            // For dynamic transport sections like 'transport_2'
            const transportIndex = section.split('_')[1];
            vehicleSelect = document.querySelector(`select[name="day${day}_transport_${transportIndex}_vehicle_id"]`);
            serviceTypeSelect = document.querySelector(`select[name="day${day}_transport_${transportIndex}_service_type"]`);
            priceDisplay = document.getElementById(`day${day}_transport_${transportIndex}_price_display`);
        } else {
            // For other sections (entry, exit, transport)
            vehicleSelect = document.getElementById(`day${day}_${section}_vehicle_id`);
            serviceTypeSelect = document.getElementById(`day${day}_${section}_service_type`);
            priceDisplay = document.getElementById(`day${day}_${section}_price_display`);
        }
        
        console.log(`Looking for vehicle select: day${day}_${section}_vehicle_id`, vehicleSelect ? 'FOUND' : 'NOT FOUND');
        
        if (!vehicleSelect) { 
            console.log(`Vehicle select not found for day${day}_${section}_vehicle_id`);
            console.log(`Available elements with similar names:`, document.querySelectorAll(`[id*="${section}_vehicle_id"]`));
            return;
        }
        
        const selectedOption = vehicleSelect.options[vehicleSelect.selectedIndex];
        
        console.log('Elements found:', {
            vehicleSelect: !!vehicleSelect,
            selectedOption: !!selectedOption,
            serviceTypeSelect: !!serviceTypeSelect,
            priceDisplay: !!priceDisplay
        });
        
        if (selectedOption.value) {
            // Check if point-to-point service type is selected
            let pointToPointRadio, priceField;
            
            if (section.startsWith('transport_')) {
                // For dynamic transport sections
                const transportIndex = section.split('_')[1];
                pointToPointRadio = document.querySelector(`input[name="day${day}_transport_${transportIndex}_service_type"][value="point_to_point"]`);
                priceField = document.getElementById(`day${day}_transport_${transportIndex}_price_field`);
            } else if (section === 'transport') {
                // For static transport section
                pointToPointRadio = document.querySelector(`input[name="day${day}_transport_service_type"][value="point_to_point"]`);
                priceField = document.getElementById(`day${day}_transport_price_field`);
            }
            
            if (pointToPointRadio && pointToPointRadio.checked) {
                // Show custom price field for point-to-point
                if (priceField) {
                    priceField.style.display = 'block';
                    console.log(`Showing price field for day ${day} transport ${section}`);
                }
            }
            
            // Show price display section with initial message
            if (priceDisplay) {
                priceDisplay.style.display = 'block';
                priceDisplay.innerHTML = `
                    <div class="d-flex align-items-center">
                        <i class="ri-money-dollar-circle-line me-2 fs-4"></i>
                        <div>
                            <strong>Price Information</strong>
                            <div class="small text-muted">Select a service type to see pricing details</div>
                        </div>
                    </div>
                `;
            }
            
            // Arrival (entry) / Departure (exit) section: set Number of Passengers max from vehicle city_tour_seating_capacity
            const isEntryOrExitSection = (section === 'entry_0' || (typeof section === 'string' && section.startsWith('entry_'))) || (section === 'exit_0' || (typeof section === 'string' && section.startsWith('exit_')));
            if (isEntryOrExitSection) {
                const passengerInput = document.getElementById(`day${day}_${section}_passengers`);
                const maxPaxSpan = document.getElementById(`day${day}_${section}_max_pax`);
                const maxPax = parseInt(selectedOption.dataset.seatingcapacity || selectedOption.getAttribute('data-seatingCapacity') || '50', 10) || 50;
                if (passengerInput) {
                    passengerInput.setAttribute('max', maxPax);
                    if (parseInt(passengerInput.value, 10) > maxPax) passengerInput.value = maxPax;
                }
                if (maxPaxSpan) maxPaxSpan.textContent = maxPax;
            }
            
            // Reset service type selection to trigger pricing update
        } else {
            // Reset to default state
            
            // Hide custom price field
            const priceField = document.getElementById(`day${day}_transport_price_field`);
            if (priceField) {
                priceField.style.display = 'none';
                console.log(`Hiding price field for day ${day} transport`);
            }
            
            // Hide price display
            if (priceDisplay) {
                priceDisplay.style.display = 'none';
            }
            
            // Arrival (entry) / Departure (exit) section: reset max pax display when no vehicle selected
            const isEntryOrExitSectionReset = (section === 'entry_0' || (typeof section === 'string' && section.startsWith('entry_'))) || (section === 'exit_0' || (typeof section === 'string' && section.startsWith('exit_')));
            if (isEntryOrExitSectionReset) {
                const passengerInput = document.getElementById(`day${day}_${section}_passengers`);
                const maxPaxSpan = document.getElementById(`day${day}_${section}_max_pax`);
                if (passengerInput) passengerInput.setAttribute('max', '50');
                if (maxPaxSpan) maxPaxSpan.textContent = '—';
            }
        }
    }
        window.updateTypeSelect = function(event,day, section){
            const vehicleSelect = event.target;
            const selectedOption = vehicleSelect.options[vehicleSelect.selectedIndex];
            
            // Close Select2 dropdown if it's initialized on the vehicle select
            if (typeof jQuery !== 'undefined' && jQuery(vehicleSelect).data('select2')) {
                jQuery(vehicleSelect).select2('close');
            }
            
            // Find service type select - handle both static and dynamic transport fields
            let serviceTypeSelect;
            if (section.startsWith('transport_')) {
                // Dynamic transport field (e.g., transport_2, transport_3)
                const transportIndex = section.split('_')[1];
                serviceTypeSelect = document.getElementById(`day${day}_transport_${transportIndex}_service_type_select`) ||
                                document.querySelector(`select[name="day${day}_transport_${transportIndex}_service_type"]`);
            } else {
                // Static transport field or other sections
                serviceTypeSelect = document.getElementById(`day${day}_${section}_service_type`) ||
                                document.querySelector(`select[name="day${day}_${section}_service_type"]`);
            }
            
            // If service type select not found, return early to prevent errors
            if (!serviceTypeSelect) {
                console.warn(`Service type select not found for day ${day}, section ${section}`);
                return;
            }
            
            // Check if hourly or point-to-point radio button is selected
            // Handle both static and dynamic transport fields
            let hourlyRadio, pointToPointRadio;
            if (section.startsWith('transport_')) {
                // Dynamic transport field
                const transportIndex = section.split('_')[1];
                hourlyRadio = document.querySelector(`input[name="day${day}_transport_${transportIndex}_service_type"][value="hourly"]`);
                pointToPointRadio = document.querySelector(`input[name="day${day}_transport_${transportIndex}_service_type"][value="point_to_point"]`);
            } else if (section === 'transport') {
                // Static transport field
                hourlyRadio = document.querySelector(`input[name="day${day}_transport_service_type"][value="hourly"]`);
                pointToPointRadio = document.querySelector(`input[name="day${day}_transport_service_type"][value="point_to_point"]`);
            }
            
            serviceTypeSelect.innerHTML = '<option value="">Select service type</option>';

            // If hourly or point-to-point is selected, only show Private option
            if ((hourlyRadio && hourlyRadio.checked)) {
                console.log('Hourly radio button is selected');
                const privateOption = document.createElement('option');
                privateOption.value = 'Private';
                privateOption.textContent = 'Private';
                serviceTypeSelect.appendChild(privateOption);
                serviceTypeSelect.disabled = false; // Keep it enabled for hourly
                serviceTypeSelect.style.backgroundColor = '';
                serviceTypeSelect.style.cursor = '';
            }
            else if ((pointToPointRadio && pointToPointRadio.checked)) {
                console.log('Point-to-point radio button is selected');
                const privateOption = document.createElement('option');
                privateOption.value = 'Private';
                privateOption.textContent = 'Private';
                serviceTypeSelect.appendChild(privateOption);
                serviceTypeSelect.value = 'Private';
                serviceTypeSelect.disabled = true; // Make it readonly
                serviceTypeSelect.style.backgroundColor = '#f8f9fa';
                serviceTypeSelect.style.cursor = 'not-allowed';
            } else {
                // For local transfer, entry, and exit ports, show options based on vehicle sharable property
                // sharable: 1 = Private only, 2 = Shared only, 3 = Both Private and Shared
                const sharable = selectedOption ? parseInt(selectedOption.dataset.sharable) : null;
                console.log('Vehicle sharable value:', sharable, 'for section:', section);
                
                if (sharable === 1 || sharable === 3) {
                    // Show Private option (for sharable = 1 or 3)
                    const privateOption = document.createElement('option');
                    privateOption.value = 'Private';
                    privateOption.textContent = 'Private';
                    serviceTypeSelect.appendChild(privateOption);
                    console.log('Added Private option (sharable =', sharable, ')');
                }
                
                if (sharable === 2 || sharable === 3) {
                    // Show Shared option (for sharable = 2 or 3)
                    const sharedOption = document.createElement('option');
                    sharedOption.value = 'Shared';
                    sharedOption.textContent = 'Shared';
                    serviceTypeSelect.appendChild(sharedOption);
                    console.log('Added Shared option (sharable =', sharable, ')');
                }
                
                // If sharable is not 1, 2, or 3, show both options as fallback
                if (sharable !== 1 && sharable !== 2 && sharable !== 3) {
                    console.log('Sharable value not recognized (', sharable, '), showing both options as fallback');
                    const privateOption = document.createElement('option');
                    privateOption.value = 'Private';
                    privateOption.textContent = 'Private';
                    serviceTypeSelect.appendChild(privateOption);

                    const sharedOption = document.createElement('option');
                    sharedOption.value = 'Shared';
                    sharedOption.textContent = 'Shared';
                    serviceTypeSelect.appendChild(sharedOption);
                }

                // Extra rule: lock Service Type options based on dropoff zone vehicle_type (Shared/Private/Both)
                // This must apply even when vehicle.sharable = 3 (Both).
                try {
                    const baseSection =
                        (typeof section === 'string' && section.startsWith('entry')) ? 'entry' :
                        (typeof section === 'string' && section.startsWith('exit')) ? 'exit' :
                        section;

                    const zoneKeyCandidates = [
                        `${day}_${section}`,
                        `${day}_${baseSection}`,
                    ];

                    const zoneMap = window.zoneVehicleTypeBySection || {};
                    let zoneVehicleType = '';
                    for (const k of zoneKeyCandidates) {
                        if (typeof zoneMap[k] === 'string' && zoneMap[k].trim() !== '') {
                            zoneVehicleType = zoneMap[k].trim();
                            break;
                        }
                    }

                    if (zoneVehicleType === 'Shared' || zoneVehicleType === 'Private') {
                        const privateOpt = Array.from(serviceTypeSelect.options).find(o => o.value === 'Private');
                        const sharedOpt = Array.from(serviceTypeSelect.options).find(o => o.value === 'Shared');

                        // reset
                        if (privateOpt) privateOpt.disabled = false;
                        if (sharedOpt) sharedOpt.disabled = false;

                        if (zoneVehicleType === 'Shared' && privateOpt) {
                            privateOpt.disabled = true;
                            if (sharedOpt) serviceTypeSelect.value = 'Shared';
                        } else if (zoneVehicleType === 'Private' && sharedOpt) {
                            sharedOpt.disabled = true;
                            if (privateOpt) serviceTypeSelect.value = 'Private';
                        }

                        // trigger pricing refresh
                        serviceTypeSelect.dispatchEvent(new Event('change', { bubbles: true }));
                    }
                } catch (e) {
                    console.warn('Failed to apply zone vehicle type UI lock', e);
                }
                
                serviceTypeSelect.disabled = false;
                serviceTypeSelect.style.backgroundColor = '';
                serviceTypeSelect.style.cursor = '';
            }
            
            // Reinitialize Select2 on service type select if it was initialized
            if (typeof jQuery !== 'undefined' && jQuery(serviceTypeSelect).data('select2')) {
                jQuery(serviceTypeSelect).select2('destroy');
                jQuery(serviceTypeSelect).select2({
                    placeholder: "Select service type",
                    allowClear: true,
                    width: '100%'
                });
            }
    }

        window.updatePricing = function(day, section) {

