                    // Get vehicle name from option text
                    let vehicleName = selectedOption.textContent || '';
                    // Extract vehicle name from text (format: "Vehicle Name (Type) - X seats")
                    // Take everything before the first '(' if it exists
                    if (vehicleName && vehicleName.includes('(')) {
                        vehicleName = vehicleName.split('(')[0].trim();
                    }
                    // Clean up the text
                    vehicleName = vehicleName.trim();
                    if (vehicleName && vehicleName !== 'Choose vehicle' && vehicleName !== 'Select Vehicle' && vehicleName !== 'Choose your vehicle' && !vehicleNames.includes(vehicleName)) {
                        vehicleNames.push(vehicleName);
                    }
                }
            }
            
            if (totalPriceField) {
                const price = parseFloat(totalPriceField.value) || 0;
                totalDeparturePrice += price;
            }
        });
        
        // Update departure header
        const departureVehicleNameEl = document.getElementById(`day${day}_departure_vehicle_name`);
        const departureTotalPriceEl = document.getElementById(`day${day}_departure_total_price`);
        
        if (departureVehicleNameEl) {
            if (vehicleNames.length > 0) {
                departureVehicleNameEl.textContent = vehicleNames.length === 1 ? vehicleNames[0] : `${vehicleNames.length} vehicles selected`;
                departureVehicleNameEl.style.color = '#3b82f6';
            } else {
                departureVehicleNameEl.textContent = 'No vehicle selected';
                departureVehicleNameEl.style.color = '#6c757d';
            }
        }
        
        if (departureTotalPriceEl) {
            departureTotalPriceEl.textContent = `SGD ${totalDeparturePrice.toFixed(2)}`;
        }
    }

    // Update other transport section header with vehicle name and total price
    window.updateOtherTransportHeader = function(day) {
        let totalTransportPrice = 0;
        let vehicleNames = [];
        
        // Check for main transport vehicle (transport_0 or just transport)
        const mainVehicleSelect = document.getElementById(`day${day}_transport_vehicle_id`);
        const mainTotalPrice = document.getElementById(`day${day}_transport_total_price`);
        
        if (mainVehicleSelect && mainVehicleSelect.value) {
            const selectedOption = mainVehicleSelect.options[mainVehicleSelect.selectedIndex];
            if (selectedOption && selectedOption.value) {
                let vehicleName = selectedOption.textContent || '';
                if (vehicleName && vehicleName.includes('(')) {
                    vehicleName = vehicleName.split('(')[0].trim();
                }
                vehicleName = vehicleName.trim();
                if (vehicleName && vehicleName !== 'Choose vehicle' && vehicleName !== 'Select Vehicle' && vehicleName !== 'Choose your vehicle' && !vehicleNames.includes(vehicleName)) {
                    vehicleNames.push(vehicleName);
                }
                // Only count main transport price when a vehicle is selected (avoid stale hidden totals).
                if (mainTotalPrice) {
                    const price = parseFloat(mainTotalPrice.value) || 0;
                    totalTransportPrice += price;
                }
            }
        }
        
        // Check for additional transport items (transport_1, transport_2, etc.)
        const transportsContainer = document.getElementById(`day${day}_transports_container`);
        if (transportsContainer) {
            const transportItems = transportsContainer.querySelectorAll('.transport-item');
            transportItems.forEach((item) => {
                const transportIndex = item.getAttribute('data-transport-index');
                if (transportIndex) {
                    const vehicleSelect = item.querySelector(`select[name="day${day}_transport_${transportIndex}_vehicle_id"]`);
                    const totalPriceField = item.querySelector(`input[id="day${day}_transport_${transportIndex}_total_price"]`);
                    
                    if (vehicleSelect && vehicleSelect.value) {
                        const selectedOption = vehicleSelect.options[vehicleSelect.selectedIndex];
                        if (selectedOption && selectedOption.value) {
                            let vehicleName = selectedOption.textContent || '';
                            if (vehicleName && vehicleName.includes('(')) {
                                vehicleName = vehicleName.split('(')[0].trim();
                            }
                            vehicleName = vehicleName.trim();
                            if (vehicleName && vehicleName !== 'Choose vehicle' && vehicleName !== 'Select Vehicle' && vehicleName !== 'Choose your vehicle' && !vehicleNames.includes(vehicleName)) {
                                vehicleNames.push(vehicleName);
                            }
                        }
                    }
                    
                    if (totalPriceField) {
                        const price = parseFloat(totalPriceField.value) || 0;
                        totalTransportPrice += price;
                    }
                }
            });
        }
        
        // Update other transport header
        const otherTransportVehicleNameEl = document.getElementById(`day${day}_other_transport_vehicle_name`);
        const otherTransportTotalPriceEl = document.getElementById(`day${day}_other_transport_total_price`);
        
        if (otherTransportVehicleNameEl) {
            if (vehicleNames.length > 0) {
                otherTransportVehicleNameEl.textContent = vehicleNames.length === 1 ? vehicleNames[0] : `${vehicleNames.length} vehicles selected`;
                otherTransportVehicleNameEl.style.color = '#14b8a6';
            } else {
                otherTransportVehicleNameEl.textContent = 'No vehicle selected';
                otherTransportVehicleNameEl.style.color = '#6c757d';
            }
        }
        
        if (otherTransportTotalPriceEl) {
            otherTransportTotalPriceEl.textContent = `SGD ${totalTransportPrice.toFixed(2)}`;
        }
    }

    // Update exit port custom pricing function (Zone = 0)
    window.updateExitPortCustomPricing = function(day, section) {
        console.log('Updating exit port custom pricing for day', day, 'section', section);
        
        // Get the custom price input field
        const customPriceInput = document.getElementById(`day${day}_${section}_custom_price`);
        const priceDisplay = document.getElementById(`day${day}_${section}_price_display`);
        
        if (!customPriceInput || !priceDisplay) {
            console.error('Custom price input or price display not found for exit port', section);
            return;
        }
        
        const customPrice = parseFloat(customPriceInput.value) || 0;
        
        if (customPrice > 0) {
            // Get guest count for display
            const adults = parseInt(document.getElementById('adults')?.value) || 0;
            const children = parseInt(document.getElementById('children')?.value) || 0;
            const totalGuests = adults + children;
            
            // Update price display with custom price
            priceDisplay.style.display = 'block';
            priceDisplay.innerHTML = `
                <div class="d-flex align-items-center">
                    <i class="ri-money-dollar-circle-line me-2 fs-4"></i>
                    <div>
                        <strong>Exit Port Custom Pricing</strong>
                        <div class="small">
                            <strong>Custom Price:</strong> <span class="text-success fw-bold">SGD ${customPrice.toFixed(2)}</span><br>
                            <strong>Service Type:</strong> Private<br>
                            <strong>Total Guests:</strong> ${totalGuests} (${adults} adults, ${children} children)<br>
                            <small class="text-info">Fixed price for exit port service in zone 0 mode.</small>
                        </div>
                    </div>
                </div>
            `;
            
            // Store pricing data in hidden fields
            const basePriceField = document.getElementById(`day${day}_${section}_base_price`);
            const totalPriceField = document.getElementById(`day${day}_${section}_total_price`);
            const guestCountField = document.getElementById(`day${day}_${section}_guest_count`);
            
            if (basePriceField) basePriceField.value = customPrice.toFixed(2);
            if (totalPriceField) totalPriceField.value = customPrice.toFixed(2);
            if (guestCountField) guestCountField.value = totalGuests;
            
            console.log(`Exit port custom pricing updated for day ${day}, section ${section}: SGD ${customPrice.toFixed(2)}`);
            
            // Update departure header after custom pricing change
            if (section.startsWith('exit')) {
                updateDepartureHeader(day);
            }
            
        } else {
            // Hide price display if no custom price
            priceDisplay.style.display = 'none';
            // Clear hidden fields
            const basePriceField = document.getElementById(`day${day}_${section}_base_price`);
            const totalPriceField = document.getElementById(`day${day}_${section}_total_price`);
            const guestCountField = document.getElementById(`day${day}_${section}_guest_count`);
            
            if (basePriceField) basePriceField.value = '0';
            if (totalPriceField) totalPriceField.value = '0';
            if (guestCountField) guestCountField.value = '0';
            
            // Update departure header after custom pricing change
            if (section.startsWith('exit')) {
                updateDepartureHeader(day);
            }
        }
    }

    // Save service data to the backend
    window.saveService = function(day, type) {
        // Get tour ID
        const tourId = window.currentTourId;
        if (!tourId) {
            showNotification('Tour ID not found. Please create a tour first.', 'error');
            return;
        }
        
        // Get agent ID
        const agentId = document.getElementById('agent_id').value;
        if (!agentId) {
            showNotification('Agent ID not found.', 'error');
            return;
        }
        
        // For entry_port, use the same format as edit.blade.php
        if (type === 'entry_port') {
            // Get customer info
            const customer_info = getCustomerInfo();
            
            // Get form data
            const pickupZoneId = document.querySelector(`select[name="day${day}_entry_pickup_zone_id"]`).value;
            const dropoffZoneId = document.querySelector(`select[name="day${day}_entry_dropoff_zone_id"]`).value;
            const pickupTime = document.querySelector(`[name="day${day}_entry_pickup_time"]`)?.value || '';
            const pickupDate = document.querySelector(`input[name="day${day}_entry_pickup_date"]`).value;
            const vehicleId = document.querySelector(`select[name="day${day}_entry_vehicle_id"]`).value;
            const serviceType = document.querySelector(`select[name="day${day}_entry_service_type"]`).value;
            const passengers = document.getElementById(`day${day}_entry_passengers`).value;
            
            // Validate required fields
            if (!pickupZoneId || !dropoffZoneId || !pickupTime || !pickupDate || !vehicleId || !serviceType || !passengers) {
                showNotification('Please fill in all required fields for entry port service.', 'error');
                return;
            }
            
            // Get pickup and dropoff location names
            const pickupZoneSelect = document.querySelector(`select[name="day${day}_entry_pickup_zone_id"]`);
            const dropoffZoneSelect = document.querySelector(`select[name="day${day}_entry_dropoff_zone_id"]`);
            const pickupZoneName = pickupZoneSelect.options[pickupZoneSelect.selectedIndex]?.text || '';
            const dropoffZoneName = dropoffZoneSelect.options[dropoffZoneSelect.selectedIndex]?.text || '';
            
            // Get selected vehicle details
            const vehicleSelect = document.querySelector(`select[name="day${day}_entry_vehicle_id"]`);
            const selectedOption = vehicleSelect.options[vehicleSelect.selectedIndex];
            let vehicleData = {};
            if (selectedOption) {
                vehicleData = {
                    image: selectedOption.dataset.image || "",
                    dmc_id: selectedOption.dataset.dmcId || "",
                    vehicle_name: selectedOption.dataset.vehicleName || selectedOption.text,
                    vehicle_type: selectedOption.dataset.vehicleType || "",
                    vehicle_model: selectedOption.dataset.vehicleModel || "",
                    model_year: selectedOption.dataset.modelYear || null,
                    seating_capacity: selectedOption.dataset.seatingcapacity || 0,
                    city: "Singapore", // Default city
                    country: "Singapore" // Default country
                };
            }
            
            // Get pricing data
            const totalPrice = document.getElementById(`day${day}_entry_total_price`).value || '0';
            
            // Build transport data in the same format as edit.blade.php
            const transportData = {
                fullName: customer_info.fullName,
                email: customer_info.email,
                phone: customer_info.phone,
                countryCode: customer_info.countryCode,
                address1: customer_info.address1,
                address2: customer_info.address2,
                state: customer_info.state,
                zip: customer_info.zip,
                specialRequests: customer_info.specialRequests,
                vehicles_id: vehicleId,
                image: vehicleData.image,
                dmc_id: vehicleData.dmc_id,
                vehicles_name: vehicleData.vehicle_name,
                Mode: "dmc",
                type: serviceType,
                entrypickup: pickupZoneName,
                entrydropoff: dropoffZoneName,
                bookingDate: pickupDate,
                pickupdate: pickupDate,
                entrytime: pickupTime,
                PickupPlaceid: pickupZoneId,
                DropoffPlaceid: dropoffZoneId,
                adults: parseInt(passengers),
                children: 0,
                totalPrice: parseFloat(totalPrice),
                Tax: 0,
                distance: 0,
                Night_Start_Time: null,
                Night_End_Time: null,
                city: vehicleData.city,
                country: vehicleData.country,
                id: `entry-${Date.now()}`,
                vehicle_type: vehicleData.vehicle_type,
                vehicle_model: vehicleData.vehicle_model,
                model_year: vehicleData.model_year,
                seating_capacity: vehicleData.seating_capacity,
                booking_id: null
            };
            
            console.log('Transport booking data:', transportData);
            
            // Create a form to submit the transport data (same as edit.blade.php)
            const form = document.createElement('form');
            form.method = 'POST';
            form.action = "{{ route('orders.transport.select') }}";
            
            // Add CSRF token
            const token = document.createElement('input');
            token.type = 'hidden';
            token.name = '_token';
            token.value = "{{ csrf_token() }}";
            form.appendChild(token);
            
            // Add the transport data as JSON
            const transportDataInput = document.createElement('input');
            transportDataInput.type = 'hidden';
            transportDataInput.name = 'transport_data';
            transportDataInput.value = JSON.stringify([transportData]); // Wrap in array
            form.appendChild(transportDataInput);
            
            // Add basic form fields
            const basicData = {
                tour_id: tourId,
                type: "entry_port",
                agent_id: agentId,
